window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-12"]={"block":"med:med-clinica-medica-med-clm-12","label":"MED · MED CLM 12","count":474,"questions":[{"id":"med-clinica-medica-med-clm-12-345446","number":"345446","sourceNumber":"345446","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O exame cuidadoso dos olhos é de extrema utilidade na avaliação clínica do paciente\ncomatoso. O achado de pupilas simétricas e muito pequenas é sugestivo de:","options":{"A":"Lesão pontina.","B":"Hérnia de uncus.","C":"Síndrome seratoninérgica.","D":"Compressão do terceiro par craniano."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-345448","number":"345448","sourceNumber":"345448","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem de 32 anos apresenta episódio súbito de cefaleia intensa e evolui com redução\ndo nível de consciência em poucas horas. No\nexame físico apresenta sinais de irritação meníngea e\nparalisia do terceiro par craniano à esquerda com midríase e perda do reflexo fotomotor ipsilateral.\nO médico que o atende solicita tomografia computadorizada do crânio na suspeita clínica de se\ntratar de hemorragia subaracnóidea a partir da artéria.","options":{"A":"Cerebral anterior.","B":"Cerebral média.","C":"Carótida posterior.","D":"Comunicante anterior."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-345459","number":"345459","sourceNumber":"345459","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Demência é um quadro clínico em que ocorre perturbação de múltiplas funções\ncognitivas e se faz presente na vida de\nmuitos idosos. Sobre esse tema, assinale a alternativa\nCORRETA:","options":{"A":"A Doença de Pick tem início pré-senil (a partir dos 45 anos).","B":"Hemorragias não se configuram como uma etiologia das Demências Vasculares.","C":"Os principais tipos de Demências Vasculares é Demência de Lewy.","D":"Infecções pelo HIV e sífilis são causas irreversíveis de demência."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-343808","number":"343808","sourceNumber":"343808","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma das ações de prevenção aplicadas na Atenção Primária é o rastreamento de\ndoenças na população. Essa é uma das\nestratégias mais eficazes para diagnóstico de\ndeterminados tipos de câncer, como os de Mama e Colo de Útero. Sobre o conceito de\nrastreamento, assinale a alternativa correta entre as disponíveis abaixo.","options":{"A":"Aplicação de testes diagnósticos quando o paciente inicia algum sintoma (horizonte clínico).","B":"Aplicação de testes em pessoas hospitalizadas com sintomas difusos.","C":"Aplicação de testes para diagnóstico de neoplasias malignas, independente dos sintomas.","D":"Aplicação de testes em pessoas assintomáticas em um grupo populacional definido."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-281089","number":"281089","sourceNumber":"281089","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um determinado paciente com deficit motor focal, que se instalou há uma hora, foi\nsubmetido a uma modalidade específica de RNM encefálica onde foi observado presença de\n\"mismatch\". Isto significa:","options":{"A":"Que o AVE é isquêmico, e que há alto risco para transformação hemorrágica.","B":"Que o AVE é isquêmico, e que há área de penumbra viável.","C":"Que o AVE é hemorrágico.","D":"Que não há lesão vascular isquêmica ou hemorrágica.","E":"Que há sinais de envelhecimento encefálico desproporcional à faixa etária do paciente."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-283285","number":"283285","sourceNumber":"283285","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O protocolo SPIKES é utilizado na prática médica para:","options":{"A":"Estabelecer prognostico em paciente oncológico.","B":"Acompanhamento clínico de pacientes com leucemias agudas.","C":"Escore prognostico em UTls.","D":"Comunicação de más notícias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-281107","number":"281107","sourceNumber":"281107","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 68 anos, diabética e hipertensa, em uso de metformina e enalapril dá\nentrada no pronto socorro por 5 horas de\nevolução de hemiparesia à direita, associada a afasia.\nTomografia de crânio normal na admissão. Assinale a assertiva que contém o território vascular e\nconduta inicial corretos.","options":{"A":"Artéria cerebral média esquerda, trombólise.","B":"Artéria cerebral média esquerda, ácido acetil salicílico 300mg.","C":"Artéria cerebral anterior esquerda, trombólise.","D":"Artéria cerebral anterior esquerdaa, ácido acetil salicílico 300mg.","E":"Artéria basilar, anticoagulação com varfarina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-281111","number":"281111","sourceNumber":"281111","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma preocupação a se ter com a população com idade acima de 65 anos é o maior\nnúmero de ocorrências de efeitos adversos com eventuais drogas em uso. Isso se deve a um\nconjunto de fatores causais. Com base nessas informações, assinale a alternativa que apresenta\num fator causal.","options":{"A":"Elevada incidência de tumores.","B":"Doses maiores, que sempre devem ser usadas, para surtir o efeito desejado.","C":"Infecções de repetição muito comum.","D":"Inapetência, que ocorre em 90% desses indivíduos.","E":"Metabolismo das drogas alterado com a idade."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-281168","number":"281168","sourceNumber":"281168","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Os pacientes portadores de doença arterial carotídea podem apresentar manifestações\nclínicas com graus variados, exceto:","options":{"A":"placas de Hollenhorst.","B":"isquemia cerebral ipsilateral.","C":"ataque isquêmico transitório.","D":"afasia quando ocorre no lado esquerdo.","E":"hematoma cerebral intra parenquimatoso."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-283361","number":"283361","sourceNumber":"283361","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"No ambulatório de atendimento à Saúde do Idoso realizar a AGA - Avaliação Geral\nAmpla constitui a base de um bom atendimento geriátrico. Várias escalas são usadas nesse\natendimento, visando à caracterização de problemas cognitivos, função, humor, marcha e\ngraduação de quadros de demências. Sobre essas escalas assinale a alternativa correta:","options":{"A":"O mini exame do estado mental (MEEM) é um instrumento extremamente útil na triagem\ncognitiva por ser simples e de fácil avaliação\nneste exame avaliamos os atributos psíquicos de\nOrientação, Memória, Evocação, Linguagem e Humor.","B":"O instrumento APGAR de FAMÍLIA é uma escala que serve para refletir a experiência do idoso\ncom seus relacionamentos mais próximos. Quando temos um resultado menor que três pontos\ncaracterizamos uma deficiência acentuada desse suporte familiar para o paciente geriátrico.","C":"A escala de Katz é uma das mais utilizadas na geriatria e avalia a independência em atividades\ninstrumentais de vida diária.","D":"Teste do relógio é um teste de rastreio que avalia as funções executivas e habilidade\nvisuoespacial e com pontuação de 0 a 10 pontos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-247143","number":"247143","sourceNumber":"247143","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Aneurisma de artéria cerebral comunicante posterior, quando expande ou sangra,\ncostuma comprimir o:","options":{"A":"V nervo craniano.","B":"IV nervo craniano.","C":"III nervo craniano.","D":"VI nervo craniano.","E":"VII nervo craniano."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-247150","number":"247150","sourceNumber":"247150","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"No atendimento de um paciente com acidente vascular cerebral isquêmico na fase\naguda, pode-se afirmar que:","options":{"A":"A hipotensão arterial é rara, porém deve ser prontamente revertida.","B":"A antibioticoprofilaxia é recomendada devido ao risco de aspiração pulmonar.","C":"A temperatura corporal elevada não é um fator relacionado com pior prognóstico.","D":"O decúbito do paciente deve ser mantido a 90 graus para reduzir as chances de edema cerebral\nprecoce.","E":"As soluções glicosadas devem ser usadas de rotina a fim de evitar hipoglicemia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-247151","number":"247151","sourceNumber":"247151","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual tétrade clássica da doença de Parkinson?","options":{"A":"Bradicinesia, demência, polineuropatia e ataxia de marcha.","B":"Tremor de ação, irritabilidade, transtornos de memória e hiperreflexia.","C":"Transtornos de memória, afasia apraxia e transtornos de comportamento.","D":"Tremor de repouso, bradicinesia, rigidez muscular e alteração de reflexos posturais.","E":"As soluções glicosadas devem ser usadas de rotina a fim de evitar hipoglicemia."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-251907","number":"251907","sourceNumber":"251907","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente ASM, analfabeta, 80 anos, avaliada na UBS do Universitário no dia de\natendimento da Saúde do Idoso pela\npreceptora da unidade relata antecedentes de DM, HAS,\nOsteoporose e Osteoartrose de joelhos. - Inventário medicamentoso: omeprazol em jejum,\nIbuprofeno 8/8 h se dor, Hidroclorotiazida 25 mg/dia, atenolol 50 mg/dia, Glibenclamida 5 mg 3 x dia\nMetformina 850mg 3x dia, AAS 100mg/dia, Clonazepam 0,5mg a noite e Amitriptilina 25 mg a noite,\nsinvastatina20 mg, ômega 3 e , alendronato de sódio 70 mg, cálcio e vitamina D. - Queixa Principal:\ndor nos joelhos e dificuldade para deambulação há aproximadamente 2 anos. Interrogatório\nSintomatológico: fadiga, astenia, urgência miccional, dor no corpo tudo, rigidez articular matinal,\ndesmotivação, insônia, diminuição de memória recente e tonturas diárias. Realizado AGA\n(avaliação geriátrica ampla/Funcional - Global) encontrando: Miniavaliação do estado mental\n(MEEM): 9 pontos. Escala geriátrica de depressão (EGD) 11 pontos, AIVD: 14/27 precisa de ajuda\npara uso de telefone, gerenciar medicamentos, finanças, preparar refeições e transporte. AVD: 2/6:\n\n+ continência e alimentação. Get up and GO: 33 segundos. Deambula com dispositivoauxiliar da\nmarcha IMC: 23Kg/m2 CP(circunferência da panturrilha)= 33 cm; Segundo o resultado da\nAvalização Funcional da paciente, que lista de problemas e ou Síndromes Geriátricas estão\npresente nesta paciente no momento da avaliação, exceto:","options":{"A":"Depressão, Insuficiência Cognitiva.","B":"Dependência, Risco de quedas.","C":"Polifarmácia, Medicamentos inapropriados.","D":"Desnutrição, Imobilidade, delirium."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-251913","number":"251913","sourceNumber":"251913","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A campanha Novembro Azul é uma iniciativa de entidades médicas e filantrópicas que\ntem recebido apoio de empresas, organizações\nnão governamentais e secretarias de saúde que\ntalvez não conheçam os problemas que envolvem o rastreamento do câncer de próstata. Em\nprimeiro lugar, rastreamento significa uma ação feita para identificar uma doença (ou fator de\nrisco)\nantes que ela se manifeste ou piore, com o objetivo de diminuir o adoecimento e a mortalidade - ou\nseja, fazer as pessoas viverem mais e melhor. É o que fazemos ao pedir que uma pessoa\naparentemente saudável saia da sua casa e faça, por exemplo, uma sorologia de HIV ou uma\ncoleta de papanicolau. Embora se diga que o Novembro Azul visa estimular o homem a cuidar da\nsua saúde e a realizar exames preventivos, o foco no câncer de próstata fica evidente nos sítios da\ncampanha, em seu material informativo e na divulgação pela mídia. A campanha afirma que \"a\núnica forma de garantir a cura do câncer de próstata é o diagnóstico precoce\", e recomenda que\ntodos os homens com mais de 50 anos - ou 45, no caso de negros e parentes de primeiro grau de\nindivíduos que tiveram a doença - procurem anualmente um urologista para fazer o exame de toque\nretal e a dosagem de PSA (antígeno prostático específico) no sangue. Essa, entretanto, não é a\nrecomendação de respeitadas instituições nacionais e estrangeiras. Em 2012, o United States\nPreventive Services Task Force (USPSTF) passou a contraindicar o rastreamento de câncer de\npróstata baseado em PSA para homens estadunidenses de qualquer idade. Assinale a alternativa\ncorreta de acordo com o texto acima: I. Em 2013, o Instituto Nacional de Câncer (INCA) passou a\nrecomendar que não se organizassem programas de rastreamento para o câncer da próstata, e\nque homens que demandassem espontaneamente a realização de exames de rastreamento\nfossem informados por seus médicos sobre os riscos e benefícios associados a esta prática, \"por\nexistirem evidências científicas de boa qualidade de que o rastreamento do câncer de próstata\nproduz mais dano do que benefício\". Na verdade, desde 2010, o Ministério da Saúde já duvidava\nda indicação desses exames, por não haver evidências científicas suficientes para justificá-lo.\n\nOutras entidades reconhecidas internacionalmente, como o Canadian Task Force on Preventive\nHealth Care, o American Academy of Family\nPhysicians8 e o United Kingdom National Screening\n\nComittee, fazem recomendações semelhantes. II. Os homens devem ser vistos de forma integral, e\na eles devem ser dirigidos cuidados\npreventivos adequados, de forma regular. A Sociedade\nBrasileira de Medicina de Família e Comunidade considera que os homens, de fato, precisam dar e\nreceber mais atenção à sua saúde, mas as evidências científicas mais recentes deixam claro que\nisso não deve ser feito através da dosagem do PSA ou realização de toque retal em pessoas que\nnão apresentam qualquer sintoma. III. Fazer PSA com ou sem toque retal não diminui a mortalidade\ngeral dos homens, e muda muito pouco a mortalidade específica por câncer de próstata.","options":{"A":"Todas as alternativas estão corretas.","B":"Somente I e II estão corretas.","C":"Apenas II e III estão corretas.","D":"Todas estão incorretas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-217644","number":"217644","sourceNumber":"217644","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O diagnóstico de hidrocefalia de pressão normal é improvável quando o paciente\napresenta:","options":{"A":"Papiledema.","B":"Apraxia.","C":"Incontinência urinária.","D":"Demência."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-217650","number":"217650","sourceNumber":"217650","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 92 anos portadora de doença de Parkinson, com múltiplas contraturas,\nafasia, quadro demencial, má conservação de\ndentes e incontinência urinária e fecal, foi internada\npara tratamento de úlcera por pressão com infecção secundária, submetida a debridamento\ncirúrgico. Essas condições permitem afirmar que a paciente apresenta:","options":{"A":"Síndrome de fragilidade.","B":"Síndrome de imobilidade.","C":"Demência por corpúsculos de Lewy.","D":"Hidrocefaleia de pressão normal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-217654","number":"217654","sourceNumber":"217654","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente idosa de 87 anos foi trazida pela filha ao posto de saúde do Universitário após\nter sofrido duas quedas sem maiores\nconsequências traumáticas, enquanto andava no período\ndiurno dentro de sua residência. Apresentou IMC = 19, critérios para a síndrome de fragilidade e\nfazia uso de rivastigmina, memantina, losartana, vitamina D e aspirina. Segundo a filha, o\napartamento havia sido adaptado para a maior segurança e conforto da idosa, com colocação de\nbarras de apoio no banheiro e corrimão no corredor. Visando estabelecer estratégias para a\nredução de riscos relacionados à futuras quedas, a intervenção mais efetiva a ser indicada é:","options":{"A":"Retirar os tapetes da casa e evitar o uso de cera nos pisos para reduzir os fatores de risco\nextrínsecos para queda.","B":"Suspender por tempo indeterminado o uso da aspirina para evitar os riscos de um possível\nsangramento após trauma.","C":"Iniciar um programa regular e orientado de exercícios físicos, visando à redução dos fatores de\nrisco intrínsecos para queda.","D":"Monitorar e anotar diariamente os níveis de pressão arterial na intenção de minimizar a\npredisposição para hipotensão."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-182689","number":"182689","sourceNumber":"182689","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Todos abaixo são fatores de risco modificáveis para demência e comprometimento\ncognitivo leve, EXCETO:","options":{"A":"Hipertensão ou diabetes.","B":"Síndrome metabólica ou dislipidemia.","C":"Obesidade e sedentarismo a partir da meia-idade.","D":"Tabagismo e histórico familiar."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-159077","number":"159077","sourceNumber":"159077","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 64 anos, com diagnóstico de câncer de pulmão, em tratamento\npaliativo, faz acompanhamento com o médico de\nfamília e comunidade em uma Unidade Básica de\nSaúde. Com relação à analgesia neste caso, qual das alternativas está CORRETA?","options":{"A":"O uso de morfina deve ser evitado ao máximo, pois pode desenvolver tolerância e dependência.","B":"A associação fixa da codeína a analgésicos não opióides é farmacologicamente inaceitável.","C":"Deve-se evitar o uso de laxativos, pois os mesmos podem comprometer o estado geral do\npaciente.","D":"O uso de amitriptilina poderia ser indicado pela sua ação analgésica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-135967","number":"135967","sourceNumber":"135967","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual pneumoniconiose está também associada ao mesotelioma da pleura e peritônio,\ncâncer de pulmão, câncer de laringe, e\npossivelmente a cânceres gastrintestinais?","options":{"A":"Asbestose;","B":"Pneumoniconioses dos mineiros de carvão;","C":"Silicose;","D":"Beriliose."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-108807","number":"108807","sourceNumber":"108807","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sobre as exacerbações da DPOC, assinale a alternativa INCORRETA:","options":{"A":"Com o aumento no volume e/ou purulência do escarro, a antibioticoterapia está associada a um\nbenefício mensurável;","B":"A cultura do escarro geralmente é útil, e o tratamento empírico não deve ser a regra;","C":"Nas exacerbações graves, a esteroidoterapia sistêmica mostrou promover uma recuperação\nrelativamente rápida e o equivalente a 40 mg\nde prednisona por dia por 10 a 14 dias é justificável;","D":"Em paciente de alto risco, levofloxacina 500 mg por dia por 7 a 10 dias, pode ser aconselhável."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-108667","number":"108667","sourceNumber":"108667","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"No ambulatório da UFS Universitário, a médica de família e comunidade atende uma\ncriança de 10 anos com crise asmática. Após conduta para estabilização clínica do quadro, a\nmesma classifica o quadro como asma persistente moderada. Qual é a melhor conduta a seguir\npara o tratamento de manutenção deste caso?","options":{"A":"ß2 inalatório de longa duração;","B":"Corticoide inalatório em doses baixas;","C":"ß2 inalatório de longa duração + corticoide inalatório em dose alta + corticoide oral.","D":"ß2 inalatório de longa duração + corticoide inalatório em dose baixa a moderada."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-84450","number":"84450","sourceNumber":"84450","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de cinco anos de idade, diagnóstico pregresso de asma intermitente chega ao\nPronto-Socorro expressando frases incompletas e parciais dizendo que: \"não consegue respirar\ndireito\". Ao exame apresenta retrações subcostais acentuadas, sibilos difusos, frequência\nrespiratória de 55 irpm, frequência cardíaca de 120 bpm e saturação de O2 de 95%. Segundo a\nDiretriz Brasileira para o manejo da asma, devemos iniciar:","options":{"A":"Beta-2 agonista por nebulização ou spray com espaçador.","B":"Corticosteroide oral e Brometo de Ipatrópio.","C":"Nebulização com Beta-2 agonista e Corticosteroide endovenoso.","D":"Nebulização com Beta-2 agonista e corticosteroide por via oral.","E":"Brometo de Ipatrópio."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-84531","number":"84531","sourceNumber":"84531","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"As condições abaixo contraindicam a prescrição de quimioprofilaxia para\nTromboembolismo Venoso em pacientes clínicos, EXCETO:","options":{"A":"Plaquetas < 100.000/mm³.","B":"Hipertensão arterial sistêmica não controlada (PAS > 200 mmHg).","C":"Insuficiência renal persistente (TFG < 30 ml/min).","D":"Punção liquórica nas últimas 24 horas.","E":"Doença neoplásica."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-50047","number":"50047","sourceNumber":"50047","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente do sexo feminino, 26 anos, refere dor torácica posterior à esquerda\nventilatório-dependente há aproximadamente 30\ndias. Também refere febre baixa com períodos de\nastenia e mal-estar geral recorrente. Nega etilismo e tabagismo. História patológica pregressa -\nepisódios de infecções de pele recorrentes nos últimos meses. Ao exame físico: Aparelho\nrespiratório - murmúrio vesicular abolido em 2/3 do pulmão esquerdo, frêmito toracovocal diminuído\nem base de pulmão esquerdo; aparelho cardiovascular - sem anormalidades; pele - lesões\neritematosas ovaladas pruriginosas de diversos tamanhos em braços e pernas. Foi realizado RX\ntórax que revelou: imagem hipodensa (velamento total) na base de pulmão esquerdo, com\nmediastino e traqueia centrada e área cardíaca de tamanho normal. Com base nos dados clínicos\napresentados, responda: Imaginemos que os resultados para o provável exame acima solicitado\nfossem: TC TÓRAX - Imagem hipodensa em terço médio e inferior do pulmão esquerdo com\ndensidade próxima de 1; Broncoscopia - Sem alterações patológicas no estudo; PPD - 0 mm;\nAnálise do líquido pleural - Proteínas totais no sangue - 5,0, proteínas no líquido pleural- 2,8;\nleucometria normal sem linfocitose; histopatológico em andamento. Qual seria sua conduta\nterapêutica com base nos exames disponíveis e na anamnese do caso clínico?","options":{"A":"Prednisona 1 mg/kg diariamente;","B":"Rifampicina, Isoniazida, Etambutol e Pirazinamida;","C":"Moxifloxacina 400 mg/dia;","D":"Furosemida 80 mg/dia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-37074","number":"37074","sourceNumber":"37074","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 30 anos tem procurado atendimento médico semanal desde que se mudou\npara São Paulo há quatro meses,\nqueixando-se de dispneia intensa e chiado que melhoram\nparcialmente com medicamentos que usa no PS, persistindo com sintomas inclusive à noite. Refere\nque desde a infância tem esses sintomas, mas eram esporádicos. Qual a proposta medicamentosa\npara esse paciente?","options":{"A":"Corticosteroide inalatório e teofilina.","B":"ß2-agonista inalatório de longa duração e corticosteroide inalatório.","C":"Corticosteroide oral e ß2-agonista inalatório de longa e curta duração.","D":"ß2-agonista inalatório de longa duração e teofilina.","E":"Brometo de ipatrópio e ß2-agonista inalatório de curta duração."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-37079","number":"37079","sourceNumber":"37079","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A avaliação anatomopatológica da gravidade da bronquite crônica é feita através do\níndice de Reid, que vem a ser:","options":{"A":"O número de glândulas mucosas por cm² num brônquio fonte.","B":"A relação entre o número de glândulas mucosas e o número de células caliciformes em\nbrônquios segmentares.","C":"A relação entre o número de células caliciformes e o número de células epiteliais nas grandes\nvias aéreas.","D":"A relação entre a espessura das glândulas brônquicas e a espessura da parede brônquica, nas\ngrandes vias aéreas.","E":"Relação entre VEF1 e CVF."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-29413","number":"29413","sourceNumber":"29413","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O tratamento da crise de asma inclui todos os medicamentos abaixo, exceto:","options":{"A":"Fenoterol inalatório.","B":"Terbutalina endovenosa","C":"Brometo de ipratrópio inalatório.","D":"Corticoide inalátorio.","E":"Quetamina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-341085","number":"341085","sourceNumber":"341085","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O Brasil envelhece de forma rápida e intensa. Segundo o Censo IBGE de 2010, a\npopulação idosa brasileira é composta por 23\nmilhões de pessoas, totalizando 11,8% da população\ntotal do País. A expectativa de vida para a população brasileira aumentou para 74 anos, sendo 77,7\nanos para a mulher e 70,6 anos para o homem. Considerando os conceitos necessários para a\nformulação das metas das políticas de saúde para a terceira idade, pode-se dizer que:","options":{"A":"A longevidade está diretamente relacionada à qualidade de vida.","B":"Envelhecimento Ativo envolve os mesmos conceitos de Envelhecimento Saudável.","C":"Autonomia do idoso refere-se, principalmente, à capacidade de executar os atos da vida diária.","D":"Autonomia e Independência são conceitos correlatos mas diferentes em Gerontologia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-343219","number":"343219","sourceNumber":"343219","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A radiografia do tórax pode ainda ser utilizada como método de triagem no diagnóstico\nda tuberculose:","options":{"A":"Notadamente em populações confinadas, cuja incidência da doença é extremamente baixa.","B":"Exceto em populações confinadas, cuja incidência da doença é extremamente elevada.","C":"Notadamente em populações confinadas, cuja incidência da doença não é elevada.","D":"Notadamente em populações confinadas, cuja incidência da doença é extremamente elevada."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-315206","number":"315206","sourceNumber":"315206","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um infarto da artéria cerebelar posteroinferior tem como sintomas principais:","options":{"A":"Paralisia hemicorporal.","B":"Monoplegia.","C":"Vertigem e desequilíbrio.","D":"Afasia.","E":"Hipertonia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-275974","number":"275974","sourceNumber":"275974","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A doença de Parkinson se caracteriza por se tratar de distúrbio neurológico\nestigmatizado predominantemente pela presença de tremor\ninvoluntário de difícil controle. Que\nparte do cérebro e qual o neurotransmissor envolvido na patologia?","options":{"A":"Hipocampo e noradrenalina.","B":"Amigdala e serotonina.","C":"Substância negra e dopamina.","D":"Córtex cerebral e acetilcolina.","E":"Nenhuma das alternativas anteriores."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-278100","number":"278100","sourceNumber":"278100","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Assinale a alternativa correta em relação ao uso de escalas para manejo da dor em\npediatria.","options":{"A":"Ainda não há, na literatura, um consenso quanto ao uso rotineiro de escalas para avaliação da\ndor nas UTIs pediátricas.","B":"É possível utilizar com crianças as mesmas escalas intuídas para adultos, pois todas são\nvalidadas para todas as faixas etárias.","C":"O autorrelato e as escalas numéricas e de faces são muito úteis para manejo e avaliação da dor.","D":"As escalas de faces são consideradas padrão ouro para a avaliação da dor, uma vez que são\nmuito uteis e de fácil entendimento na faixa etária pediátrica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-249410","number":"249410","sourceNumber":"249410","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A endarterectomia de carótida é uma cirurgia consagrada no tratamento da isquemia\ncerebral de origem extracraniana. Sobre suas complicações, é correto afirmar:","options":{"A":"A lesão intra-operatória do nervo vago causa alteração motora de metade da língua.","B":"A lesão do nervo hipoglosso pode levar a regurgitações alimentares, com broncoaspiração e\npneumonia de repetição.","C":"O ramo mandibular do nervo facial quando lesado leva a dificuldade em emitir notas de timbre\nagudo e resulta em fatigabilidade da voz.","D":"A microembolização cerebral pode levar a acidente vascular encefálico isquêmico."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-249419","number":"249419","sourceNumber":"249419","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sobre isquemia cerebral de origem extracraniana, marque a correta:","options":{"A":"A arterite de Takayasu pode levar a isquemia cerebral extracraniana, sendo mais comum em\nhomens a partir da sexta década de vida.","B":"A aterosclerose não é causa comum de ataque isquêmico transitório e de acidente vascular\ncerebral.","C":"Na displasia fibromuscular a cirurgia de endarterectomia de carótidas é sempre o melhor\ntratamento.","D":"A displasia fibromuscular ocorre mais frequentemente em pacientes do sexo feminino."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-212167","number":"212167","sourceNumber":"212167","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente A.B.S., 75 anos, sexo feminino, foi à consulta médica acompanhada da filha\nprimogênita, que relata que a mãe iniciou quadro de esquecimento há 2 anos, principalmente para\nacontecimentos recentes. O quadro foi piorando de forma progressiva e, no momento, apresenta\nincapacidade de executar as atividades diárias, realizadas previamente. Após avaliação clínica, o\nmédico suspeitou de um quadro de demência. Dadas as afirmativas em relação ao diagnóstico\ndiferencial das demências: I. A hidrocefalia comunicante normobárica é uma causa de demência\nnão tratável. II. A principal hipótese diagnóstica para o quadro clínico descrito acima é a doença\nde\nPick. III. A doença de Alzheimer é a causa mais comum de demência e ocorre em mais de 50% dos\ncasos. IV. Deve ser solicitado inicialmente TSH, T4L, VDRL, dosagem sérica de vitamina B12 e TC\nde crânio, para exclusão de causas tratáveis. Verifica-se que está(ão) CORRETA(S):","options":{"A":"III, apenas.","B":"I e II, apenas.","C":"III e IV, apenas.","D":"I, II e IV, apenas.","E":"I, II, III e IV."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-201765","number":"201765","sourceNumber":"201765","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 78 anos chega à emergência com paralisia em dimídio esquerdo e disfasia.\nEncontra-se lúcido, PA = 240 x 135 mmHg; FC = 98 bpm e SatO2 = 96%. Qual a conduta mais\napropriada para o controle da pressão arterial?","options":{"A":"Metropolol em bolus e nitroprussiato de sódio em bomba de infusão, mantendo PA em 170 x 110\nmmHg.","B":"Captopril SL e Furosemida EV para queda imediata da PA.","C":"Reduzir imediatamente a PA para níveis abaixo de 140 x 90 mmHg com a medicação que\nestiver ao alcance.","D":"Nitroprussiato de sódio em bomba de infusão para manter a PA < ou = a 120 x 80 mmHg.","E":"Fazer medicação oral, observando o que já toma em casa e aguardar o resultado da tomografia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-181424","number":"181424","sourceNumber":"181424","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O perfil demográfico modificou-se nas últimas décadas, principalmente em decorrência\ndo aumento da longevidade e da redução das taxas\nde mortalidade. Segundo o último censo\ndemográfico do IBGE, a quantidade de pessoas com idade acima de 60 anos no Brasil é de mais\nde 20 milhões (10,8% da população). Assinale a alternativa CORRETA sobre o idoso:","options":{"A":"A pele do idoso tem mais elasticidade e menos flexibilidade.","B":"Há aumento da sensibilidade respiratória à hipóxia e hipercapnia.","C":"Há aumento da complacência da parede torácica e redução da complacência pulmonar.","D":"Testes de função hepática normais significam\nnecessariamente metabolismo normal das drogas.","E":"O clearance de creatinina diminui com a idade. A creatinina não aumenta, uma vez que o\nmetabolismo muscular também está reduzido."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-181415","number":"181415","sourceNumber":"181415","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Reconhecido como uma forma inovadora de assistência à saúde, o Cuidado Paliativo\nvem ganhando espaço no Brasil, especialmente na\núltima década. Sobre Cuidados Paliativos na\nAtenção Primária, assinale a alternativa correta.","options":{"A":"Um das estratégias para discutir casos de pacientes em Cuidados Paliativos é o Projeto\nterapêutico singular, que consiste em consultar um especialista para passar recomendações\nespecíficas para aqueles pacientes.","B":"A definição de Cuidados Paliativos (CP) foi feita pela Organização Mundial de Saúde como\nsendo uma abordagem destinada a melhorar a\nqualidade de vida do paciente diante da fase\nterminal de uma doença.","C":"Os CP podem ser desenvolvidos em ambiente ambulatorial, hospitalar e no próprio domicílio do\npaciente. Entretanto, recomenda-se que a fase terminal da doença aconteça no hospital, devido às\nlimitações da Atenção Primária para cuidar desse paciente.","D":"No contexto domiciliar, a equipe de Atenção Primária seria responsável pelo suporte ao paciente\ne à família, de maneira a garantir o\ncontrole dos sintomas e a dignidade no processo de morte. A\narticulação da rede de cuidado é fundamental para garantir esse suporte.","E":"Apesar de algumas especialidades médicas possuírem área de atuação em Cuidados Paliativos,\nela ainda não é reconhecida no Brasil como\nespecialidade; e mesmo a Medicina de Família e\nComunidade não tendo essa área de atuação, é essencial que o médico e sua equipe conheçam\nesse tipo de paciente para ajudá-lo a controlar os principais sintomas das doenças ameaçadoras,\nde forma disciplinar."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-181396","number":"181396","sourceNumber":"181396","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 72 anos comparece à consulta com perda de memória progressiva e\ndificuldade para encontrar as palavras, há cerca de um ano de evolução. Qual é a exploração mais\nútil para\n\ncaracterizar o tipo de déficit cognitivo que apresenta?","options":{"A":"Ressonância nuclear magnética cerebral.","B":"Tomografia computadorizada do crânio.","C":"Avaliação neuropsicológica.","D":"Eletroencefalograma.","E":"Biópsia cerebral."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-161268","number":"161268","sourceNumber":"161268","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual dos fatores a seguir NÃO é determinante da decisão a respeito de controle\npressórico no Acidente Vascular Encefálico (AVE)?","options":{"A":"Tempo de instalação.","B":"Indicação farmacológica.","C":"Aspecto tomográfico.","D":"Glasgow."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-161283","number":"161283","sourceNumber":"161283","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente deu entrada na sala de emergência com dificuldade respiratória e rebaixada.\nApresentava perda motora e incoordenação dos movimentos. Apresenta PA de 200 x 110 mmHg. A\nhipótese diagnóstica inicial foi a de AVC. Diante de tal quadro, assinale a alternativa contendo a\nconduta inicial MAIS adequada.","options":{"A":"Iniciar atendimento com ABCDE.","B":"Caso menor que 4 horas propor trombólise.","C":"Para pacientes com PAS entre 150 e 220 mmHg e sem contraindicação para o tratamento, a\nredução aguda da PAS para 140 mmHg é segura e pode ser eficaz para melhorar o desfecho\nfuncional.","D":"Inicialmente solicitar Tomografia de Crânio antes de qualquer conduta inicial."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-161271","number":"161271","sourceNumber":"161271","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente hipertenso mal controlado, rebelde ao uso de medicação diária que é\nPropranolol, foi trazido ao hospital com intensa cefaleia e perda motora do lado direito do corpo.\nSua pressão era de 210 x 120 mmHg. Foi realizado Tomografia de Crânio que demonstrava\nsangramento. Diante de tal situação, marque a opção INCORRETA.","options":{"A":"Para pacientes com PAS entre 150 e 220 mmHg e sem contraindicação para o tratamento, a\nredução aguda da PAS para 140 mmHg é segura.","B":"Para pacientes com PAS entre 150 e 220 mmHg, a redução aguda da PAS pode ser eficaz para\nmelhorar o desfecho funcional.","C":"Para pacientes com PAS entre 150 e 220 mmHg, a redução aguda da PAS em 1 hora com\ninfusão IV de anti-hipertensivos é benéfica.","D":"Para pacientes com PAS entre 150 e 220 mmHg, a redução da PAS necessita de monitorização\nda PA horária."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-161381","number":"161381","sourceNumber":"161381","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Adulto jovem, masculino, procurou o hospital com intensa cefaleia, descrevendo como\na pior da vida, de forte intensidade,\nacompanhada de desorientação e perdas motoras. Foi\ninicialmente suspeitado de cefaleia secundária, sendo então decidido por realização de tomografia\nde crânio com contraste. Mas essa tomografia não foi inicialmente autorizada para o paciente,\njustificada ADEQUADAMENTE assim:","options":{"A":"Melhor ressonância.","B":"Melhor punção lombar inicial por ser mais sensível.","C":"Necessidade inicial de tomografia comum, sem contraste, pois caso ocorra sangramento,\no potencial extravasamento de contraste piora a\nlesão.","D":"Não é possível o diagnóstico com tomografia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-161147","number":"161147","sourceNumber":"161147","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Marque a opção que NÃO é considerada um fator de risco para Acidente Vascular\nEncefálico em pediatria.","options":{"A":"Doenças hematológicas, como anemia falciforme, leucemias ou linfomas.","B":"Anomalias vasculares, como aneurismas e doença de moyamoya.","C":"Doenças cardíacas congênitas ou adquiridas.","D":"Doenças endocrinológicas, como diabetes mellitus tipo 1 e diabetes insípidus."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-161150","number":"161150","sourceNumber":"161150","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Aponte a opção que apresenta o exame diagnóstico padrão ouro na investigação do\nAcidente Vascular Encefálico.","options":{"A":"Angiografia convencional.","B":"Angiografia por ressonância magnética.","C":"Ultrassonografia de crânio.","D":"Tomografia computadorizada de crânio."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-134838","number":"134838","sourceNumber":"134838","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Indique a alternativa que apresente as características do acometimento por\nTuberculose, no Sistema Nervoso Central.","options":{"A":"Preferência por base de crânio, baixos níveis de glicose no liquor e aumento da proteína\nliquórica.","B":"Preferência por base de crânio, elevados níveis de glicose no liquor e redução da proteína\nliquórica.","C":"Xantocromia e sangramentos.","D":"Sangramentos com hemácias crenadas e redução da proteína liquórica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-134326","number":"134326","sourceNumber":"134326","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente deu entrada no hospital com dispneia e tosse pouco produtiva. Seu exame\nfísico apresenta muitos roncos e sibilus. Refere histórico de ser asmático, mas não utiliza\nmedicação regularmente. Então, é prescrita inalação que deve","options":{"A":"Utilizar oxigênio.","B":"Manter fluxo de pelo menos 8 L/min.","C":"Somente utilizar beta-agonistas de ação curta.","D":"Ser pouco eficiente nesse caso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-134103","number":"134103","sourceNumber":"134103","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Idoso, 68 anos de idade, deu entrada no hospital com rebaixamento do nível de\nconsciência, Glasgow de 11, perda motora no lado esquerdo de início súbito. Sua tomografia de\ncrânio mostra-se dentro da normalidade para a idade. Podemos, assim, considerar que sua\npressão de 190 x 110 mmHg deve nortear a seguinte conduta. Assinale-a:","options":{"A":"Deve ser abaixada toda vez que ultrapassar 180 x 110 mmHg.","B":"Deve ser tolerada até 210 x 120 mmHg.","C":"Depende se a proposta de tratamento é de trombólise ou não.","D":"Independentemente do que ocorrer, irá normalizar em três dias."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-134324","number":"134324","sourceNumber":"134324","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente com histórico de trabalhar em serraria cortando tábuas se queixa de tosse e\nintensa dispneia, vem piorando nos últimos meses. Seu exame físico demonstra tórax em tonel,\nemagrecido. Ausculta com roncos e sibilos. Radiografia com intensa fibrose pulmonar. Indique a\nalternativa contendo a estrutura pulmonar MAIS envolvida com a gênese dessa síndrome.","options":{"A":"Membrana alvéolo capilar.","B":"Pleura visceral.","C":"Poros de Cohn.","D":"Traqueia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-134108","number":"134108","sourceNumber":"134108","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente com quadro de súbita dispneia ocorrida durante esta manhã. Estava\ninternada no hospital por fratura de osso\nlongo do membro inferior direito, aguardando\ncirurgia esta manhã, que acabou não ocorrendo. Apresentava dispneia objetiva com uma\nfrequência de 28 i/min, sua ausculta apresentava apenas raros roncos inspiratórios, praticamente\nsem achados. Sua principal suspeita diagnóstica ficou sendo a de tromboembolismo pulmonar, que\nseria compatível com","options":{"A":"Ecocardiograma com sobrecarga do lado esquerdo do coração.","B":"Radiografia com importante radiopacidade tomando toda uma base pulmonar.","C":"Discreta hipertransparência pulmonar na área afetada pelo embolo.","D":"Eletrocardiograma demonstrando hipertrofia atrial direita."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-134849","number":"134849","sourceNumber":"134849","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Quando classificamos Embolia Pulmonar, devemos entender que a embolização pode\nser decorrente não apenas de trombos, mas de\nqualquer substância, potencialmente. Existe\ncorrelação de fraturas de ossos longos com embolia dita gordurosa, causada pela medula óssea\nque obstrui a pequena circulação. Esta apresenta uma característica típica que é:","options":{"A":"Provocar hipóxia refratária.","B":"Sobrecarregar VD.","C":"Ultrapassar linha média.","D":"Responder bem a trombólise."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-134869","number":"134869","sourceNumber":"134869","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Quando avaliamos quadros asmáticos muito graves, consideramos o seguinte,\ncom EXCEÇÃO do contido em uma alternativa.\nAponte-a:","options":{"A":"O encontro de peak flow menor que 200 indica gravidade.","B":"O encontro de uma PCO2 normal indica que o paciente está melhorando.","C":"Em quadros muito graves ocorre a supressão dos roncos e sibilos.","D":"O não encontro de ausculta de ruídos musicais denota extrema gravidade."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-134858","number":"134858","sourceNumber":"134858","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente feminina de 60 anos de idade, hipertensa crônica inicia quadro de\nintensa dispneia após negligenciar medicações\nambulatoriais de tratamento da hipertensão. Em\nsua avaliação inicial apresenta ausculta com estertores e uma queda da saturação, estando com\n88%. Sua PA está bastante elevada, com 210 X 120 mmHg, fora edema em membros inferiores\nbilateralmente 2+/4+. Diante de tal caso, podemos AFIRMAR que","options":{"A":"Se trata de edema agudo de pulmão hipertensivo, melhor abordagem com Nitroprussiato de\nSódio por melhora pré e pós-carga.","B":"Como paciente está edemaciada, a melhor medicação seria diuréticos tiazídicos.","C":"Caso se utilize diuréticos, esses somente terão efeito na pós-carga a longo prazo.","D":"Se trata de edema agudo de pulmão hipertensivo, sendo melhor utilizar nifedipina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-134037","number":"134037","sourceNumber":"134037","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Escolar de 6 anos, com asma, é avaliado pelo Pediatra em consulta de revisão pós-alta\nhospitalar há 4 semanas, por crise. A criança tem apresentado, nas últimas 4 semanas, sintomas\nnoturnos, limitação das atividades e sintomas diurnos 3 vezes por semana. Segundo as diretrizes\nda Sociedade Brasileira de Pneumologia e Tisiologia, o caso clínico se trata de asma:","options":{"A":"Controlada.","B":"Não controlada.","C":"Parcialmente controlada.","D":"Controlada, se os sintomas noturnos forem menores ou iguais a 2 por semana."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-140180","number":"140180","sourceNumber":"140180","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem, 79 anos de idade, sem comorbidades prévias conhecidas, iniciou\nsubitamente com hemiplegia direita. É trazido\nà emergência por familiares em 30 minutos do início\ndo quadro neurológico. O paciente encontra-se consciente, a pressão arterial é de 175 x 100\nmmHg, apresenta hemiplegia direita e afasia de expressão. É realizada uma tomografia de crânio\nsem contraste que não mostra alterações. Assinale a alternativa que apresenta a conduta\nterapêutica MAIS ADEQUADA:","options":{"A":"Monitorização invasiva da pressão arterial e início de anti-hipertensivo endovenoso.","B":"Controle rigoroso da pressão arterial com medicação endovenosa e heparinização plena.","C":"Repouso e monitorização neurológica intensiva apenas.","D":"Início imediato de anti-hipertensivo e do AAS após 48 horas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-134825","number":"134825","sourceNumber":"134825","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Quanto à Embolia Pulmonar, assinale a alternativa CORRETA.","options":{"A":"É a obstrução aguda parcial ou total da árvore vascular arterial pulmonar por trombos oriundos\nde qualquer ponto da rede arterial sistêmica ou do\ncoração ?direito?.","B":"É a obstrução aguda parcial ou total da árvore vascular arterial pulmonar por trombos\noriundos de qualquer ponto da rede venosa sistêmica ou do coração ?esquerdo?.","C":"É a obstrução aguda parcial ou total da árvore vascular arterial pulmonar por trombos\noriundos de qualquer ponto da rede venosa sistêmica ou do coração ?direito?.","D":"Todas as alternativas estão corretas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-134328","number":"134328","sourceNumber":"134328","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A complicação pós-operatória, conhecida como síndrome de Mendelson, diz respeito à :","options":{"A":"Broncoaspiração.","B":"Trombose venosa.","C":"Reação anafilática.","D":"Insuficiência renal."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-109722","number":"109722","sourceNumber":"109722","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O diagnóstico da Síndrome do Desconforto Respiratório Agudo leva em conta os\nseguintes critérios, EXCETO:","options":{"A":"Auto-PEEP acima de 12 cmH2O.","B":"Relação PaO2/FiO2 < 200.","C":"Infiltrado pulmonar bilateral à radiografia de tórax.","D":"Ausência de sinais clínicos e ecocardiográficos de falência cardíaca."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-110582","number":"110582","sourceNumber":"110582","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Pré-escolar de seis anos de idade chega ao pronto-socorro em crise asmática de início\nhá três horas, após aula de natação.\nAvaliação inicial: FR = 36 irpm, FC = 124 bpm, tiragem\nintercostal de grau moderado, sibilos pulmonares generalizados. A conduta terapêutica de alívio a\nser tomada é:","options":{"A":"Corticoide por via inalatória.","B":"Aminofilina IV.","C":"Beta-2-agonista de curta duração via inalatória.","D":"Corticoide IV.","E":"Beta-2-adrenérgico IV."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-109815","number":"109815","sourceNumber":"109815","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual é a sequência ADEQUADA para tratamento do Estado de Mal Asmático (Asma\nAguda Grave) em Pediatria?","options":{"A":"Inalação contínua, corticoide endovenoso, terbutalina endovenosa, sulfato de magnésio e heliox.","B":"Aminofilina, corticoide endovenoso, inalação contínua, terbutalina endovenosa e heliox.","C":"Inalação contínua, corticoide inalatório, aminofilina, terbutalina subcutânea e sulfato de\nmagnésio.","D":"Inalação contínua, terbutalina subcutânea, sulfato de magnésio e aminofilina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-110011","number":"110011","sourceNumber":"110011","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 12 anos de idade, com asma grave, foi admitido na sala de emergência por\nexacerbação aguda de asma e foi tratado com várias medicações, inclusive albuterol nas últimas\n24h. Você está preocupado que ele possa ter sintomas relacionados com a toxicidade do albuterol.\nQual dos seguintes NÃO é um efeito colateral do albuterol inalado?","options":{"A":"Tremor muscular.","B":"Hipotensão.","C":"Hipocalemia.","D":"Taquicardia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-109735","number":"109735","sourceNumber":"109735","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Criança de três anos de idade apresenta sibilos expiratórios em ambos os pulmões, Tax\n39°C, FR 48 irpm. Após tratamento com broncodilatador administrado por via inalatória, em três\nsessões com intervalos de 20 minutos, e antitérmico, o menor mostrou melhora da sibilância, mas\nmanteve FR 48irpm e apresentou tiragem intercostal, Tax 39°C, alteração do nível de consciência e\nFC 130bpm. Das observações clínicas apresentadas no texto acima, aquela que determina a\nnecessidade de internação imediata do paciente é:","options":{"A":"a tiragem intercostal.","B":"a frequência cardíaca.","C":"o nível de consciência.","D":"a frequência respiratória."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-109745","number":"109745","sourceNumber":"109745","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Avalie as afirmativas e marque (V) para as afirmaçõesVerdadeiras ou (F) para as\nFalsas. ( ) A aminofilina é a droga de\nprimeira escolha na abordagem da crise asmática aguda; ( )\nA hipocalemia é um efeito colateral esperado pela utilização de beta 2 agonistas em altas doses; ( )\nO brometo de ipatrópio tem ação broncodilatadora semelhante aos beta 2 agonistas, podendo ser\nutilizado sozinho no manejo da asma aguda; ( ) Frequência Respiratória de sessenta incursões\nou mais em criança de qualquer faixa etária é indicação inquestionável de internação; ( )\nInternação por bronquiolite, pelo menos três episódios de sibilância nos primeiros seis meses de\nvida, dermatite atópica e história familiar de asma constituem critérios preditivos de\ndesenvolvimento de asma. Assinale a sequência CORRETA.","options":{"A":"F / V / V / V / V.","B":"F / V / F / V / V.","C":"V / V / F / F / V.","D":"F / F / V / V / F."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-110594","number":"110594","sourceNumber":"110594","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente adulto, sexo masculino, foi admitido na UTI devido à insuficiência respiratória\ndecorrente de crise asmática. Permaneceu em entubação orotraqueal prolongada por 20 dias.\n\nApresentou desconforto respiratório progressivo 7 dias após ser extubado, evoluindo para\ncornagem. Qual o diagnóstico e conduta?","options":{"A":"Estenose laringo-traqueal - traqueostomia","B":"Asma persistente e recidivante - Corticoide","C":"Asma persistente e recidivante - Corticoide e broncodilatador","D":"Estenose laringo-traqueal - Broncoscopia rígida para dilatação","E":"NDR"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-86633","number":"86633","sourceNumber":"86633","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente, sexo feminino, 61 anos, costureira, portadora de Diabetes Mellitus em uso de\nhipoglicemiante oral há 10 anos, varizes de membros inferiores, evoluiu com dispneia súbita há 4\nhoras. Chega ao serviço de saúde com saturação de 02 88%, sudorese profusa, taquidispneica. A\nhipótese diagnóstica inicial foi de Tromboembolismo Pulmonar. Sabendo-se que em todas\nafirmativas foram tomadas medidas inicias de suporte básico de vida, assinale a alternativa correta.\nI ? Anticoagulação com marevan e heparina fracionada respectivamente. II ? Anticoagulação com\nheparina e anticoagulante oral a seguir. III ? Anticoagulação com heparina não fracionada,\nantiagregante plaquetário e trombolíticos. IV ? Antiagregantes palquetários, anticoagulação com\nheparina e anticoagulação oral.","options":{"A":"Somente a afirmativa III está correta.","B":"Somente afirmativa II está correta.","C":"Somente afirmativa IV está correta.","D":"Somente afirmativa I está correta.","E":"Todas afirmativas estão erradas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-86849","number":"86849","sourceNumber":"86849","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O agente etiológico mais comum de infecção respiratória aguda bacteriana em\npacientes portadores de DPOC é:","options":{"A":"Staphylococcus aureus;","B":"Mycobacterium tuberculose;","C":"Klebsiela pneumoniae;","D":"Streptococcus pyogenes;","E":"Streptococcus penumoniae."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-108584","number":"108584","sourceNumber":"108584","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A síndrome de Löfgren, constituída por eritema nodoso, artrite de tornozelos e\nadenopatia hilar é característica de:","options":{"A":"Hanseníase.","B":"Tuberculose.","C":"Amiloidose.","D":"Sarcoidose.","E":"Linfoma."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-108587","number":"108587","sourceNumber":"108587","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sobre a abordagem das hemoptises, podemos afirmar, exceto:","options":{"A":"A hemoptise maciça não requer intervenção imediata, primeiramente deve-se procurar a causa\npara poder tratá-la;","B":"As prioridades no tratamento da hemoptise maciça envolvem estabelecer via aérea patente,\nisolar sangramento a um pulmão, manter o paciente em\ndecúbito do lado comprometido;","C":"A hemoptise maciça é uma emergência médica, com elevada taxa de mortalidade. A principal\ncausa de óbito é a asfixia, complicação bem mais frequente e temida do que o choque\nhipovolêmico;","D":"A TC de tórax e a broncoscopia ajudam a identificar o local do sangramento."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-108588","number":"108588","sourceNumber":"108588","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Na DPOC, qual a definição de bronquite crônica?","options":{"A":"É uma condição clínica caracterizada por tosse, dispneia e broncoespasmo nos períodos de\ninverno.","B":"É uma condição clínica definida pela presença de tosse e produção de escarro por pelo menos 3\nmeses ao ano, em 2 anos consecutivos.","C":"É basicamente anatômica e refere-se à dilatação e distorção irreversível dos brônquios, em\ndecorrência da destruição dos componentes elástico e muscular de sua parede.","D":"É uma doença inflamatória crônica que se caracteriza por episódios repetidos de tosse e\nsibilância.","E":"Nenhuma das anteriores."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-108617","number":"108617","sourceNumber":"108617","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 6 anos chega ao consultório, com a mãe dizendo as seguintes queixas.\n\n?Dr, meu filho geralmente fica cansado 2 vezes por semana, falta escola de vez enquanto por\ncausa disso, quando corre muito também fica\ncansado, só melhora com o aerossol passado na\nemergência, e é a noite que geralmente piora?. Com base nisso você classificaria ele como:","options":{"A":"Crise de asma intermitente.","B":"Crise de asma persistente leve.","C":"Crise de asma persistente moderada.","D":"Crise de asma persistente grave.","E":"Portador de fibrose cística."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-362446","number":"362446","sourceNumber":"362446","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"De acordo com as indicações de Cuidados Paliativos, qual desses pacientes NÃO\npreenchem os critérios para receber os serviços?","options":{"A":"CLP, 3 anos, portadora de epidermólise bolhosa grave.","B":"JRN, 43 anos, portadora de câncer de mama com metástase cerebral e óssea, lúcida e\norientada, com controle álgico.","C":"HDM, 23 anos, internado em unidade hospitalar há 3 meses, após acidente automobilístico,\nevoluindo com amputação de membro inferior direito,\ndores crônicas e dor do membro fantasma\nalém depressão.","D":"ABR, 45 anos, realizou tireoidectomia total devido a carcinoma papilífero de tireoide há 15 anos,\nsem metástase."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-327304","number":"327304","sourceNumber":"327304","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Cuidados Paliativos são definidos pela Organização Mundial de Saúde (OMS) como\n\"uma abordagem que melhora a qualidade de vida de\npacientes e seus familiares, que enfrentam\ndoenças que ameaçam a vida. Previne e alivia o sofrimento através da identificação precoce,\navaliação correta e tratamento da dor e outros problemas físicos, psíquicos, sociais, familiares e\nespirituais\". Assinale a alternativa CORRETA a respeito dos Cuidados Paliativos e sua oferta na\nrede de saúde:","options":{"A":"Por se tratarem de uma exclusividade do paciente oncológico, os Cuidados Paliativos devem ser\nofertados sempre no nível terciário.","B":"Os Cuidados Paliativos devem ser oferecidos em todos os níveis de atenção, inclusive na\nAtenção Primária à Saúde.","C":"Os Cuidados Paliativos oferecidos pelas Equipes de Saúde da Família (ESF) são\nnecessariamente de qualidade e resolutividade\ninferiores àqueles ofertados pelo nível hospitalar.","D":"A função das Equipes de Saúde da Família se restringe a identificar os pacientes com\nnecessidade de Cuidados Paliativos e referenciá-los ao nível hospitalar."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-298198","number":"298198","sourceNumber":"298198","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma professora de 57 anos de idade, tabagista, em uso de losartana 50mg ao dia, sem\nantecedencia de diabetes, apresentou quadro súbito de acidente vascular cerebral isquêmico\nevoluindo com afasia e hemiplegia direita de predomínio braquial. A causa mais frequente de\ncardiopatia embolica é:","options":{"A":"Miocardiopatia","B":"Fibrilação atrial","C":"Cardiopatia reumática","D":"Endocardite"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-286788","number":"286788","sourceNumber":"286788","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual das situações clínicas abaixo não constitui indicação para adoção de Cuidados\nPaliativos?","options":{"A":"Mulher, 55 anos, realizou tireoidectomia total devido a carcinoma papilífero de tireoide há 12\nanos, sem metástase.","B":"Criança, 3 anos, portadora de epidermólise bolhosa grave.","C":"Mulher, 43 anos, portadora de câncer de colo uterino invasivo, lúcida e orientada, em uso\nsistemático de analgésicos.","D":"Homem, 28 anos, internado em unidade hospitalar há 3 meses após acidente automobilístico,\nevoluindo com tetraplegia e úlceras de pressão com\ninfecção secundária."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-286789","number":"286789","sourceNumber":"286789","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Ao atender uma pessoa que tem uma doença em fase final, cujo curso progride\ninevitavelmente ao óbito, devem-se aplicar os\ncuidados propostos para o atual estágio da doença.\nEsses cuidados podem ser descritos por: I. Aliviar o sofrimento físico e melhorar os sintomas. II.\nSatisfazer as necessidades sociais e espirituais. III. Indicar o tratamento de acordo com o\nprotocolo\nclínico aconselhado para a doença de base. Assinale a alternativa correta:","options":{"A":"Somente a afirmativa II está correta.","B":"Somente a afirmativa III está correta.","C":"Somente as afirmativas I e III estão corretas.","D":"Somente as afirmativas I e II estão corretas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-252216","number":"252216","sourceNumber":"252216","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 56 anos de idade com antecedência de hipertensão arterial sistêmica,\ndislipidemia e diabetes, apresentou acidente vascular encefálico agudo. Ao exame clínico\nneurológico, foi observado ptose palpebral e midríase, ambas à esquerda com acuidade visual\npreservada, e hemiparesia incompleta e proporcionada à direita. Este paciente apresenta lesão\nno(a):","options":{"A":"Ponte.","B":"Mesencéfalo.","C":"Bulbo.","D":"Lobo frontal esquerdo."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-256581","number":"256581","sourceNumber":"256581","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Quais as principais causas de EXSUDATO pleural (doenças que costumam cursar com\nderrame pleural do tipo exsudato)","options":{"A":"Insuficiência cardíaca e doenças infecciosas (pneumonias e tuberculose)","B":"Neoplasias e doenças infecciosas (pneumonias e tuberculose)","C":"Insuficiência cardíaca e colagenoses","D":"Embolia Pulmonar e doenças infecciosas (pneumonias e tuberculose)"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-256592","number":"256592","sourceNumber":"256592","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente com quadro agudo de AVC secundário a trombose, a artéria cerebral\nmédia à esquerda, segmento M1, apresentará qual exame neurológico mais provável?","options":{"A":"Hemiplegia e hipotonia à direita, associada a afasia.","B":"Hiperreflexia e hipertonia à direita.","C":"Paralisia facial esquerda acometendo o terço inferior da face e hemianestesia à direita.","D":"Hemiplegia direita e anosognosia esquerda."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-252292","number":"252292","sourceNumber":"252292","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um dos princípios que deve nortear a implementação de um programa de rastreamento\nde doenças é:","options":{"A":"Se a doença tiver uma evolução rápida e alta taxa de mortalidade, o programa deve ser\ninstituído pela magnitude do problema, independente de outros fatores.","B":"A história natural da doença ou do problema clínico deve ser bem conhecida.","C":"Os programas de rastreamento, em geral, têm o potencial de trazer mais benefícios que danos\nàs populações submetidas aos testes.","D":"O teste de rastreamento deve detectar alteração na fase clínica da doença."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-208380","number":"208380","sourceNumber":"208380","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente foi diagnosticado como tendo síndrome do primeiro neurônio motor ou\npiramidal. Qual das alternativas abaixo traduz esta síndrome:","options":{"A":"Diminuição da força muscular, hipotrofia tardia, hipotonia, hiporreflexia profunda, sinal de\nBabinski, clônus, Hoffmann.","B":"Diminuição da força muscular, hipertonia, hipotrofia precoce, fasciculações, hiperreflexia\nprofunda.","C":"Diminuição da força muscular, hipotonia, hipotrofia precoce, fasciculações, hiporreflexia\nprofunda.","D":"Diminuição da força muscular, hipotrofia tardia, hipertonia, espasticidade, hiperreflexia\nprofunda,\nsinal de Babinski, clônus."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-208397","number":"208397","sourceNumber":"208397","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um dos princípios que deve nortear a implementação de um programa de rastreamento\nde doenças é:","options":{"A":"Se a doença tiver uma evolução rápida e alta taxa de mortalidade, o programa deve ser\ninstituído pela magnitude do problema, independente de outros fatores.","B":"Os programas de rastreamento, em geral, têm o potencial de trazer mais benefícios que danos\nàs populações submetidas aos testes.","C":"A história natural da doença ou do problema clínico deve ser bem conhecida.","D":"O teste de rastreamento deve detectar alteração na fase clínica da doença."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-176012","number":"176012","sourceNumber":"176012","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Estudos de genética molecular permitiram identificar os genes consistentemente\nassociados com o maior risco de desenvolvimento\nda doença de Alzheimer. Qual das alternativas\nabaixo não está relacionada à doença de Alzheimer?","options":{"A":"Alterações nos genes da alfa-sinucleinas (SNCA).","B":"Proteína precursora do amiloide (APP).","C":"Apolipoproteína E (APOE).","D":"Presenilina 2 (PSEN2)."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-151858","number":"151858","sourceNumber":"151858","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 70 anos, com síndrome demencial, após avaliação neurológica\nexaustiva foi diagnosticado como doença de\nAlzheimer. Qual é o achado predominante na doença\nde Alzheimer?","options":{"A":"Desmielinização.","B":"Atrofia dos ganglios da base.","C":"Perda neuronal no córtex cerebral.","D":"Perda das células pigmentadas na substância negra."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-151936","number":"151936","sourceNumber":"151936","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"\"A área de atuação da Medicina de Família e Comunidade (MFC) abrange a assistência\nà saúde durante todo o ciclo da vida, desde o\nperíodo antes do nascimento (preconcepção) até o\npost mortem (enlutados). Experiências bem consolidadas de Atenção Primária (AP) em países\ncomo Reino Unido e Canadá também pontuam a prática dos cuidados no final de vida dentro da\nlinha dos cuidados longitudinais.\" Entre os pacientes sob cuidados paliativos, uma das queixas\nmais frequentes é a dor. Sobre as recomendações do uso de analgésicos da Organização Mundial\nda Saúde (OMS), marque a CORRETA:","options":{"A":"Para garantir um alívio adequado da dor, os medicamentos analgésicos devem ser\nadministrados somente conforme a necessidade e não em intervalos regulares.","B":"Escolher os medicamentos analgésicos conforme a intensidade da dor, essa abordagem é\nconhecida como \"escada analgésica da dor\".","C":"Deve-se privilegiar a forma injetável dos analgésicos, principalmente a via intramuscular por ter\nefeito mais rápido.","D":"A dose dos medicamentos precisa ser padronizada, não sendo necessário levar em conta como\na pessoa sente a dor."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-129751","number":"129751","sourceNumber":"129751","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Quanto ao lavado bronquioloalveolar na asma, assinale a afirmativa CORRETA:","options":{"A":"Só tem significado quando utilizado como solução broncodilatadora.","B":"Não pode ser realizado, sob pena de agravar o broncoespasmo.","C":"Deve ser realizado sob aumento da pressão de aspiração para melhor recuperação do líquido\ninjetado.","D":"Tem, como principal indicação, a retirada de rolhas de muco de brônquios distais."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-129810","number":"129810","sourceNumber":"129810","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher de 45 anos em tratamento para insuficiência cardíaca, passado de trombose\nvenosa profunda proximal há 1 ano, apresenta\nepisódio súbito de dispneia associada a dor torácica\npleurítica. Ao exame: FC = 110 bpm; PA = 70 x 50 mmHg; estertores finos na base do hemitórax\ndireito. Radiografia de tórax mostra pequena condensação junto ao seio costofrênico direito, sem\nsinais de congestão e ECG apresentado abaixo. Diante do quadro, qual dos métodos diagnósticos\nabaixo se aplicaria para definir a causa da descompensação? (VER IMAGEM)","options":{"A":"Cineangiocoronariografia.","B":"Arteriografia pulmonar.","C":"Cintilografia pulmonar de ventilação-perfusão.","D":"Broncoscopia com lavado broncoalveolar."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/129810.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-107923","number":"107923","sourceNumber":"107923","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente com 65 anos refere dispneia progressiva há +/- 2 anos com sibilância torácica\nquando resfriado, tem prova de função pulmonar mostrando CVF=3.40 (80%), VEF1=1,20 (55%),\nVEF1/CVF=65%, com Radiografia de tórax mostrando hiperinsuflação pulmonar, escala de dispnéia\nMRC=2, SatO2=90% em repouso. Nega outras comorbidades. Referia tabagismo dos 15 aos 65\nanos (1 maço/dia). Qual o estadiamento do DPOC e o melhor tratamento conforme a classificação\nde gravidade, respectivamente.","options":{"A":"Estádio I (leve) - broncodilatador de curta ação.","B":"Estádio II (moderado) - broncodilatador de curta e longa ação + anticolinérgico de longa ação +\nreabilitação pulmonar.","C":"Estádio III (grave) - broncodilatador de curta ação e de longa ação + anticolinérgico e\ncorticoide\ninalatório.","D":"Estadio IV (muito grave) - corticóide inalatório + xantinas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-103821","number":"103821","sourceNumber":"103821","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"São sinais de gravidade na asma, EXCETO:","options":{"A":"retração acentuada do esternocleidomastóideo","B":"presença de pulso paradoxal","C":"bradicardia ou taquicardia","D":"presença de sibilos"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-107878","number":"107878","sourceNumber":"107878","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A diarréia crônica (DC) na infância pode ser causada por várias etiologias, Assinale\nabaixo a assertiva onde há correspondência entre a etiologia da DC e métodos de diagnóstico.","options":{"A":"Doença celíaca - diagnóstico clínico.","B":"Fibrose cística - teste de cloro no suor.","C":"Doença intestinal inflamatória - anticorpo anti endomisio.","D":"Síndrome do intestino irritável - enema opaco."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-103870","number":"103870","sourceNumber":"103870","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Escolar de 8 anos deu entrada no pronto atendimento em crise de asma que teve início\nhá 24 horas. A mãe refere que ele tosse,\nestá cansado, com chiado no peito e vomitando. Ao\nexame físico: está lúcido, orientado, acianótico, temperatura axilar 36,7°C; FR: 38 irpm; FC: 119\nbpm; saturimetria 95%; dispneia moderada; com retrações intercostais e sibilos expiratórios. O\ntratamento indicado neste momento é:","options":{"A":"Uso de leucotrienos via oral.","B":"Beta-2-agonista de ação curta por via inalatória.","C":"Aminofilina intravenosa.","D":"Corticoide via oral."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-81928","number":"81928","sourceNumber":"81928","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em relação à Doença Pulmonar Obstrutiva Crônica (DPOC), qual das afirmações\nabaixo é INCORRETA?","options":{"A":"O uso de oxigenoterapia de longa duração é a única terapia farmacológica que\ncomprovadamente diminui a mortalidade em pacientes com DPOC.","B":"Na DPOC grave, o VEF1, a relação VEF1/CVF e o Volume Residual (VR) ficam bastante\nreduzidos.","C":"O uso prolongado de corticoide oral para o tratamento da DPOC não é recomendado em face de\numa desfavorável relação custo/benefício.","D":"Baqueteamento digital não é um sinal de DPOC, sendo o seu achado neste grupo de paciente\nmais sugestivo de neoplasia pulmonar.","E":"A exposição crônica aos oxidantes provenientes da fumaça do cigarro leva a uma inativação da\nhistona deacetylase-2."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-81949","number":"81949","sourceNumber":"81949","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em relação aos mecanismos causadores do broncoespasmos na asma brônquica,\ntodas as afirmações abaixo estão corretas,\nEXCETO:","options":{"A":"A contração da musculatura lisa das vias aéreas em resposta a múltiplos mediadores\nbroncodilatadores e neurotransmissores, é o\nmecanismo predominante do estreitamento das vias\naéreas.","B":"O edema das vias aéreas é devido ao aumento do transudato microvascular em resposta a\nmediadores inflamatórios.","C":"O espessamento das vias aéreas devido à modificação estrutural frequentemente denominado\nde remodelação brônquica, não é completamente\nreversível pelas terapias atuais.","D":"A destruição dos espaços aéreos pós-broquíolos terminais leva a perda da sustentação das vias\naéreas, ocasionando o broncoespasmo.","E":"Hipersecreção de muco pode levar a oclusão luminal (rolhas) e é produto do aumento da\nsecreção de muco e exsudatos inflamatórios."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-87414","number":"87414","sourceNumber":"87414","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem de 65 anos, tabagista crônico, portador de DPOC grave, foi levado ao serviço\nde emergência de um hospital, apresentando dor\ntorácica súbita, dispneia importante e escarros\nhemoptoicos. De acordo com o quadro clínico apresentado o diagnóstico mais provável é:","options":{"A":"Embolia pulmonar.","B":"Pneumotórax espontâneo.","C":"Tuberculose.","D":"Carcinoma broncogênico.","E":"Bronquiectasia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-80988","number":"80988","sourceNumber":"80988","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Escolar de dez anos é levado ao pronto-socorro em crise de asma iniciada na noite\nanterior. A mãe relata tosse, chiado,\ndispneia e vômitos. Exame físico: lúcido, orientado, acianótico,\ntax 36,4º C, FR 40 irpm, FC: 112 bpm, SaO2: 94%, dispneia leve sem retrações intercostais e\npresença de sibilos expiratórios. O tratamento indicado neste momento é:","options":{"A":"Aminofilina intravenosa.","B":"Adrenalina subcutânea.","C":"corticosteroide via inalatória.","D":"Sulfato de magnésio intravenosa.","E":"ß2- agonistas de ação curta por via inalatória."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-60862","number":"60862","sourceNumber":"60862","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"No tratamento de pacientes bronquíticos crônicos portadores de Cor Pulmonale com\ndescompensação cardíaca, deve-se considerar como\nprincipal item da prescrição o uso de:","options":{"A":"Teofilina.","B":"Corticoterapia.","C":"Oxigenoterapia.","D":"Antibioticoterapia.","E":"Broncodilatadores."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-60865","number":"60865","sourceNumber":"60865","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O melhor tratamento para a manutenção de asma brônquica leve é feito com uso de:","options":{"A":"Corticoesteroide por via oral.","B":"Corticosteroide por inalação.","C":"Beta2-adrenérgico por via oral.","D":"Beta2-adrenérgico por inalação.","E":"Associação de beta2 com brometo de ipratrópio."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-34125","number":"34125","sourceNumber":"34125","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 60 anos vem apresentando dispneia progressiva aos esforços há cerca\nde seis meses acompanhado de tosse seca. Ao\nexame apresenta estertores bibasais e SatO2 =\n85%. Tabagista de 40 cigarros/dia e hipertenso. Possui ainda adenocarcinoma de próstata.\n\nRadiografia de tórax revela infiltrado reticular não septal periférico, predominante em lobos\ninferiores, volume pulmonar diminuído e área\ncardíaca normal. O diagnóstico mais provável é:","options":{"A":"Doença pulmonar obstrutiva crônica.","B":"Bronquiectasia.","C":"Insuficiência cardíaca congestiva.","D":"Doença intersticial pulmonar fibrosante.","E":"Carcinomatose linfática."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-34129","number":"34129","sourceNumber":"34129","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"É achado comum na radiografia de tórax de um paciente com enfisema pulmonar:","options":{"A":"Elevação do diafragma com acentuação dos seios costofrênicos.","B":"Aumento irregular da transparência pulmonar.","C":"Redução do espaço retroesternal.","D":"Aumento no tamanho dos vasos periféricos pulmonares.","E":"Alargamento e horizontalização do coração."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-26451","number":"26451","sourceNumber":"26451","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Na crise grave de asma são corretas as seguintes intervenções, EXCETO;","options":{"A":"Uso de oxigênio","B":"Uso de corticóides sistêmicos","C":"Uso rotineiro de antibióticos","D":"Associar broncodilatadores de curta duração","E":"Monitorização do K + plasmático"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-26603","number":"26603","sourceNumber":"26603","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual método diagnóstico é definitivo para Doença Pulmonar Obstrutiva Crônica (DPOC)\n\n?","options":{"A":"Rx de tórax - PA e perfil.","B":"Gasometria arterial.","C":"Espirometria.","D":"Tomografia Axial Computadorizada de Tórax de alta resolução.","E":"Teste Ergométrico"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-26605","number":"26605","sourceNumber":"26605","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Droga inicial a ser utilizada no Pronto-Socorro na Asma Intermitente Aguda?","options":{"A":"Xantinas","B":"Corticosteroides Endovenosos","C":"Beta-agonistas","D":"Corticosteroides inalatórios","E":"Drogas colinérgicas"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-26471","number":"26471","sourceNumber":"26471","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Lactente de 9 meses, tem apresentado episódios repetidos de tosse, sibilância e\ndesconforto respiratório.Qual dos achados clínicos é o mais sugestivo de asma?","options":{"A":"Dermatite atópica;","B":"Cianose periférica;","C":"Baqueteamento de dedos;","D":"Perda de peso progressiva;","E":"Estridor respiratório"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-7517","number":"7517","sourceNumber":"7517","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O diagnóstico de anemia ferropriva é indicado pelos seguintes parâmetros séricos: I-\nferro baixo. II- ferritina baixa. III- ferritina normal. IV- saturação de transferrina baixa. V-\nsaturação\nde transferrina alta. Estão corretos os parâmetros:","options":{"A":"I e III apenas.","B":"I e IV apenas.","C":"II e V apenas.","D":"I, II e IV apenas.","E":"I, II e III apenas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-7499","number":"7499","sourceNumber":"7499","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Nas adolescentes, em nosso meio, a principal causa da anemia é:","options":{"A":"Verminoses.","B":"Deficiência de G6PD.","C":"Deficiência alimentar de ácido fólico.","D":"Perdas menstruais.","E":"Distúrbios renais."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-7418","number":"7418","sourceNumber":"7418","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O agente etiológico mais frequente nas osteomielites em crianças com anemia\nfalciforme é:","options":{"A":"Streptococcus faecalis.","B":"Haemophilus.","C":"Staphilococcus epidermidis.","D":"Streptococcus viridans.","E":"Salmonella."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-354396","number":"354396","sourceNumber":"354396","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem, 65 anos de idade, procura a Unidade de Saúde para uma consulta de rotina.\nNão apresenta sintomas, mas está preocupado com\na saúde de sua próstata, já que seu pai foi\ndiagnosticado com câncer de próstata aos 70 anos de idade. Com base no caso apresentado,\nindique a melhor abordagem para o rastreio do câncer de próstata nesse paciente:","options":{"A":"Recomendar que ele não realize nenhum tipo de rastreio, já que não apresenta sintomas.","B":"Realizar um exame de toque retal no momento da consulta, independentemente de outros\nfatores.","C":"Indicar a realização de um exame de PSA (Antígeno Prostático Específico) anualmente e discutir\nos riscos e benefícios do rastreio.","D":"Iniciar tratamento anti-adrogênico, com base no histórico familiar, para prevenção de hipertrofia\ne de câncer."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-354421","number":"354421","sourceNumber":"354421","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem, 65 anos de idade, procura a Unidade de Saúde para uma consulta de rotina.\nNão apresenta sintomas, mas está preocupado com\na saúde de sua próstata, já que seu pai foi\ndiagnosticado com câncer de próstata aos 70 anos de idade. Com relação aos níveis de PSA na\ndetecção do câncer de próstata, pode-se afirmar:","options":{"A":"Embora o toque retal possa alterar o exame, a elevação dos níveis causada pelo procedimento\nnão interfere na acurácia.","B":"A alta sensibilidade do exame é maior que a especificidade, o que torna o exame ideal para\ntriagem.","C":"Níveis em elevação de PSA, se menores que 4 não devem ser valorizados em pacientes em uso\nde finasterida.","D":"As recomendações atuais não estabelecem limites etários para descontinuar a triagem com o\nexame."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-62834","number":"62834","sourceNumber":"62834","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente, 34 anos de idade, branco, admitido em unidade hospitalar com quadro de\nanasarca. Sumário de urina com proteína ++++. Foi feita suspeita de síndrome nefrótica. No\nterceiro dia de internamento, evoluiu com quadro de dispneia súbita. Pressão arterial normal e\nradiografia de tórax com pequeno derrame pleural à direita. A provável causa da dispneia, nesse\ncaso, é:","options":{"A":"Embolia pulmonar.","B":"Pericardite constritiva.","C":"Derrame pleural.","D":"Disfunção diastólica.","E":"Pleurite."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-35011","number":"35011","sourceNumber":"35011","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente foi avaliado por queixa de dispneia, e os dados obtidos na espirometria\ninicial foram VEF1: 50% do previsto, taxa de fluxo\nexpiratório máximo: 60% do previsto, taxa de\nfluxo expiratório máximo na metade da expiração (MMEFR): 40% do previsto. Após as medidas\nclínicas iniciais adotadas, observou-se que VEF1 passou para 65% do previsto. O quadro leva a\nconcluir que:","options":{"A":"esse paciente tem asma severa e as medidas clínicas adotadas tiveram resposta ainda\nincompleta.","B":"esse paciente tem um distúrbio ventilatório restritivo severo, sem resposta às atitudes\nadotadas.","C":"esse paciente tem um distúrbio ventilatório obstrutivo leve a moderado, com resposta incompleta\nàs medidas adotadas.","D":"o distúrbio ventilatório predominante é obstrutivo leve a moderado; com componente ventilatório\nrestritivo severo, sem resposta às medidas\nadotadas.","E":"o diagnóstico desse paciente é DPOC, com pequeno componente obstrutivo e componente\nrestritivo leve, sem resposta às medidas\nadotadas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-11121","number":"11121","sourceNumber":"11121","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente, sexo masculino, 28 anos de idade, chega à emergência vítima de acidente\nmotociclístico e, segundo relato da equipe de resgate, estava sem capacete e cursou com\ntraumatismo cranioencefálico. Ao exame, o paciente encontrava-se pálido com pulsos filiformes e\ncom expansibilidade torácica bilateral, desorientado, apresentava abertura ocular ao chamado e\nnão possuía movimentação espontânea, mas localizava a dor quando estimulado. Um ferimento\nlinear em supercílio e região temporal esquerdos com sangramento ativos chamava atenção. O\npaciente foi submetido a uma craniotomia descompressiva por hematoma intraparenquimatoso, e,\nno 8º dia pós-operatório cursou com edema ++/IV e dor do membro inferior esquerdo, com\nempastamento da panturrilha ipsilateral. O exame diagnóstico a ser solicitado é:","options":{"A":"ecocardiograma","B":"dupplex scan dos membros inferiores","C":"flebografia dos membros inferiores","D":"cintilografia pulmonar da ventilação-perfusão","E":"tomografia computadorizada do membro inferior esquerdo"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-11122","number":"11122","sourceNumber":"11122","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente, sexo masculino, 28 anos de idade, chega à emergência vítima de acidente\nmotociclístico e, segundo relato da equipe de resgate, estava sem capacete e cursou com\ntraumatismo cranioencefálico. Ao exame, o paciente encontrava-se pálido com pulsos filiformes e\ncom expansibilidade torácica bilateral, desorientado, apresentava abertura ocular ao chamado e\nnão possuía movimentação espontânea, mas localizava a dor quando estimulado. Um ferimento\nlinear em supercílio e região temporal esquerdos com sangramento ativo chamava atenção.\n\nConsiderando-se o diagnóstico de trombose venosa profunda:","options":{"A":"anticoagulação plena com heparina de baixo peso molecular","B":"anticoagulação plena com heparina não fracionada","C":"anticoagulação plena com cumarínicos","D":"implante de filtro de veia cava","E":"heparinização profilática"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-157687","number":"157687","sourceNumber":"157687","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sobre a Mediastinite Necrotizante Descendente Aguda, aponte a opção que esteja\nINCORRETA.","options":{"A":"Geralmente é uma infecção polimicrobiana, e os agentes mais comuns são: Pseudomonas\naeroginosa, Stafilococcus aureus e\n\nBacteriodes fragilis.","B":"A mortalidade pode chegar a 50% e é mais frequente na população de pior condição\nsocioeconômica.","C":"O tratamento com medidas de suporte intensivo e antibioticoterapia de amplo espectro é a\nterapia padrão.","D":"O exame mais preciso e que melhor orienta o diagnóstico é a tomografia computadorizada de\npescoço e tórax."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-157680","number":"157680","sourceNumber":"157680","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Assinale a alternativa INCORRETA quanto ao atendimento hospitalar na UTI para\ncrianças em crise de asma.","options":{"A":"Assim que o paciente chega à UTI, a oferta de oxigênio suplementar deve ser otimizada, e a\nadministração do beta 2 agonista de curta duração inalatório deve ser maximizada e novamente\naveriguada quanto à sua dose e forma de administração.","B":"Em UTI, recomenda-se a manutenção da terapia com corticoide sistêmico, preferencialmente por\nvia endovenosa.","C":"O aumento do escore PAS (Pediatric Asthma Score), cujas variáveis são FR, necessidade de\noxigênio, presença de retrações, esforço respiratório e ausculta, representa piora clínica e indica\ntroca na etapa de tratamento intensivo da asma.","D":"Se houver falha no tratamento com broncodilatador, corticoide e sulfato de magnésio, deve-se\nconsiderar a seguinte sequência:\n\naminofilina, salbutamol endovenoso e ventilação mecânica não invasiva."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-157690","number":"157690","sourceNumber":"157690","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Quanto ao sulfato de magnésio e à aminofilina, aponte a alternativa INCORRETA.","options":{"A":"Em crianças, o sulfato de magnésio deve ser administrado na dose de 25 a 75 mg/kg/dose.","B":"Transpiração, depressão dos reflexos e colapso circulatório estão entre as reações adversas do\nsulfato de magnésio.","C":"A dose de ataque da aminofilina é de 6 mg/kg, infundida em 20 minutos, seguida de dose de\nmanutenção de 0,65 mg/kg/hora em crianças maiores de 10 kg.","D":"Vômitos, palpitações e dor no local da injeção estão entre as reações adversas à aminofilina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-134721","number":"134721","sourceNumber":"134721","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente com queixa de dispneia, tosse e chiado no peito. Refere ser asmático\ne apresentar frequentemente crises, e procura o\nPronto-socorro para tomar injeção e fazer\ninalação. Qual dos achados abaixo, NÃO denota gravidade da crise?","options":{"A":"Frequência respiratória acima de 40 por minuto.","B":"Peak Flow menor que 200 l/min.","C":"Gasometria com hipocapnia.","D":"Gasometria com PCO2 de 55 mm Hg."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-111848","number":"111848","sourceNumber":"111848","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual dos achados abaixo NÃO pode ser considerado como característico ou possível\nem uma Embolia Pulmonar?","options":{"A":"S1Q3T3.","B":"Taquicardia sinusal.","C":"Inversão de ondas T de V1 a V6.","D":"Todos os achados acima são característicos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-111869","number":"111869","sourceNumber":"111869","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual é a sequência ADEQUADA para tratamento do Estado de Mal Asmático (Asma\nAguda Grave), em Pediatria?","options":{"A":"Inalação contínua, corticoide endovenoso, terbutalina endovenosa, sulfato de magnésio e heliox.","B":"Aminofilina, corticoide endovenoso, inalação contínua, terbutalina endovenosa e heliox.","C":"Inalação contínua, corticoide inalatório, aminofilina, terbutalina subcutânea e sulfato de\nmagnésio.","D":"Inalação contínua, terbutalina subcutânea, sulfato de magnésio e aminofilina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-350874","number":"350874","sourceNumber":"350874","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 70 anos, hipertenso e diabético há 25 anos, vem em consulta com geriatra\ncom queixa de esquecimentos há 1 ano. Filha\nrelata que o mesmo teve episódio de desorientação\nquando estava dirigindo para igreja e necessitou auxílio do neto para chegar ao destino. Tem\napresentado dificuldade no controle de suas finanças e de suas medicações. Na avaliação\ncognitiva inicial, fez 28 de 30 pontos no Mini exame do estado mental, perdendo 2 pontos na\nevocação. Nível de escolaridade: superior completo. História de infarto do miocárdio com colocação\nde stent há 10 anos. Qual o próximo passo para auxiliar no diagnóstico neste caso?","options":{"A":"Encaminhamento para realização de avaliação neuropsicológica detalhada e coleta de líquor.","B":"Realização do teste fluência verbal semântica (animais) e o teste do desenho do relógio (TDR),\nrastreio para sintomas depressivos e ressonância magnética de crânio.","C":"Realização da avaliação cognitiva de Montreal (MoCA), bateria Addenbrooke (ACE-R), rastreio\npara sintomas depressivos e ressonância\nmagnética de crânio.","D":"Aplicação da escala \"avaliação clínica da demência? (CDR-Clinical Dementia Rating), rastreio\npara sintomas depressivos e neuropsiquiátricos,\nalém de tomografia de crânio sem contraste."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-350890","number":"350890","sourceNumber":"350890","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem de 64 anos, hipertenso e diabético, comparece ao pronto-atendimento com\nhemiparesia em dimidio direito. Percebeu alteração ao despertar hoje, pela manhã, às 6h, 1 hora\nantes do atendimento médico. PA 240x130mmHg. Realizou tomografia de crânio sem contraste\nsem sinais de sangramento intracraniano. Dentro desse contexto, qual a conduta mais adequada a\nser realizada?","options":{"A":"Encaminhar paciente para trombectomia.","B":"Iniciar trombolítico endovenoso, imediatamente.","C":"Administrar anti-hipertensivo parenteral para trombólise, após controle pressórico adequado.","D":"Prescrever anti-hipertensivo endovenoso, antiagregação plaquetária e estatina de alta potência."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-350886","number":"350886","sourceNumber":"350886","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 35 anos portadora de câncer de mama com metástase óssea e em sistema\nnervoso central vem ao ambulatório com queixa dor de difícil controle, já em uso de morfina 30mg 3\ncomprimidos de 4 em 4 horas, e dipirona 8g/dia. Solicita inúmeros resgates e refere que a sua dor é\nintensidade 8 em 10 durante todo o tempo e com dor episódica 10 em 10. Relata ainda queixa de\nprurido sem melhora com uso de anti-histamínico. Qual a melhor abordagem nesse contexto?","options":{"A":"Considerar dependência física à morfina e suspender gradualmente esse opioide.","B":"Considerar que não foi atingida a dose máxima de morfina e aumentar a dose deste opioide.","C":"Considerar a possibilidade de adição ao opioide e encaminhar a paciente para equipe\nespecializada.","D":"Considerar tolerância à morfina e realizar rodízio de opioides, com prescrição de metadona ou\nfentanil."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-350847","number":"350847","sourceNumber":"350847","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em sua reunião estratégica de equipe para discutir as próximas visitas domiciliares a\nserem realizadas, o ACS Gustavo traz para sua\nciência que dona Alegria, uma paciente de 102\nanos que reside na área, já acamada há dez anos, está com sintomas urinários e a família solicitou\nvisita. Você prontamente se dispõe a fazer a visita domiciliar no turno da tarde. Em seu atendimento\ndomiciliar, você é recebido por Marcello, filho da paciente. D. Alegria é acompanhada por demência\nde Alzheimer grave, sem outras comorbidades conhecidas. É restrita ao leito, apresenta postura\nfletida, não interage com examinador, alimenta-se por gastrostomia e apresenta dupla\nincontinência. Está constipada há 5 dias, sem distensão abdominal. Apresenta lesão por pressão\nestágio 2 em região sacral, que está em acompanhamento em conjunto por equipe de Atenção\nDomiciliar. Em último internamento hospitalar, foi estabelecido plano terapêutico com cuidados\npaliativos, com acompanhamento no nível domiciliar. Medidas invasivas e desproporcionais foram\ncontraindicadas, inclusive ressuscitação cardiopulmonar. A família compreende o contexto de\nfinitude e o estado de fragilidade de saúde em que se encontra a matriarca da família. Há dois dias\na paciente evoluiu com episódios de agitação psicomotora, polaciúria, hematúria e aparente disúria,\ncom gemidos durante diurese. Há um dia, apresentou pico febril de 37,8°C. Hoje, durante seu\natendimento, você encontra paciente afebril, sonolenta, não interagindo com examinador. Os sinais\nvitais estão estáveis. A fralda apresenta diurese de caráter avermelhado. O exame físico não traz\nachados clinicamente relevantes. Assinale a alternativa que traz a conduta terapêutica inicial\nadequada em relação ao quadro urinário de d. Alegria.","options":{"A":"Indicar a hospitalização da paciente para tratamento de infecção urinária em contexto clínico\ncomplexo.","B":"Prescrever antibioticoterapia e sintomáticos. Orientar medidas não-farmacológicas adjuvantes\npara o controle de sintomas. Programar\nreavaliação precoce.","C":"Prescrever sintomáticos, mas sem prescrever antibióticos. Paciente se encontra em contexto de\ncuidados paliativos, portanto, não há indicação de antibioticoterapias.","D":"Prescrever antibioticoterapia, sintomáticos e sondagem vesical de demora. Aumentar a ingesta\n\nhídrica e solicitar balanço hídrico para vigilância de possível deterioração clínica. Programar\nreavaliação precoce."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-321303","number":"321303","sourceNumber":"321303","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"SM, 78 anos, físico, antecedente de HAS e episódio prévio de hemorragia\nsubaracnóidea há 10 anos, informa que há 6\nmeses vem apresentando alteração de marcha\ncaracterizada por uma base de sustentação alargada, com os artelhos desviados lateralmente,\npostura ligeiramente fletida, aumento do balanço do tronco durante a marcha e diminuição da altura\ne comprimento dos passos. Há lentidão e hesitação ao iniciar a marcha com os pés parecendo\ngrudados ao chão. Nesse período, também passou a apresentar incontinência urinária. A esposa\nrelata que tem percebido o paciente com déficit de atenção, alterações de comportamento e de\npersonalidade e disfunção executiva manifestada por diminuição do processamento de informações\ncomplexas, e dificuldade para manipular novos conhecimentos. O paciente traz exames\nlaboratoriais normais, recentes, incluindo hemograma, eletrólitos, função renal e tireoidiana,\nenzimas hepáticas, glicemia e hemoglobina glicada, dosagem de vitaminas B12 e ácido fólico,\nlipidograma, VDRL e anti-HIV. A RM de crânio mostrou atrofia global leve e escala de atrofia mesial\ntemporal (MTA) de 1; microangiopatia periventricular Fazekas 1, além de aumento dos ventrículos,\nacompanhado de arredondamento dos cornos frontais e alargamento dos cornos temporais.\n\nAssinale, dentre as alternativas abaixo, a hipótese diagnóstica adequada para o caso clínico acima.","options":{"A":"Depressão.","B":"Doença de Alzheimer.","C":"Doença de Biswanger.","D":"Hidrocefalia de pressão normal."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-321347","number":"321347","sourceNumber":"321347","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma agente de saúde procura você trazendo a demanda de uma família. Ela relata que\nDona Benzarina, de 102 anos, recebeu alta do\nhospital municipal ?para morrer em casa, pois não\ntinham mais o que fazer por ela?. A equipe da UBS de referência não recebeu comunicação do\nServiço Social do referido hospital. A família está muito angustiada, pois a paciente ?está\nagonizando? e por isso solicita uma visita domiciliar. Durante a visita domiciliar à Dona\nBenzarina, a\nDra. Tatiana tem acesso ao relatório de alta, que indica neoplasia maligna de mama localmente\navançada e com metástase óssea de arcos costais. Há Tramadol prescrito, em dosagem máxima\nde 400mg/dia. Em exame físico, a paciente se encontra em estado geral regular, emagrecida,\nconsciente, orientada e com fasceis de dor. A família refere estar administrando a prescrição\ncorretamente, mas a paciente refere dor intensa. Assinale a alternativa que corresponde à conduta\ncorreta diante do sintoma de dor.","options":{"A":"Associar Paracetamol com Codeína ao Tramadol.","B":"Substituir Tramadol por Morfina.","C":"Associar Dipirona ao Tramadol.","D":"Associar Morfina ao Tramadol."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-321351","number":"321351","sourceNumber":"321351","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Seu Edinaílson, de 60 anos, é trazido para consulta por seus dois filhos: Edberto e\nEdnardo. Ele vem em cadeira de rodas, mas\nestá com punhos e tornozelos contidos. Segue o\nrelato dos filhos - Papai sempre foi um mecânico de referência aqui no bairro, mas tem dois anos\nque as coisas desandaram. A gente foi vendo ele ficar cada vez mais magro e não entendia o que\nestava acontecendo. Depois, o salário começou a diminuir, mas quando a gente perguntava, ele\nficava muito irritado. Levamos numa clínica popular, onde ele fez uma bateria de exames para\ndiabetes, pressão, hepatite e até sífilis e HIV, mas nunca deu nada. Ele começou a perder o prazo\ndos serviços e começou a fazer os serviços pela metade, mas o pior foi que ele começou a\ndestratar todo mundo. Ele sempre foi uma pessoa calma, mas começou a falar palavrão e querer\nbater nos outros. A gente só foi saber disso depois de um ano, porque ele chegou em casa\nmachucado porque tinha se envolvido em briga. A gente foi na oficina e o dono falou que ele não\ntinha mais condições de trabalhar. Ele disse que papai começou a urinar no chão do banheiro, que\nnão comia mais e que não se vestia mais direito. Levamos ele para cuidar em casa, mas ele estava\nmuito teimoso e briguento. Não queria comer, não queria tomar banho e não queria se vestir.\n\nEstamos levando do jeito que dá, mas quando ele começou a se urinar e se sujar, a gente viu que\nprecisava vir pedir ajuda de novo. Ele não está mais sabendo mexer em dinheiro, não toma mais\nbanho sem ajuda e agora começou a engasgar com a comida. Ele consegue andar e tem força,\nmas a gente teve que amarrar ele nessa cadeira, porque ele fica querendo pegar nas mulheres, é\nhorrível. Ele lembra da gente, lembra da nossa mãe, lembra dos irmãos, mas a gente não\nreconhece mais ele. Os filhos trouxeram exames laboratoriais recentes. Não havia alteração\nendócrino-metabólica significativa, nem hidroeletrolítica ou autoimune. Os exames de rastreamento\nde ISTs (HIV, sífilis e hepatites) também estavam sem alterações significativas. Ao se aproximar\npara realizar o exame físico de Seu Edinaílson, ele se mostrava calmo, mas pouco cooperativo. Ele\nsoube dizer o nome completo e reconheceu os filhos. Estava desorientado em espaço. O exame\nfísico não revelou alterações clínicas significantes. Assinale a alternativa com o diagnóstico\netiológico mais provável para a síndrome demencial apresentada no quadro.","options":{"A":"Doença de Creutzfeldt-Jakob.","B":"Demência Frontotemporal.","C":"Demência de Alzheimer.","D":"Demência Vascular."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-321352","number":"321352","sourceNumber":"321352","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Seu Edinaílson, de 60 anos, é trazido para consulta por seus dois filhos: Edberto e\nEdnardo. Ele vem em cadeira de rodas, mas\nestá com punhos e tornozelos contidos. Segue o\nrelato dos filhos - Papai sempre foi um mecânico de referência aqui no bairro, mas tem dois anos\nque as coisas desandaram. A gente foi vendo ele ficar cada vez mais magro e não entendia o que\nestava acontecendo. Depois, o salário começou a diminuir, mas quando a gente perguntava, ele\nficava muito irritado. Levamos numa clínica popular, onde ele fez uma bateria de exames para\ndiabetes, pressão, hepatite e até sífilis e HIV, mas nunca deu nada. Ele começou a perder o prazo\ndos serviços e começou a fazer os serviços pela metade, mas o pior foi que ele começou a\ndestratar todo mundo. Ele sempre foi uma pessoa calma, mas começou a falar palavrão e querer\nbater nos outros. A gente só foi saber disso depois de um ano, porque ele chegou em casa\nmachucado porque tinha se envolvido em briga. A gente foi na oficina e o dono falou que ele não\ntinha mais condições de trabalhar. Ele disse que papai começou a urinar no chão do banheiro, que\nnão comia mais e que não se vestia mais direito. Levamos ele para cuidar em casa, mas ele estava\nmuito teimoso e briguento. Não queria comer, não queria tomar banho e não queria se vestir.\n\nEstamos levando do jeito que dá, mas quando ele começou a se urinar e se sujar, a gente viu que\nprecisava vir pedir ajuda de novo. Ele não está mais sabendo mexer em dinheiro, não toma mais\nbanho sem ajuda e agora começou a engasgar com a comida. Ele consegue andar e tem força,\nmas a gente teve que amarrar ele nessa cadeira, porque ele fica querendo pegar nas mulheres, é\nhorrível. Ele lembra da gente, lembra da nossa mãe, lembra dos irmãos, mas a gente não\nreconhece mais ele. Os filhos trouxeram exames laboratoriais recentes. Não havia alteração\nendócrino-metabólica significativa, nem hidroeletrolítica ou autoimune. Os exames de rastreamento\nde ISTs (HIV, sífilis e hepatites) também estavam sem alterações significativas. Ao se aproximar\npara realizar o exame físico de Seu Edinaílson, ele se mostrava calmo, mas pouco cooperativo. Ele\nsoube dizer o nome completo e reconheceu os filhos. Estava desorientado em espaço. O exame\nfísico não revelou alterações clínicas significantes. O manejo farmacológico de sintomas\nneurocognitivos e comportamentais nas síndromes demenciais se dá geralmente com\n\nantidepressivos e antipsicóticos. No entanto, é preciso atenção ao uso de psicofármacos em idosos\ndevido a potenciais efeitos adversos. Considerando o quadro clínico de Seu Edinaílson, assinale a\nalternativa que traz uma opção de tratamento antidepressivo adequado em idosos.","options":{"A":"Diazepam.","B":"Trazodona.","C":"Amitriptilina.","D":"Tranilcipromina."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-292818","number":"292818","sourceNumber":"292818","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"ACR, 82 anos, advogado aposentado, há 6 meses passou a apresentar esquecimento\npara fatos recentes, tendo passado a esquecer\nde pagar as contas da casa e teve sua energia\ncortada pela companhia elétrica. Relata que no fim da tarde é comum ver uma criança\ndesconhecida brincando na varanda de sua casa. Relata também sono agitado com muitos\npesadelos frequentes. A esposa informa que há dias em que ele está muito apático, ficando\nisolado, sem se comunicar. O exame físico é normal, exceto pela presença de rigidez em roda\ndenteada em punho direito. Mini Exame do Estado Mental (MEEM) foi 25/30. Durante o MEEM\nrespondeu que estava no consultório de seu dentista, lembrou duas das três palavras solicitadas na\nevocação e errou três cálculos. Os exames laboratoriais são normais, exceto por anemia leve\nobservada no hemograma (Hb = 11g/dl; Ht 38%; VCM 100 fl; HCM 31 pg). A dosagem de vitamina\nB12 foi 259 pg/ml (VR: 239 a 931 pg/ml). A ressonância magnética de crânio mostrou atrofia global\nleve e escala de atrofia mesial temporal (MTA) de 1. Qual a principal hipótese diagnóstica para o\ncaso clínico?","options":{"A":"Doença de Alzheimer.","B":"Doença de Parkinson.","C":"Demência por corpúsculos de Lewy.","D":"Demência por deficiência de vitamina B12."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-292863","number":"292863","sourceNumber":"292863","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em sua consulta com Edberto, ele refere que o medo de desenvolver câncer de pulmão\né uma das razões que o motiva a parar de\nfumar. Ele, então, pergunta se você pode solicitar algum\nexame de rastreio para câncer de pulmão nele. De acordo com recomendações nacionais para o\nrastreio do câncer de pulmão, assinale a alternativa com a conduta adequada.","options":{"A":"Informar que até o momento não existe diretriz nacional governamental para o rastreamento de\ncâncer de pulmão, além de ele não ter indicação de realizar o exame.","B":"Solicitar exame de radiografia simples de tórax para acolher a demanda do paciente e avaliar\nseu risco de câncer de pulmão, sem recorrer a\num exame oneroso e complexo.","C":"Solicitar exame de tomografia de tórax de baixa energia para acolher a demanda do paciente e\ncondicionar a solicitação do exame à cessação do tabagismo de Edberto, ajudando na motivação\nda parada do tabagismo.","D":"Informar que a diretriz ministerial brasileira prevê que a tomografia de tórax de baixa energia\nestá indicada no rastreamento de câncer de\npulmão somente na população considerada de alto\nrisco: idade entre 50 e 80 anos e carga tabágica de pelo menos 30 maços-ano."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-292867","number":"292867","sourceNumber":"292867","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em um turno de demanda programada na Unidade, Vanusa, irmã de Vanessa, traz\ndona Benzarina para atendimento. A consulta é\npara mostrar exames solicitados há seis meses. O\nregistro no prontuário traz ?síndrome demencial com predominância de disfunção executiva,\nsintomas neurológicos focais, síndrome pseudobulbar e início precoce de alteração de marcha?. A\nressonância nuclear magnética de crânio evidencia acometimento extenso de substância branca,\nno giro do cíngulo, no lobo temporal medial e no tálamo. Assinale a alternativa com o diagnóstico\nmais provável.","options":{"A":"Demência vascular.","B":"Demência de Alzheimer.","C":"Demência frontotemporal (DFT).","D":"Demência por corpúsculo de Lewy."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-259710","number":"259710","sourceNumber":"259710","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente, 65 anos, masculino, procura atendimento médico na Unidade Básica de\nSaúde devido a tremor em membros superiores\niniciado há pelo menos 5 anos. Paciente refere que\no tremor está atrapalhando suas atividades como escrita e alimentação, pois piora nessas\natividades, sem ser perceptível no repouso. Nega outros sintomas. Paciente é asmático e por isso\nnão fuma nem usa bebidas alcoólicas. Nega história familiar. Ao exame físico: Pressão Arterial de\n110 x 70mmHg; Pulso: 62 batimentos por minuto; presença de tremor em membros superiores\nvisualizada durante prova dos braços estendidos e índex-índex. Sem outras alterações. Qual o\nmelhor tratamento para o paciente acima?","options":{"A":"Primidona.","B":"Biperideno.","C":"Propranolol.","D":"Levodopa/carbidopa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-259753","number":"259753","sourceNumber":"259753","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma médica, atuando em uma equipe de atenção primária, recebe em seu consultório\numa senhora de 74 anos de idade, solicitando um\n\"check-up\". Nega qualquer sintoma no momento.\nNão relata nenhum antecedente patológico pessoal ou familiar. Qual deverá ser a conduta da\nmédica em relação ao rastreamento?","options":{"A":"Solicitar mamografia.","B":"Realizar exame de papanicolau.","C":"Solicitar sangue oculto nas fezes.","D":"Realizar o rastreamento para câncer de pele."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-259756","number":"259756","sourceNumber":"259756","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente do sexo masculino, 86 anos, é portador de câncer de pulmão com metástase\npara osso e fígado. Está totalmente acamado,\ndependente para as atividades de vida diária (AVD)\ne sonolento. Ingestão de alimentos reduzida. Familiares informam que paciente vinha apresentando\nfalta de ar que piorou nas últimas 12 horas. Ao exame: Pressão arterial = 80 x 60 mmHg\nFrequência cardíaca = 112 batimentos por minuto Frequência respiratória = 30 incursões\nrespiratórias por minuto Saturação periférica de oxigênio= 93% em ar ambiente Estado geral ruim,\nconsumido, anictérico, acianótico, afebril, fala entrecortada a cada 15 segundos. Tórax: presença\nde retrações subcostais e esternocleidomastoideas discretas Ausculta pulmonar: Murmúrio\nvesicular universal com roncos de transmissão. Qual a melhor opção para o tratamento da dispneia\ndo paciente descrito no caso clínico acima?","options":{"A":"Iniciar haloperidol 1-2 mg, SC.","B":"Prescrever morfina 1-5 mg, SC.","C":"Preservar paciente em ambiente fechado.","D":"Manter paciente deitado sem cabeceira elevada."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-259761","number":"259761","sourceNumber":"259761","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente, 75 anos, analfabeta, portadora de osteoartrose, hipertensão arterial sistêmica\ne diabetes mellitus não-insulino dependente.\nComparece ao posto de saúde para consulta de rotina\nacompanhada de sua filha. Apresenta a seguinte avaliação multidimensional: VISÃO ? Aplicação\ndo cartão de Jaeger: olho direito 20/70 e olho esquerdo 20/70. AUDIÇÃO ? Aplicação do teste do\nsussurro (whisper): paciente responde corretamente à pergunta formulada próxima ao ouvido direito\ne próxima ao ouvido esquerdo. FUNÇÃO DOS MEMBROS SUPERIORES PROXIMAL ? Paciente\nconsegue tocar a nuca com ambas as mãos. DISTAL ? Paciente consegue apanhar um lápis sobre\na mesa com cada uma das mãos e colocá-lo de volta no mesmo lugar. FUNÇÃO DOS MEMBROS\nINFERIORES ? Paciente consegue levantar da cadeira sozinho na segunda tentativa, mas utiliza\nos braços como apoio. Consegue caminhar 3,5 metros, voltar e sentar. ESTADO MENTAL ? Escore\ndo mini exame do estado mental (MEEM) de 15 pontos. HUMOR ? Escala de depressão geriátrica\nabreviada (GDS) = 12 pontos. DOMICÍLIO ? Paciente nega queda nos últimos 12 meses. Em sua\ncasa, não há escadas/batentes, tapetes soltos nem corrimão no banheiro. ATIVIDADES DIÁRIAS ?\nPaciente, sem auxílio, é capaz de sair da cama e preparar suas refeições. Porém, não consegue\nfazer compras. INCONTINÊNCIA ? Nega perda involuntária de urina. NUTRIÇÃO ? Nega perda de\npeso no último ano. Peso usual de 82 Kg. Altura usual de 1,60 cm. SUPORTE SOCIAL ? Conta\ncom apoio de sua filha mais nova para ajudá-la e caso fique incapaz de tomar decisões. Baseado\nna avaliação multidimensional da idosa acima descrita, qual a conduta mais adequada?","options":{"A":"Solicitar audiometria.","B":"Iniciar um antidepressivo.","C":"Prescrever um andador ou bengala.","D":"Reavaliar acuidade visual a cada 3 meses."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-234038","number":"234038","sourceNumber":"234038","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher, 66 anos, acompanhada há 6 anos devido a doença de Parkinson, em uso de\nlevodopa desde o início do acompanhamento. Há 8 meses, apresenta movimentos involuntários,\ninicialmente em membros inferiores, depois acontecendo também em tronco e membros superiores,\niniciados após 90 minutos da tomada da levodopa, durando aproximadamente 30 minutos. Faz uso\natual de levodopa/carbidopa 250/25mg 1/2 (meio) comprimido em 5 tomadas ao dia (intervalo\nmédio de 3 horas entre as tomadas). Nega uso de outras medicações ou perda de efeito (rigidez,\nlentificação ou tremor) entre as tomadas. Ao exame neurológico são observados movimentos\ncoreiformes em membros inferiores e superiores, além de leve rigidez e bradicinesia assimétricas.\n\nQual a melhor opção terapêutica para ser associada a levodopa/carbidopa nessa paciente para\ndiminuir os movimentos descritos?","options":{"A":"Amantadina.","B":"Pramipexol.","C":"Biperideno.","D":"Rasagilina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-234042","number":"234042","sourceNumber":"234042","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem de 80 anos, viúvo, aposentado e analfabeto, mora com a filha e comparece ao\nPosto de Saúde para consulta de rotina. Antecedentes: hipertensão, diabetes, osteoartrose de\njoelhos, obesidade, glaucoma e retinopatia diabética. Traz exames com hemograma, perfil\nglicêmico e lipídico, função renal e tireoidiana, todos normais. Filha refere que no último ano o\npaciente tem necessitado de ajuda para manejo das medicações e atividades fora do domicílio.\n\nPouco sai de casa e não demonstra mais interesse em sua vida cotidiana. Qual a provável causa\nda dificuldade em atividades do dia a dia e a\nabordagem inicial?","options":{"A":"Déficit cognitivo ? aplicar Mini-Exame do Estado Mental e iniciar tratamento de demência.","B":"Perda funcional multifatorial ? aplicar escala de Lawton e Katz e iniciar manejo de\ncomorbidades.","C":"Transtorno depressivo ? aplicar Escala de Depressão Geriátrica para diagnóstico e iniciar\ntratamento.","D":"Perda funcional secundária a senescência ? aplicar Avaliação Geriátrica Ampla e orientar sobre\no quadro."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-234082","number":"234082","sourceNumber":"234082","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Dr. Sombra, recém-formado, acabou de ser lotado em uma Unidade Básica de Saúde\nda Família no interior do Ceará e foi\ninformado pela Vigilância Epidemiológica local que há casos\nnovos de zika sendo relatados. Diante desse cenário, decidiu chamar sua equipe e sensibilizá-la\nem relação à necessidade de utilizar um teste diagnóstico no pré-natal para rastrear possíveis\ncasos suspeitos. Qual a principal característica que esse teste diagnóstico deverá apresentar?","options":{"A":"Alta sensibilidade.","B":"Alta especificidade.","C":"Alto valor preditivo positivo.","D":"Alto valor preditivo negativo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-199810","number":"199810","sourceNumber":"199810","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente masculino, 52 anos, procurou atendimento médico em emergência devido a\nepisódio de fraqueza em hemicorpo direito e dificuldade na fala iniciada há 2 horas. Nega\ncomorbidades prévias, exceto HAS. Faz uso regular de anlodipino 5 mg e AAS 100 mg. Ao exame\nPA = 180 x 100 mmHg; pulso = 96 batimentos; saturação de oxigênio = 96% em ar ambiente. Tem\nNIH de 15 à custa de hemiparesia à direita, disartria e afasia motora, sem alteração de nível de\nconsciência. Com 2 horas e 30 minutos de início do quadro, tem os seguintes exames laboratoriais\nnormais (hemograma, ureia, creatinina, TAP e TTPA) e a TC de crânio evidencia hematoma\nputaminal de 15 cm³ à direita. LEGENDA: PA = Pressão Arterial; HAS = Hipertensão Arterial\nSistêmica; NIH = National Institute of Health Stroke Scale; TAP = Tempo de Atividade de\nProtrombina; TTPA = Tempo de Tromboplastina Parcial Ativado; TC = Tomografia\nComputadorizada. Qual a melhor conduta para esse paciente?","options":{"A":"Fator VIIa recombinado.","B":"Dexametasona 10 mg endovenoso.","C":"Transfusão de concentrado de plaquetas.","D":"Anti-hipertensivo com alvo de PA < 140 mmHg."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-199721","number":"199721","sourceNumber":"199721","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem de 72 anos procura assistência ambulatorial com queixa de alteração de\nmarcha e duas quedas da própria altura há um\nmês. Relata antecedentes de ?pressão alta,\nreumatismo e tontura?. Está fazendo uso contínuo de: losartana, hidroclorotiazida, carbonato de\ncálcio e cinarizina. No exame físico neurológico, evidenciou-se rigidez simétrica em cotovelos,\npunhos, joelhos e tornozelos, assim como em tronco. Ausência de tremor. Marcha com passos\ncurtos e arrastados, sem a participação dos movimentos dos braços. Considerando a principal\nhipótese diagnóstica, qual a conduta mais adequada neste momento?","options":{"A":"Suspender cinarizina.","B":"Prescrever rasagilina.","C":"Prescrever pramipexol.","D":"Prescrever levodopa + benserazida."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-199766","number":"199766","sourceNumber":"199766","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Idosa de 88 anos, portadora de fibrose pulmonar idiopática há 3 anos, em uso de\noxigênio domiciliar e parcialmente dependente\npara atividades de vida diária. Em uso de morfina 30\nmg/d via oral e clonazepam 2 mg/d. Internada por quadro de piora da dispneia, mesmo após 7 dias\nde tratamento ambulatorial com moxifloxacino oral, sendo iniciado piperacilina + tazobactan na\nadmissão. Evolui no 3º dia de internação sonolenta, taquidispneica, em uso de musculatura\nacessória, saturação de oxigênio 82% com máscara de venturi a 50%, PA: 100 x 60 mmHg,\nFrequência cardíaca: 100 bpm. Palliative Performance Scale (PPS) de 30%. Paciente já havia\nmanifestado desejo de não ser intubada nem internada em unidade de terapia intensiva. Qual a\nconduta mais adequada nesse momento?","options":{"A":"Iniciar ventilação não invasiva.","B":"Realizar intubação orotraqueal.","C":"Iniciar sedação paliativa com midazolam.","D":"Iniciar morfina em bomba de infusão contínua."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-199704","number":"199704","sourceNumber":"199704","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 82 anos, viúva, analfabeta, teve visita domiciliar requisitada pelos filhos.\nA\npaciente morava no interior do estado e, há 2 semanas, foi trazida para a casa de um dos filhos, na\ncapital. Está agitada à noite, fica rezando alto, não consegue dormir, apresenta dificuldade de\ndeambular e \"vem perdendo urina\". Os filhos dizem que ela não era assim, mas não sabem\nprecisar o início dos sintomas. Não faz uso de medicamentos, nega tosse e dispneia. Atividades de\nvida diária básicas comprometidas. Escala de depressão geriátrica = 3, mini exame do estado\nmental = 15 pontos. Nega alucinações visuais ou auditivas. Ao exame físico, apresenta marcha de\nbase alargada e passos curtos. Movimentação passiva das articulações sem resistência.\n\nConsiderando a hipótese diagnóstica mais provável, qual a conduta inicial mais adequada para esta\npaciente?","options":{"A":"Solicitar ressonância magnética de sistema nervoso.","B":"Prescrever antidepressivo e reavaliar com quinze dias.","C":"Simplificar o ambiente para evitar excesso de estímulo à paciente.","D":"Tranquilizar a paciente e familiares e orientar em relação a evolução do quadro demencial."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-172998","number":"172998","sourceNumber":"172998","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem de 78 anos é levado à emergência com fraqueza em hemicorpo direito e\ndificuldade para falar há três horas. Na avaliação inicial, pressão arterial = 160 x 100 mmHg,\npulso\n\n= 90 batimentos por minuto, glicemia capilar = 100 mg/dl e saturação de oxigênio = 97%. Ao\nexame, encontra-se vígil, com afasia de Broca,\ndesvio do olhar conjugado para a esquerda e\nhemiparesia direita (escala NIHSS = 21). Antecedente patológico de hipertensão arterial sistêmica,\nsem diabetes. Na tomografia de crânio realizada com 3 horas e 30 minutos do início dos sintomas\nnão se observa nenhuma alteração aguda. Sem alterações em exames laboratoriais. Legenda:\nNIHSS = National Institutes of Health Stroke Scale. Qual a melhor terapêutica a ser tomada nesse\nmomento?","options":{"A":"Warfarin 5 mg.","B":"Clopidogrel 75 mg.","C":"Ácido acetilsalicílico 300 mg.","D":"Ativador de plasminogênio tecidual 0,9 mg/kg."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-172969","number":"172969","sourceNumber":"172969","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente, 75 anos, sexo masculino, comparece para avaliação clínica com queixa de\ntremor em membros superiores. Relata que o\nsintoma teria iniciado há cerca de 1 ano. Percebe o\ntremor principalmente em repouso e em membro superior direito. Ao exame neurológico: presença\nde tremor de repouso, assimétrico com predomínio em membro superior direito associado a\ndiscreta rigidez e bradicinesia também em membro superior direito. Durante a avaliação da marcha,\nnão se observa instabilidade postural. Qual a conduta medicamentosa mais adequada, nesse\nmomento?","options":{"A":"Primidona para controle do tremor.","B":"Propranolol para controle do tremor.","C":"Levodopa para controle da bradicinesia.","D":"Anticolinérgico para controle da bradicinesia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-172986","number":"172986","sourceNumber":"172986","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Durante visita domiciliar, você avalia um senhor de 53 anos com câncer de pulmão em\nestágio avançado, sem proposta terapêutica curativa. O paciente está consciente, apresenta\ndiscurso lúcido e está orientado quanto ao prognóstico de sua doença, sem demonstrar\ndificuldades de aceitação. Queixa-se de dispneia progressiva na última semana que chega a\nocorrer em repouso e, atualmente, pontua 7 na escala de Borg modificada (0 sem dispneia; 10\ndispneia máxima). Ao exame físico, sentado, apresenta-se emagrecido, PA = 110 x 80 mmHg,\npulso = 96 bpm, frequência respiratória = 24 irpm, SpO2 93% e expansão torácica diminuída\nsimetricamente, com dor à inspiração profunda. Ausculta respiratória apresenta diminuição do\nmurmúrio vesicular em bases. Vem em uso de codeína de 8/8h. Qual a próxima conduta para\nmelhorar o controle da dispneia do paciente?","options":{"A":"Iniciar oxigenioterapia domiciliar sob cateter.","B":"Associar Clonazepam por via oral de 12/12h.","C":"Substituir Codeína por Morfina por via oral de 4/4h.","D":"Administrar broncodilatadores por nebulização de 4/4h."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-150871","number":"150871","sourceNumber":"150871","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher de 77 anos, hipertensa e diabética, admitida na emergência com história de\nhemiparesia à esquerda e disartria iniciadas há 1 hora. Realizou tomografia computadorizada de\ncrânio sem contraste que foi normal. Exames laboratoriais colhidos na emergência não revelaram\nalterações. No momento, a paciente está monitorizada e apresenta PA: 180 x 100 mmHg; FC: 78\nbpm; saturação arterial de O2 de 93%; glicemia capilar de 300 mg/dl; e temperatura axilar de 38ºC.\nA conduta inicial mais apropriada nesse momento é:","options":{"A":"Indicar trombólise com alteplase por intravenoso.","B":"Controlar glicemia com insulina regular por via subcutânea.","C":"Aumentar oferta de oxigênio com máscara de Venturi a 50%.","D":"Reduzir níveis pressóricos com nitroprussiato de sódio intravenoso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-150851","number":"150851","sourceNumber":"150851","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 48 anos, sexo feminino, passou por tratamento com quimioterapia para\nneoplasia mamária, mas não houve benefício. No momento, além do tumor primário, recidivado\napós mastectomia, apresenta metástases cerebrais. Recebeu alta hospitalar para seguimento\ndomiciliar. Durante a visita domiciliar pela equipe de saúde, encontravam-se presentes: o esposo\nde 50 anos, muito abalado e angustiado por estar faltando frequentemente ao trabalho, apenas\nobservando de longe; a filha de 18 anos também calada e com aparência entristecida; e o filho de\n25 anos que participou ativamente da visita. A escala abaixo foi utilizada pela enfermeira enquanto\no médico conversava com a paciente e o filho. Que ações inicialmente trarão maior benefício?(VER\nIMAGEM)","options":{"A":"Antibióticos tópicos e aconselhamento do marido com assistente social.","B":"Antibióticos orais e tranquilizar a família informando que tudo vai dar certo.","C":"Antidepressivos tricíclicos e encaminhar todos os familiares para grupo de cuidadores.","D":"Analgésicos opioides de modo intermitente e encaminhar os familiares para suporte psicológico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/150851.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-126980","number":"126980","sourceNumber":"126980","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem de 62 anos, com diagnóstico de doença pulmonar obstrutiva crônica (DPOC)\nem tratamento com tiotrópio inalatório, procura\nUnidade de Pronto Atendimento (UPA) referindo\ndispneia e aumento da expectoração com cor clara há 3 dias. Ao exame, encontra-se com pulso de\n95 ppm, frequência respiratória de 24 irpm, oximetria digital com SpO2 de 90% e com sibilos\nexpiratórios difusos à ausculta pulmonar. Qual a recomendação para a prescrição de\nbroncodilatadores para esse paciente?","options":{"A":"Substituir tiotrópio por nebulização com ipratrópio.","B":"Substituir tiotrópio por salmeterol spray com espaçador.","C":"Manter tiotrópio e associar nebulização com formoterol.","D":"Manter tiotrópio e associar salbutamol spray com espaçador."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-127006","number":"127006","sourceNumber":"127006","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 50 anos, sexo feminino, é admitida no setor de emergência com hemiplegia\nesquerda de início súbito há 2 horas. Paciente tem, como única comorbidade, fibrilação atrial há\ntrês anos, sem necessidade de controle de frequência e em uso de rivaroxabana 15 mg por dia.\n\nDurante avaliação do médico plantonista, ela está orientada e descreve sua história em detalhes. O\nexame físico evidencia Pressão Arterial (PA) de 200 x 110 mmHg em repetidas aferições nos 4\nmembros, além de confirmar a hemiplegia. Não foram detectadas outras alterações relevantes.\n\nConsiderando o manuseio clínico ideal para este caso, além de manter a paciente em\nmonitorização, como deve ser feito o tratamento da PA nesse momento?","options":{"A":"Não iniciar medicamentos.","B":"Iniciar captopril por via oral.","C":"Iniciar nifedipino por via sublingual.","D":"Iniciar nitroprussiato por via endovenosa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-126934","number":"126934","sourceNumber":"126934","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um médico foi chamado por familiares para uma visita domiciliar a uma paciente de 59\nanos com câncer de mama e metástases\nósseas, sofrendo com dores intensas relacionadas\nao quadro que cediam parcialmente ao uso de paracetamol ou codeína. Há 3 dias, foi\nprescrito pelo médico oncologista morfina por via oral a cada 6 horas. Por receio de a paciente\ndesenvolver drogadição, os familiares vinham dando o medicamento somente se necessário e\npediram avaliação deste médico que fez a visita. Qual deve ser a conduta do médico visando uma\nboa prática de cuidados paliativos?","options":{"A":"Insistir em uso da morfina conforme prescrição.","B":"Preferir metadona via oral em intervalos regulares à morfina.","C":"Substituir a morfina por dipirona via oral em intervalos regulares.","D":"Preferir anti-inflamatórios não esteroides mantendo morfina sob demanda."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-102120","number":"102120","sourceNumber":"102120","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um homem de 36 anos foi admitido com dispneia importante, cianose, hipotensão\narterial, desvio traqueal e turgência jugular.\nAo exame físico, o murmúrio vesicular estava abolido\nno hemitórax direito. Na avaliação inicial, foi colocada máscara de Venturi e puncionado tórax com\nagulha calibrosa saindo muito ar sobre pressão. Após essa manobra, o paciente melhorou o quadro\nclínico, porém continuava dispneico. Referiu que este era o terceiro episódio semelhante e que o\nseu pneumologista já diagnosticara fibrose cística com comprometimento pulmonar. De acordo com\no quadro clínico descrito, a melhor conduta na emergência e tratamento sequencial são,\nrespectivamente:","options":{"A":"Drenagem torácica sob selo d?água e toracoscopia e pleurodese.","B":"Drenagem com cateter e válvula de Heimlich e toracotomia e pleurodese.","C":"Drenagem com cateter e válvula de Heimlich e toracotomia e pneumectomia.","D":"Drenagem torácica sob selo d?água, videotoracoscopia, bulectomia e pleurodese."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-102119","number":"102119","sourceNumber":"102119","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 59 anos, sexo masculino, destro, evolui com afasia súbita. Ao ser avaliado\nno setor de emergência, obedece comandos, mas\né incapaz de repetir palavras, nomear objetos ou\nformular frases. Com base nos dados apresentados, qual das imagens abaixo (cortes axiais de\nressonância magnética ponderada por difusão) representa a alteração mais provável para esse\npaciente?","options":{"A":"(VER IMAGEM).","B":"(VER IMAGEM).","C":"(VER IMAGEM).","D":"(VER IMAGEM)."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/102119.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-102128","number":"102128","sourceNumber":"102128","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Criança de três meses, assintomática, comparece ao ambulatório para checar o teste\ndo pezinho que evidencia triagem positiva para\nfibrose cística. Nessa situação, dentre as abaixo\ncitadas, qual a melhor conduta a seguir?","options":{"A":"Encaminhar a família para aconselhamento genético.","B":"Solicitar teste de eletrólitos (sódio e cloro) no suor.","C":"Solicitar nova coleta de tripsina imunorreativa (IRT).","D":"Aguardar presença de sinais e sintomas para repetir o exame."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-81259","number":"81259","sourceNumber":"81259","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente masculino, 60 anos, pós-operatório tardio de fratura do colo do fêmur\nesquerdo, comparece à emergência com quadro de\ndor intensa na perna contralateral. Ao exame,\napresenta hipersensibilidade difusa no membro comprometido e edema depressível em toda a\nperna, mais intenso na região da panturrilha, que está com diâmetro 5 cm maior em relação à perna\nesquerda. Não há eritema. Qual o exame mais indicado para comprovação da hipótese diagnóstica\nmais provável nesse caso?","options":{"A":"Venografia.","B":"Dosagem de d-dímero.","C":"Angiotomografia venosa.","D":"Ultrassonografia com Doppler."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-81293","number":"81293","sourceNumber":"81293","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente masculino, 60 anos, ex-tabagista (30 maços/ano), encaminhado à unidade de\natenção primária por apresentar dispneia aos médios esforços. Nega outros sintomas. Refere não\napresentar exacerbações frequentes. Traz radiografia de tórax (VER IMAGEM). Realizou\nespirometria com broncodilatador, que mostrou Capacidade Vital Forçada (CVF): 82% do previsto,\nVolume Expiratório Forçado no Primeiro Segundo (VEF1): 65% do previsto e VEF1/CVF: 0,53. Não\nhouve modificação significativa da espirometria após prova broncodilatadora. Considerando o\nestadiamento da doença desse paciente, qual o tratamento inalatório de primeira escolha mais\nrecomendado?","options":{"A":"Fenoterol.","B":"Formoterol.","C":"Tiotrópio e budesonida.","D":"Salbutamol e ipratrópio."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/81293.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-81291","number":"81291","sourceNumber":"81291","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Criança de 10 anos de idade, com diagnóstico de asma, chega à sala de emergência\napresentando, há 3 dias, tosse cheia e dificuldade para respirar. Ao exame clínico, o médico\nconstata: torpor, dispneia em repouso e saturação de oxigênio = 90%. Qual a gravidade clínica da\ncrise?","options":{"A":"Leve.","B":"Moderada.","C":"Grave.","D":"Persistente."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-65730","number":"65730","sourceNumber":"65730","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente feminina, 43 anos, não fumante, está em investigação de tosse crônica. Não\nhá outras comorbidades. De acordo com a\nanálise das curvas fluxo-volume e volume-tempo da\nespirometria, reproduzidas na figura (VER IMAGEM), a terapia mais recomendada será:","options":{"A":"Fonoterapia/reeducação vocal.","B":"Dilatação traqueal por broncoscopia.","C":"ß-2-adrenérgico de longa ação/corticoide inalatório.","D":"Fisioterapia respiratória reexpansiva.","E":"Imunossupressor/dose baixa de corticoide oral."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/65730.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-65736","number":"65736","sourceNumber":"65736","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um recém-nascido com 15 dias de vida, saudável, em aleitamento materno exclusivo,\nretorna ao ambulatório com resultado do\nteste de triagem neonatal ? realizado aos sete dias de\nvida ? revelando valores alterados para Tripsina Imunorreativa (IRT). Qual a recomendação\nadequada?","options":{"A":"Nada de especial deve ser recomendado.","B":"Deve ser realizado teste de eletrólitos no suor.","C":"Deve-se encaminhar a criança para atendimento especializado.","D":"Deve ser realizado novo teste do pezinho na 3ª ou 4ª semana de vida.","E":"Deve ser solicitada análise de DNA para identificação de mutações cromossômicas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-65744","number":"65744","sourceNumber":"65744","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma criança de cinco anos de idade chega à emergência com tosse e dificuldade para\nrespirar. O diagnóstico é de crise aguda de sibilância de moderada gravidade; não há relato de\ncrises de natureza grave em episódios anteriores. Qual é a terapêutica recomendada para resolver\no problema?","options":{"A":"Utilizar corticoide endovenoso.","B":"Beta-2-agonista por via inalatória, a cada 10-30 minutos, na primeira hora.","C":"Beta-agonista por via inalatória associado com sulfato de magnésio endovenoso.","D":"Beta-2-agonista por via inalatória, a cada 10-30 minutos, associado com salbutamol por via oral.","E":"Beta-2-agonista por via inalatória, a cada 10-30 minutos, associado com aminofilina endovenosa."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-65748","number":"65748","sourceNumber":"65748","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Na Emergência, o médico identifica que uma criança de três anos apresenta crise\nmoderada de sibilância, provavelmente de origem asmática. Qual a melhor opção de dispositivo\npara utilizar beta2-agonista de curta ação por via inalatória neste caso?","options":{"A":"Inalador pressurizado + espaçador com máscara.","B":"Inalador pressurizado + espaçador com bocal.","C":"Inalador pressurizado sem espaçador.","D":"Inalador de pó seco multidose.","E":"Inalador de pó seco monodose."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-51167","number":"51167","sourceNumber":"51167","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma mulher de 45 anos, não tabagista, apresenta crises de \"chiado no peito\" e tosse\nseca com dispneia matinal desde a infância. A\nfunção pulmonar, nos períodos assintomáticos, é\nreduzida (VEF1 40% do previsto, sem variação significativa após administração inalatória de\nsalbutamol). Não faz tratamento regular, utilizando apenas aerossol com broncodilatador quando\ntem sintomas. Qual o principal motivo para a redução na função pulmonar desta paciente nos\nperíodos assintomáticos?","options":{"A":"Broncoconstrição por inflamação dos espaços aéreos e pequenas vias aéreas.","B":"Remodelamento brônquico por estreitamento irreversível de pequenas vias aéreas.","C":"Inflamação crônica por hiperplasia de glândulas mucosas das pequenas vias aéreas.","D":"Hiper-responsividade brônquica por uso frequente de broncodilatadores (tolerância)."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-51181","number":"51181","sourceNumber":"51181","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente asmática procura a emergência com crise de \"falta de ar\". Não consegue\ncompletar frases inteiras. Exame físico:\nagitada, taquicárdica, com cianose de extremidades.\nAusculta pulmonar: murmúrios vesiculares diminuídos, sem ruídos adventícios. Gasometria arterial\nem ar ambiente: PaO2 de 58 mmHg e PaCO2 de 42 mmHg. Já está em uso de beta-agonista por\nvia inalatória em doses elevadas e foi administrado corticosteroide IV. Qual a conduta a seguir?","options":{"A":"Ofertar oxigênio por cateter nasal 4 L/min.","B":"Ofertar oxigênio por máscara de Venturi a 50%.","C":"Proceder à intubação orotraqueal e ventilação mecânica invasiva.","D":"Proceder à ventilação mecânica não invasiva com CPAP em torno de 10 cmH2O."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-51179","number":"51179","sourceNumber":"51179","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual dos medicamentos abaixo apresenta maior potencial de desencadear crise de\nasma?","options":{"A":"Timolol colírio.","B":"Paracetamol comprimido.","C":"Dipirona solução injetável.","D":"Ceftriaxona solução injetável."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-51289","number":"51289","sourceNumber":"51289","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"<p>Um paciente de 60 anos, há dois anos com dispneia progressiva aos esforços,\napresenta infiltrado pulmonar intersticial na\nradiografia de tórax. A tomografia computadorizada de\ntórax em alta resolução mostra bronquiectasias de tração e áreas de faveolamento em bases\npulmonares, com mínimas áreas de vidro fosco. Foi encaminhado para realização de biópsia\npulmonar cirúrgica. Qual o achado histopatológico característico para o diagnóstico mais provável\npara esse paciente?</p>","options":{"A":"Dano alveolar difuso com deposição de tecido de granulação nos septos alveolares e nas\npequenas vias aéreas e hiperplasia de músculo\nliso.","B":"Deposição de tecido de granulação nos ductos alveolares e pequenas vias aéreas e áreas de\ninflamação crônica nos septos alveolares.","C":"Áreas de pulmão normal alternadas com focos de inflamação intersticial, deposição de colágeno\nem zonas subpleurais e hiperplasia de músculo\nliso.","D":"Focos homogêneos de deposição de colágeno denso com proliferação de fibroblastos, infiltrado\nlinfocitário e hiperplasia de pneumócitos tipo I."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-45390","number":"45390","sourceNumber":"45390","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Ao exame radiológico do tórax de um paciente, observa-se doença intersticial\nassociada a derrame, com espessamento e placa pleural. Deve-se pesquisar:","options":{"A":"Sarcoidose.","B":"Amiloidose.","C":"Asbestose.","D":"Histiocitose X.","E":"Espondilite anquilosante."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-45400","number":"45400","sourceNumber":"45400","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O acúmulo anormal de líquido na cavidade pleural define o derrame ou efusão pleural.\nQuanto a isso, é verdadeiro afirmar, EXCETO:","options":{"A":"empiema pleural é a infecção supurativa do espaço pleural e é o tipo mais comum de derrame\npleural exsudativo.","B":"os derrames pleurais malignos são geralmente exsudativos, sendo os tumores de mama e\npulmão os mais frequentemente associados.","C":"todos os derrames pleurais associados a cânceres são neoplásicos e são causados por\nenvolvimento direto da superfície pleural.","D":"a melhor abordagem terapêutica é aquela dirigida à doença de base e ao derrame em si\n(toracocentese, drenagem pleural, pleurodese).","E":"a pleurodese pode ser realizada à beira do leito ou via toracoscópica e habitualmente tem altas\ntaxas de sucesso."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-37603","number":"37603","sourceNumber":"37603","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em relação à doença pulmonar obstrutiva crônica (DPOC), marque a alternativa\nincorreta.","options":{"A":"Segundo o projeto GOLD (Global Initiative for\n\nChronic Obstructive Lung Disease), a DPOC se caracteriza por limitação do fluxo aéreo totalmente\nreversível, usualmente progressivo e, em geral, está associada a uma resposta inflamatória do\npulmão a partículas ou gases nocivos.","B":"Os fatores de risco para DPOC são tabagismo, poeiras e produtos químicos ocupacionais\n(exposições intensas e prolongadas), poluição do ar\nintradomiciliar (combustão de lenha), poluição\nextradomiciliar e infecções respiratórias recorrentes.","C":"A história natural da DPOC desenrola-se ao longo de 20 ou 30 anos até que surjam os primeiros\nsintomas.","D":"Os sintomas de DPOC são tosse crônica, produção crônica de expectoração, bronquite aguda e\ndispneia progressiva, persistente, que piora com exercícios físicos e infecções respiratórias."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-30849","number":"30849","sourceNumber":"30849","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual é a condição considerada com fator de risco secundário para o desenvolvimento\nda DPOC?","options":{"A":"Sexo feminino.","B":"Idades menores.","C":"Classe socioeconômica alta.","D":"Etilismo.","E":"Menopausa precoce."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-37400","number":"37400","sourceNumber":"37400","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em relação ao tratamento da asma nos períodos intercrises, assinale a alternativa\nCORRETA:","options":{"A":"A educação do paciente acerca da doença, fatores desencadeantes, sinais de alerta e\nmedicações são muito importante para o sucesso do tratamento e o controle da\n\ndoença.","B":"O objetivo principal do tratamento é o controle sintomático e a melhora na qualidade de vida,\npara que o paciente possa beneficiar-se das terapias curativas (imunoterapia e terapia anti-IgE).","C":"O tratamento é dividido em tratamento de manutenção, como os beta-agonistas e o brometo de\nipratrópio e o tratamento de alívio sintomático, como os corticoides inalatórios e o brometo de\ntiotrópio.","D":"O tratamento deve ser escalonado de acordo com os sintomas (se houver melhora, deve-se\ndiminuir ou suspender as medicações) e a via\noral é a preferida para administração dos fármacos\nem idosos.","E":"O broncodilatador via nebulização é a droga de escolha para tratamento intercrise de\nadolescentes, pela comodidade posológica,\nficando os corticoides orais e inalatórios reservados\npara os casos de asma grave."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-37406","number":"37406","sourceNumber":"37406","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente masculino, 62 anos, aposentado, ex-tabagista (30 maços/ano), apresentando\ndispneia aos pequenos esforços e tosse com\nexpectoração clara matinal. Nega chiado no peito. Ao\nexame físico, apresenta diminuição de\n\nmurmúrio vesicular difusamente. Qual a alternativa correta em relação ao diagnóstico do quadro\nclínico deste paciente?","options":{"A":"A espirometria serve para confirmar a existência de limitação do fluxo aéreo e estadiar a doença\natravés do grau de obstrução. A radiografia\nde tórax serve para excluir condições associadas e\nfazer o diagnóstico diferencial.","B":"O diagnóstico definitivo se baseia normalmente em achados radiológicos típicos, presentes\nmesmo em fases iniciais da doença. A\nespirometria serve para o diagnóstico diferencial com outras\ncondições que causem obstrução ao fluxo aéreo.","C":"A espirometria serve para confirmar a existência de limitação do fluxo aéreo e estadiar a doença\natravés do grau de obstrução. A tomografia\ncomputadorizada de tórax deve ser solicitada de rotina\npara confirmação diagnóstica.","D":"A radiografia de tórax serve para excluir condições associadas e fazer o diagnóstico\ndiferencial.\n\nA medida do pico do fluxo expiratório substitui a espirometria na quantificação do grau de\nobstrução.","E":"A história típica e o exame físico compatível com a doença afastam a possibilidade de outras\ndoenças, sendo necessários apenas a\nradiografia de tórax e a medida do pico de fluxo inspiratório\npara a confirmação diagnóstica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-37623","number":"37623","sourceNumber":"37623","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual o tratamento de escolha da crise aguda de asma de moderada intensidade?","options":{"A":"Nebulização com beta2-agonista de curta +\npredinisolona oral.","B":"Nebulização com beta2-agonista de curta +\npredinisolona oral + acebrofilina.","C":"Aminofilina venosa + nebulização com beta2-agonista de curta + corticoide injetável.","D":"Nebulização com adrenalina + corticoide\ninjetável."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-37015","number":"37015","sourceNumber":"37015","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 34 anos procura atendimento por lesões vermelhas e dolorosas em ambas\nas pernas. Nega uso de medicamentos ou doenças\nprévias. No exame físico observam-se nódulos\ndolorosos em ambos os membros inferiores. A radiografia de tórax evidencia linfoadenopatia hilar\nbilateral. Qual o diagnóstico mais provável?","options":{"A":"Linfoma não Hodgkin.","B":"Linfoma Hodgkin.","C":"Sarcoidose.","D":"Tuberculose."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-37030","number":"37030","sourceNumber":"37030","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher de 60 anos, ex-fumante (25 maços/ano), realizou espirometria com prova\nbroncodilatadora para investigação de dispneia e tosse seca recorrentes há 6 meses. O exame\nmostrou o seguinte resultado: (VER IMAGEM)/CVF: Capacidade vital forçada VEF1: volume\nexpiratório forçado no 1º segundo. Qual o diagnóstico mais provável?","options":{"A":"Fibrose pulmonar idiopática.","B":"DPOC.","C":"Hiperresponsividade brônquica.","D":"Bronquiolite constrictiva."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/37030.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-37641","number":"37641","sourceNumber":"37641","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Dra. Marta vem acompanhando Dona Conceição, portadora de doença pulmonar\nobstrutiva crônica (DPOC). Dona Conceição foi tabagista durante 30 anos. Ela apresenta\nfrequentemente exacerbações do quadro mais graves (Grupo 2, segundo o Consenso da\nSociedade Brasileira de Pneumologia e Tisiologia). Nesse caso, qual o antimicrobiano mais\nindicado a ser prescrito?","options":{"A":"Levofloxacina.","B":"Amoxicilina.","C":"Azitromicina.","D":"Cefalosporina de segunda geração."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-30910","number":"30910","sourceNumber":"30910","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem de 50 anos, obeso, queixa-se de hipersonolência diurna e fadiga. Um estudo\npolissonográfico detectou episódios de cessação da respiração com duração entre 15 a 25\nsegundos, cerca de 35 episódios/hora com dessaturação (SpO2<88%) e manutenção do esforço\nrespiratório durante os mesmos. Qual dentre as intervenções abaixo tem maior chance de sucesso\nterapêutico?","options":{"A":"Cirurgia redutora do estômago.","B":"Uvulopalatofaringoplastia.","C":"Aplicação de dispositivo avançador de mandíbula.","D":"Uso de teofilina ou medroxiprogesterona via oral.","E":"CPAP nasal à noite."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-30928","number":"30928","sourceNumber":"30928","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher de 46 anos, ex-fumante (10 maços/ano), realizou espirometria com prova\nbroncodilatadora para investigação de\ndispneia, tosse recorrentes que mostrou o seguinte resultado\n(VER IMAGEM). CVF: Capacidade vital forçada VEF1: volume expiratório forçado no 1º segundo.\n\nQual o diagnóstico mais provável?","options":{"A":"DPOC.","B":"DPOC com hiper-responsividade brônquica.","C":"Hiper-responsividade brônquica.","D":"Asma.","E":"Bronquiolite respiratória."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/30928.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-37038","number":"37038","sourceNumber":"37038","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um homem de 42 anos, trabalhador em ?pedreira?, cortando rocha, sem máscara,\nfumante, apresenta maior risco de contrair qual doença associada ao trabalho?","options":{"A":"Asbestose.","B":"Silicose.","C":"Beriliose.","D":"Asma ocupacional."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-24306","number":"24306","sourceNumber":"24306","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A complicação mais preocupante e potencialmente letal da trombose venosa profunda\né a embolia pulmonar. Na maioria das vezes,\na anticoagulação é efetiva como método profilático,\nmas em algumas situações está indicado o uso do filtro de veia cava. Qual das situações abaixo\nNÃO representa uma destas situações?","options":{"A":"Trombose venosa profunda diagnosticada uma semana antes da operação.","B":"Tromboembolia recorrente, apesar da anticoagulação adequada.","C":"Embolia pulmonar crônica e decorrente hipertensão pulmonar.","D":"Complicações da anticoagulação."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-24356","number":"24356","sourceNumber":"24356","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em relação ao tratamento das crises agudas de asma brônquica (AB), podemos\nafirmar:","options":{"A":"Inalações repetidas de simpaticomiméticos de ação curta proporcionam alívio três a quatro\nvezes maior do que a aminofilina venosa.","B":"Cerca de 80% dos pacientes com crises agudas de AB em pronto-socorro necessitam de\ncorticóides EV.","C":"O montelukast, por sua potente ação sobre os leucotrienos, é fundamental no tratamento da\ncrise aguda de AB refratária ao corticóide.","D":"O ipatrópio não tem qualquer indicação no tratamento das crises agudas de AB, devendo ser\nusado apenas no controle a longo prazo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-6896","number":"6896","sourceNumber":"6896","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Adolescente do sexo feminino é submetida à esplenectomia por esferocitose. Após 3\nmeses de cirurgia os níveis de hemoglobina não subiram satisfatoriamente. A presença de baço\nacessório deverá ser suspeitada se no sangue periférico tiver o seguinte achado:","options":{"A":"Siderócitos.","B":"Linfocitose.","C":"Esferocitose.","D":"Trombocitopenia.","E":"Corpúsculos de Howell-Jolly."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-7296","number":"7296","sourceNumber":"7296","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"As anemias são classificadas pela sua causa e pelo tamanho da célula vermelha.\nSobre esse assunto, responda o correto.","options":{"A":"A anemia por deficiência de ferro é a mais comum, geralmente é microcítica e sua principal\ncausa é a doença crônica.","B":"São características das talassemias - espectro de anemias adquiridas - o seguinte: hipocromia,\nnormocitose e células em alvo.","C":"A síndrome mielodisplásica, caracterizada por hiperplasia eritroide decorrente da eritopoiese\nineficaz, é macrocítica e há aumento nos\ndepósitos de ferro na medula.","D":"A anemia megaloblástica por deficiência de vitamina B12 raramente é grave, precede os\nsintomas neurológicos e não causa hiperbilirrubinemia.","E":"A anemia falciforme é uma doença autossômica dominante e está relacionada à produção de\numa hemoglobina defeituosa fruto da troca de\ntirosina por valina na cadeia dessa proteína."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-8841","number":"8841","sourceNumber":"8841","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 19 anos, sabidamente asmático, procura atendimento por dispneia\nimportante e achados de exame físico\ncompatíveis com crise asmática grave. Qual conduta, dentre\nos itens abaixo, está contraindicada?","options":{"A":"Corticoide endovenoso.","B":"Broncodilatador inalatório.","C":"Oxigênio suplementar.","D":"Ansiolítico.","E":"Antibioticoterapia empírica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-9061","number":"9061","sourceNumber":"9061","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Quanto ao tratamento da asma, é CORRETO afirmar:","options":{"A":"A aminofilina EV é mais efetiva que os agentes beta-agonistas inalatórios para tratamento dos\nepisódios de exacerbação da asma.","B":"Os antibióticos devem ser usados, rotineiramente, no tratamento da exacerbação da asma.","C":"Os agentes mucolíticos (acetilcisteína e iodeto de potássio) devem ser evitados, pois podem\npiorar a tosse.","D":"Montelukaste, um novo agente beta-agonista, deve ser utilizado nas formas graves refratárias ao\nuso do corticoide EV."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-9062","number":"9062","sourceNumber":"9062","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual das seguintes doenças autoimunes pode cursar com hemoptise,\nFREQUENTEMENTE?","options":{"A":"Granulomatose de Wegener","B":"Colangite esclerosante primária","C":"Esclerodermia","D":"Doença de Still"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-9092","number":"9092","sourceNumber":"9092","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Dona Maria de Fátima, 33 anos, solteira, diarista, sabidamente asmática, procurou o\nacolhimento da Unidade de Saúde da Família sem alterações no estado geral e no estado mental,\ncom dispneia moderada, taquipneica, presença de sibilos difusos, com frequência cardíaca igual a\n120 bpm, não conseguindo falar frases completas. Qual a classificação da crise de asma de Dona\nMaria de Fátima?","options":{"A":"Leve.","B":"Moderada.","C":"Grave.","D":"Muito Grave."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-9066","number":"9066","sourceNumber":"9066","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mariana, 7 anos, atópica, portadora de asma brônquica, faz uso de várias medicações\ne realizou uma série de exames, porém apenas em\numa das opções abaixo observa-se coerência\ncom o quadro. Por favor, marque-a:","options":{"A":"Seu volume expiratório forçado no primeiro segundo está aumentado.","B":"Sua IgA sérica deve ser bastante aumentada.","C":"A IgE sérica de Mariana pode estar elevada.","D":"Nas crises graves, os anti-histamínicos são as drogas mais utilizadas por Mariana."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-8892","number":"8892","sourceNumber":"8892","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um menino de 8 anos de idade é atendido no ambulatório. Tem história de asma,\ntratada somente nas crises, com boa resposta. Há\ntrês dias apresenta tosse cheia, congestão\nnasal, febre baixa e desconforto respiratório. Seus pais estavam usando um descongestionante\nnasal de uso oral, e um xarope fitoterápico para a tosse. Ao exame, o menino apresenta-se bem,\ncom taquipneia (frequência respiratória de 40 ipm), tiragem costal leve e sibilos expiratórios à\nausculta. Não há estertores. A taxa de fluxo de pico expiratório (peak-flow-metria) é de 60%. A\nconduta imediata mais adequada é:","options":{"A":"Uso de beta-2-agonista de ação curta aerosolizado (p.ex., salmeterol), mais corticoide\ninalatório","B":"Uso de beta-2-agonista de ação curta aerosolizado (p.ex., salmeterol), mais uso de corticoide\noral","C":"Uso de beta-2-agonista de ação curta via oral (p.ex. salbutamol), corticoide oral, e Uso de\nbeta-2-agonista de ação curta aerosolizado (p.ex., salmeterol)","D":"Uso de beta-2-agonista de ação curta aerosolizado (p.ex., salmeterol) mais corticoide\nendovenoso","E":"Uso de beta-2-agonista de ação curta aerosolizado (p.ex., salmeterol), beta-2 oral, corticoide\noral\ne inalatório"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-17811","number":"17811","sourceNumber":"17811","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 47 anos admitido por erisipela evolui com piora da função renal e oligúria\n(200mL nas últimas 24h). Está com\ncrepitações pulmonares em terço inferior de ambos os pulmões\ne os exames laboratoriais evidenciam: C = 2,2 mg/dL, U = 89mg/dL, K+ = 6,1 mg/dL, HCO3 -= 13\nmg/dL. Após a execução de\n\ntodas as medidas cabíveis e possíveis (cerca de 2h depois), a paciente parou de crepitar e\napresenta os seguintes exames: C = 2,1 mg/dL, U = 85 mg/dL, K+ =\n\n4,1mg/dL, HCO3 - = 14 mg/dL. Com base nesses dados, selecione, dentre os itens abaixo, qual\nserá a melhor conduta a ser adotada.","options":{"A":"Não solicitar hemodiálise","B":"Solicitar hemodiálise justificada pela hipercalemia","C":"Solicitar hemodiálise justificada pelo edema pulmonar","D":"Solicitar hemodiálise justificada pelos níveis de ureia e creatinina","E":"Solicitar hemodiálise justificada pela acidose metabólica"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-17812","number":"17812","sourceNumber":"17812","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Que gênero de bactéria está mais frequentemente associado à síndrome nefrótica?","options":{"A":"Salmonella","B":"Shigella","C":"Escherichia","D":"Pseudomonas","E":"Streptococcus"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-17824","number":"17824","sourceNumber":"17824","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Assinale a condição associada à acidose metabólica com ânion gap normal.","options":{"A":"Fístula pancreática com perda de bicarbonato","B":"Cetoacidose diabética","C":"Acidose láctica","D":"Intoxicação por salicilatos","E":"Uremia"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-349733","number":"349733","sourceNumber":"349733","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"É considerada uma manifestação clínica comum da Doença de Parkinson a","options":{"A":"estabilidade postural.","B":"hipercinesia.","C":"fasciculação.","D":"hipermobilidade.","E":"rigidez em roda dentada."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-349720","number":"349720","sourceNumber":"349720","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A avaliação que considera múltiplas dimensões é denominada avaliação\nmultidimensional a qual estrutura e organiza\no cuidado às pessoas idosas. Em outras palavras, a\navaliação multidimensional permite a compreensão ampliada e integral do estado de saúde de um\ndeterminado indivíduo, buscando identificar e intervir nas áreas mais comprometidas e que podem\nafetar sua funcionalidade: doenças agudas ou crônicas, agravos como quedas e outros acidentes,\nquestões relativas a processos psicológicos/subjetivos ou, ainda, situações sociais, econômicas e\nculturais que podem trazer limitações para o exercício da autonomia e/ou independência. Tal\navaliação permite o direcionamento de intervenções oportunas, que respondam às reais\nnecessidades de cada pessoa, o que possibilita prognósticos mais favoráveis em sua trajetória de\nenvelhecimento. Referente à avaliação multidimensional do idoso, assinale a alternativa correta.","options":{"A":"A dimensão psicossocial enfatiza critérios sociais e étnico-raciais, sendo a questão da saúde\nmental exclusiva da dimensão clínica.","B":"A avaliação da capacidade de realizar atividades diárias (instrumentais e básicas) faz parte da\ndimensão clínica.","C":"A avaliação psicossocial busca avaliar a funcionalidade do indivíduo diante da sua comunidade.","D":"A dimensão clínica concentra-se em avaliar sinais de doenças passadas, ficando a cargo da\ndimensão funcional avaliar doenças atuais.","E":"A dimensão funcional considera de forma objetiva se uma pessoa é capaz ou não de realizar\natividades da vida diária."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-365589","number":"365589","sourceNumber":"365589","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Considere um paciente de 45 anos de idade, hipertenso e ex-tabagista (usava meio\nmaço por dia, iniciou aos 14 anos e parou com 24 anos de idade). Nega diabetes. Qual é o\nrastreamento com maior nível de evidência recomendado para esse paciente?","options":{"A":"Tomografia de tórax com baixa dosagem de radiação","B":"PSA total e livre","C":"CA 19-9","D":"Pesquisa de sangue oculto nas fezes"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-322153","number":"322153","sourceNumber":"322153","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sobre a dor, assinale a alternativa correta.","options":{"A":"Os nociceptores são responsáveis pela transdução.","B":"A dor neuropática tem como principal característica a melhora à noite e nos meses mais frios.","C":"A migrânea é um exemplo clássico de dor somática superficial.","D":"A pregabalina atua nos receptores opioides do sistema nervoso central, principalmente µ1 e µ2.","E":"A presença de injúria tecidual é essencial para a explicação do fenômeno doloroso."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-322154","number":"322154","sourceNumber":"322154","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um homem de 62 anos é levado ao hospital com história de perda de força em dimídio\ndireito, afasia e desvio de rima labial, de início há aproximadamente 40min. Após a realização de\numa tomografia computadorizada de crânio (normal, com laudo oficial do radiologista), seus sinais\nvitais são os seguintes: ? PA: 192x124 mmHg; ? Glicemia capilar: 88mg/dL; ? NlHSS: 18 pontos.\n\nNesse caso, qual é a conduta mais adequada?","options":{"A":"Chamar o neurologista de plantão.","B":"Uso de um comprimido de nifedipina 20 mg sublingual.","C":"Uso de 300 mg de ácido acetilssalicílico (AAS) por via oral.","D":"Uso de 20 mg de rivaroxabana por via oral.","E":"Controle da pressão arterial com medicação endovenosa ? alvo abaixo de 180x100 mmHg ?\nseguido de trombólise com alteplase 9 mg/Kg, na ausência de contraindicações."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-337589","number":"337589","sourceNumber":"337589","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Roberto, um homem de 58 anos, é portador de hipertensão arterial, diabetes mellitus e\nhipotireoidismo. Há cerca de dois meses, ele sofreu um AVE isquêmico, apresentando diminuição\nde força em dimidio esquerdo, necessitando de auxílio para marcha. Desde que ocorreu o AVEi,\nRoberto não recuperou completamente a função cognitiva, apresentando dificuldade em\ncompreender fala, acalculia e diminuição da memória de curto prazo. Considerando o caso descrito\ne seus conhecimentos, julgue o item a seguir. O uso de ácido acetilsalicílico está contraindicado\npara esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-337591","number":"337591","sourceNumber":"337591","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Roberto, um homem de 58 anos, é portador de hipertensão arterial, diabetes mellitus e\nhipotireoidismo. Há cerca de dois meses, ele sofreu um AVE isquêmico, apresentando diminuição\nde força em dimidio esquerdo, necessitando de auxílio para marcha. Desde que ocorreu o AVEi,\nRoberto não recuperou completamente a função cognitiva, apresentando dificuldade em\ncompreender fala, acalculia e diminuição da memória de curto prazo. Considerando o caso descrito\ne seus conhecimentos, julgue o item a seguir. Para pacientes que sofreram AVEi como Roberto,\nestá indicado o uso de estatinas de alta potência.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-337593","number":"337593","sourceNumber":"337593","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Roberto, um homem de 58 anos, é portador de hipertensão arterial, diabetes mellitus e\nhipotireoidismo. Há cerca de dois meses, ele sofreu um AVE isquêmico, apresentando diminuição\nde força em dimidio esquerdo, necessitando de auxílio para marcha. Desde que ocorreu o AVEi,\nRoberto não recuperou completamente a função cognitiva, apresentando dificuldade em\ncompreender fala, acalculia e diminuição da memória de curto prazo. Considerando o caso descrito\ne seus conhecimentos, julgue o item a seguir. Pelas informações fornecidas, é possível inferir que\nRoberto se tornou completamente dependente para atividades de vida instrumentais.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-305267","number":"305267","sourceNumber":"305267","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 85 anos, acamado há 2 anos e com quadro de demência há 1 ano, foi\ndiagnosticado com múltiplos nódulos pulmonares e lesão expansiva no cólon, sendo internado com\nquadro de dispneia intensa e saturação de O2 de 79%. O paciente já não responde a estímulos\nverbais há alguns dias e está acompanhado da filha. Qual é a melhor conduta a ser tomada nesse\nmomento?","options":{"A":"Instalar oxigenoterapia ao paciente e conversar com a filha sobre estabelecer cuidados paliativos\na ele, tendo em vista suas condições\nclínicas prévias e a provável complicação de um câncer de\ncólon metastático sem indicação de tratamento cirúrgico.","B":"Solicitar o carrinho de parada, preparar tubo orotraqueal, administrar propofol e etomidato e\nproceder intubação orotraqueal em sequência rápida.","C":"Instalar oxigenoterapia, solicitar exames laboratoriais para investigação de possível sepse e\nsolicitar biópsia com urgência para diagnosticar e tratar o provável câncer de pulmão.","D":"Instalar oxigenoterapia e orientar a filha sobre a indicação de intubação e cuidados paliativos\nem\nseguida do procedimento.","E":"Oferecer oxigenoterapia, conversar com a filha sobre cuidados paliativos devido à demência e\norientar sobre o provável diagnóstico de 2 tipos de câncer associados - câncer de pulmão e de\ncólon - com indicação cirúrgica em 2 tempos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-305292","number":"305292","sourceNumber":"305292","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sobre a escala NIHSS (National Institutes of Health Stroke Scale), é CORRETO afirmar\nque:","options":{"A":"A presença de ataxia pode ser avaliada pela manobra index-nariz ou calcanhar-joelho.","B":"A presença de mutismo causado por barreira mecânica (cânula orotraqueal, por exemplo)\ncaracteriza pontuação máxima nos itens disartria e linguagem.","C":"A pontuação, nos casos em que o paciente não possui um membro (amputação), deve ser\nmáxima na avaliação de força desse membro.","D":"A heminegliência deve ser pontuada no paciente não contatuante.","E":"A escala de NIHSS é mais importante nos casos de AVC hemorrágico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-305294","number":"305294","sourceNumber":"305294","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um homem de 34 anos é levado ao serviço médico de urgência com história de\nferimento por projétil de arma de fogo na\ncoxa direita. Ele relata que estava fazendo limpeza e\nmanutenção da sua arma, quando houve o disparo acidental. Relata que, durante alguns segundos,\nnão sentiu nenhuma dor e logo chamou por ajuda. No momento da avaliação, refere dor intensa.\n\nSobre a fisiopatologia da dor, assinale a alternativa correta.","options":{"A":"A temperatura elevada do projétil leva à inativação dos nociceptores de pele e estruturas mais\nprofundas.","B":"A dor experimentada pelo paciente pode ser caracterizada como visceral verdadeira.","C":"A retirada do projétil é essencial para uma adequada analgesia.","D":"Dentro do componente sensitivo-discriminativo, a modulação tem papel importante nesse caso e\ntem função evolutiva de proporcionar um comportamento de luta e/ou fuga.","E":"A ausência de dor nos primeiros segundos após o acidente pode estar relacionada com o\nhistórico do paciente (por exemplo: ex-militar)."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-298879","number":"298879","sourceNumber":"298879","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 16 anos de idade, com oito horas de evolução, compareceu à\nemergência por apresentar vertigem,\ndiplopia e surdez. Além disso, demonstrou deficits motores.\nAo exame físico, verificaram-se SatO2 = 96% em ar ambiente, FC = 92 bpm regular e PA = 180\nmmHg x 100 mmHg. Tomografia de crânio e angiotomografia não evidenciaram malformação\nvascular nem sangramento. Aos 15 anos, a paciente teve trombose venosa profunda. Em relação a\nesse caso clínico e aos conhecimentos médicos correlatos, julgue o item a seguir. Os sintomas da\npaciente sugerem acometimento carotídeo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-298881","number":"298881","sourceNumber":"298881","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 16 anos de idade, com oito horas de evolução, compareceu à\nemergência por apresentar vertigem,\ndiplopia e surdez. Além disso, demonstrou deficits motores.\nAo exame físico, verificaram-se SatO2 = 96% em ar ambiente, FC = 92 bpm regular e PA = 180\nmmHg x 100 mmHg. Tomografia de crânio e angiotomografia não evidenciaram malformação\nvascular nem sangramento. Aos 15 anos, a paciente teve trombose venosa profunda. Em relação a\nesse caso clínico e aos conhecimentos médicos correlatos, julgue o item a seguir. O uso de\ntrombolítico é contraindicado para essa paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-274377","number":"274377","sourceNumber":"274377","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A respeito das demências secundárias, ou aquelas que têm lesão estrutural do sistema\nnervoso central, assinale a alternativa CORRETA.","options":{"A":"A infecção pelo HIV é a causa mais comum.","B":"A demência vascular é uma forma secundária comum, e a forma de doença de Binswanger é\nrelacionada à arteriosclerose das artérias da substância branca.","C":"A Hipertensão Intracraniana com Pressão Normal (HICPN) é uma causa importante e, para seu\ndiagnóstico, observa-se a tríade de alteração da marcha com características apráxicas,\ndeterioração cognitiva e incontinência urinária. O teste de punções repetidas de líquido\ncefalorraquidiano normalmente é negativo para melhora do quadro.","D":"A doença priônica é uma causa comum em idosos.","E":"As síndromes neuroinfecciosas devem ter diagnóstico por líquido cefalorraquidiano, sendo os\nexames de neuroimagem descartados nesse caso."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-265553","number":"265553","sourceNumber":"265553","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Certa mulher, estudante de 24 anos de idade, procurou atendimento no pronto-socorro\nem razão de dor na panturrilha esquerda de\ninício nas últimas 24 horas. Ao exame físico,\napresentava índice de massa corporal (IMC) de 20, edema, calor, rubor e dor à palpação suave da\nmusculatura da panturrilha esquerda. Teste de dímero-D = 1.540 ng/mL (VR < 500 ng/mL).\n\nRealizou-se exame de ultrassonografia (US) com Doppler venoso que evidenciou trombo isolado\nem veias tibiais posteriores. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. No interrogatório clínico dessa paciente, devem ser investigados histórico\nfamiliar de tromboses, uso de anticoncepcional oral, e traumas ou cirurgias prévias, com a\nfinalidade de definição de anticoagulação perene.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-265554","number":"265554","sourceNumber":"265554","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Certa mulher, estudante de 24 anos de idade, procurou atendimento no pronto-socorro\nem razão de dor na panturrilha esquerda de\ninício nas últimas 24 horas. Ao exame físico,\napresentava índice de massa corporal (IMC) de 20, edema, calor, rubor e dor à palpação suave da\nmusculatura da panturrilha esquerda. Teste de dímero-D = 1.540 ng/mL (VR < 500 ng/mL).\n\nRealizou-se exame de ultrassonografia (US) com Doppler venoso que evidenciou trombo isolado\nem veias tibiais posteriores. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. A investigação de trombofilias hereditárias e adquiridas é indicada em\npacientes com fenômeno tromboembólico abaixo de 50 anos de idade, sem fatores causais ou\ndesencadeantes de tromboembolismo venoso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-274427","number":"274427","sourceNumber":"274427","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma mulher de 83 anos, hipertensa, sem outras comorbidades, comparece à unidade\nde saúde para verificação da pressão arterial\nde rotina. Está assintomática no momento. Utiliza\napenas um comprimido de losartana 50 mg. No momento do exame, sua pressão arterial é de\n90x60 mmHg. A paciente refere que eventualmente tem sentido tonturas, porém nega outras\nmanifestações. Tendo em vista suas características e o histórico apresentado, qual dos seguintes\nagravos representa um maior risco à saúde dessa paciente nesse contexto?","options":{"A":"Câncer de mama.","B":"Infecção urinária.","C":"Queda.","D":"Demência vascular.","E":"Depressão."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-284362","number":"284362","sourceNumber":"284362","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A detecção em indivíduos saudáveis que poderão desenvolver uma doença hereditária\nno futuro é o objetivo dos testes preditivos\n(TP). Já a epigenética é uma importante ferramenta para\nexplicar as interações entre gene e ambiente. Acerca desses temas, julgue o item. Para as doenças\nde início tardio e sem perspectivas de tratamento, como, por exemplo, as doenças\nneurodegenerativas do adulto que apresentem recorrência familiar, os testes preditivos deverão ser\nrealizados ainda na infância.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-274430","number":"274430","sourceNumber":"274430","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Tendo em vista os programas de rastreamento e seus possíveis vieses, assinale a\nalternativa correta.","options":{"A":"O diagnóstico precoce através do rastreamento é capaz de alterar o desfecho,\nindependentemente da eficácia do tratamento.","B":"Em casos de sobrediagnóstico, o principal erro é a falha no diagnóstico, podendo ser\nconsiderada como um falso-positivo do rastreamento.","C":"O rastreamento deve, preferencialmente, ser realizado para condições que não apresentem\nfases pré-clínicas bem conhecidas, aumentando o\nimpacto sobre a morbimortalidade.","D":"Ao avaliarmos a eficácia de um determinado programa de rastreamento, a forma mais confiável\nde descrever sua efetividade é a diferença na\nsobrevida em 5 anos.","E":"No viés de tempo de duração, há erro ao considerar como homogêneas evoluções heterogêneas\nna dita ?história natural das doenças?."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-284363","number":"284363","sourceNumber":"284363","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A detecção em indivíduos saudáveis que poderão desenvolver uma doença hereditária\nno futuro é o objetivo dos testes preditivos\n(TP). Já a epigenética é uma importante ferramenta para\nexplicar as interações entre gene e ambiente. Acerca desses temas, julgue o item. Nas doenças em\nque medidas terapêuticas ou de prevenção possam ser tomadas para prevenir, retardar ou\nminimizar os sintomas, como, por exemplo, os erros inatos do metabolismo, o benefício das\nmedidas preventivas justifica a realização do TP em indivíduos de qualquer idade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-262279","number":"262279","sourceNumber":"262279","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 30 anos de idade procura um serviço de atendimento médico e\ninforma que desde a infância, manifesta\nepisódios de chiado no peito, tosse seca e dispneia, os\nquais remitem espontaneamente ou com o uso de beta-2 agonista de curta duração. Percebeu um\naumento na frequência dos sintomas no último mês, agravados pelo fato de, por três vezes, ter\napresentado sintomas noturnos. Nega tabagismo ou uso de drogas ilícitas. Mora em casa com boas\ncondições sanitárias e faz trabalhos de freelancer como publicitária. O tratamento tem base no uso\nde beta-2 agonista de curta duração, quando das exacerbações. O exame físico mostra PA = 120\nmmHg x 80 mmHg, FC = 65 bpm, FR = 16 irpm, SatO2 = 98% e temperatura axilar = 36 °C. A\nausculta pulmonar é normal. Quanto a esse caso clínico e tendo em vista os conhecimentos\nmédicos correlatos, julgue o item a seguir. Um plano de educação quanto à doença deve ser\nindividualizado e entregue à paciente para que ela possa melhor monitorar a própria condição\nclínica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-239293","number":"239293","sourceNumber":"239293","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 50 anos de idade, diabética, tabagista e hipertensa, procura\natendimento médico por desvio da rima labial,\nhemiparesia direita e afasia de início há duas horas.\nEvoluiu com rebaixamento de sensório e necessidade de entubação orotraqueal. Na chegada à\nemergência, foi encaminhada à tomografia de crânio, que evidenciou acidente vascular encefálico\nisquêmico acometendo mais que 1/2 do território cerebral. Em relação a esse caso clínico e com\nbase nos conhecimentos médicos correlatos, julgue o item a seguir. Pacientes com sequelas\nneurológicas estão propensos a desenvolver depressão maior, sendo a insônia e a hipersonia\ndiária um critério diagnóstico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-239294","number":"239294","sourceNumber":"239294","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 50 anos de idade, diabética, tabagista e hipertensa, procura\natendimento médico por desvio da rima labial,\nhemiparesia direita e afasia de início há duas horas.\nEvoluiu com rebaixamento de sensório e necessidade de entubação orotraqueal. Na chegada à\nemergência, foi encaminhada à tomografia de crânio, que evidenciou acidente vascular encefálico\nisquêmico acometendo mais que 1/2 do território cerebral. Em relação a esse caso clínico e com\nbase nos conhecimentos médicos correlatos, julgue o item a seguir. A paciente deve ser\nencaminhada para trombólise química com tenecteplase em até duas horas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-239295","number":"239295","sourceNumber":"239295","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 50 anos de idade, diabética, tabagista e hipertensa, procura\natendimento médico por desvio da rima labial,\nhemiparesia direita e afasia de início há duas horas.\nEvoluiu com rebaixamento de sensório e necessidade de entubação orotraqueal. Na chegada à\nemergência, foi encaminhada à tomografia de crânio, que evidenciou acidente vascular encefálico\nisquêmico acometendo mais que 1/2 do território cerebral. Em relação a esse caso clínico e com\nbase nos conhecimentos médicos correlatos, julgue o item a seguir. Uma pressão arterial maior ou\nigual a 230 mmHg x 90 mmHg não contraindica para realização de trombólise com maior segurança\ndessa paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-239296","number":"239296","sourceNumber":"239296","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 50 anos de idade, diabética, tabagista e hipertensa, procura\natendimento médico por desvio da rima labial,\nhemiparesia direita e afasia de início há duas horas.\nEvoluiu com rebaixamento de sensório e necessidade de entubação orotraqueal. Na chegada à\nemergência, foi encaminhada à tomografia de crânio, que evidenciou acidente vascular encefálico\nisquêmico acometendo mais que 1/2 do território cerebral. Em relação a esse caso clínico e com\nbase nos conhecimentos médicos correlatos, julgue o item a seguir. Para pacientes com sequelas\npsicóticas importantes de acidente vascular cerebral, o uso de antipsicóticos típicos, como a\nquetiapina, é boa alternativa medicamentosa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-239297","number":"239297","sourceNumber":"239297","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 50 anos de idade, diabética, tabagista e hipertensa, procura\natendimento médico por desvio da rima labial,\nhemiparesia direita e afasia de início há duas horas.\nEvoluiu com rebaixamento de sensório e necessidade de entubação orotraqueal. Na chegada à\nemergência, foi encaminhada à tomografia de crânio, que evidenciou acidente vascular encefálico\nisquêmico acometendo mais que 1/2 do território cerebral. Em relação a esse caso clínico e com\nbase nos conhecimentos médicos correlatos, julgue o item a seguir. Essa paciente possui alto risco\nde síndrome de imobilidade, que ocorre em pacientes acamados por períodos prolongados, sendo\na hipercalcemia e reabsorção óssea achados frequentes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-250167","number":"250167","sourceNumber":"250167","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O rastreamento é definido como o exame de pessoas assintomáticas para a\nidentificação presuntiva de doença previamente\nnão conhecida. No que se refere ao rastreamento\nde doenças, julgue o item a seguir. Os pacientes com resultado positivo em exame de rastreamento\ndevem ser submetidos a outros procedimentos para confirmação da presença da doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-250168","number":"250168","sourceNumber":"250168","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O rastreamento é definido como o exame de pessoas assintomáticas para a\nidentificação presuntiva de doença previamente não\nconhecida. No que se refere ao rastreamento\nde doenças, julgue o item a seguir. O principal objetivo do rastreamento é melhorar o prognóstico\nda doença rastreada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-250170","number":"250170","sourceNumber":"250170","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O rastreamento é definido como o exame de pessoas assintomáticas para a\nidentificação presuntiva de doença previamente\nnão conhecida. No que se refere ao rastreamento\nde doenças, julgue o item a seguir. A realização do Papanicolau para rastreamento do câncer de\ncolo de útero tem franca superioridade em relação à realização de radiografia de tórax para câncer\nde pulmão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-239358","number":"239358","sourceNumber":"239358","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Acerca dos conhecimentos de bioestatística, das políticas de saúde e dos\nconhecimentos médicos correlatos, julgue o item a\nseguir. As políticas de rastreamento devem\npriorizar testes com maior sensibilidade, a fim de haver baixa taxa de falso-negativos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-214500","number":"214500","sourceNumber":"214500","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 65 anos de idade, tabagista pesado (dois maços de cigarro por dia) há\nmais de 15 anos, apresenta tosse e dispneia em atendimento no pronto-socorro. Os raios X de\ntórax demonstram lesão de 2 cm no segmento anterior do lobo superior esquerdo. Ao exame físico,\nverificam-se sibilos expiratórios e estertores crepitantes em bases à ausculta pulmonar, frequência\nrespiratória de 28 mrpm, frequência cardíaca de 75 bpm e saturação de O? de 88% em ar\nambiente. Com base no caso clínico apresentado e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. É possível que o quadro respiratório atual desse paciente também esteja relacionado\nà exacerbação de doença pulmonar obstrutiva crônica (DPOC) preexistente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-214506","number":"214506","sourceNumber":"214506","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 65 anos de idade, tabagista pesado (dois maços de cigarro por dia) há\nmais de 15 anos, apresenta tosse e dispneia em atendimento no pronto-socorro. Os raios X de\ntórax demonstram lesão de 2 cm no segmento anterior do lobo superior esquerdo. Ao exame físico,\nverificam-se sibilos expiratórios e estertores crepitantes em bases à ausculta pulmonar, frequência\nrespiratória de 28 mrpm, frequência cardíaca de 75 bpm e saturação de O? de 88% em ar\nambiente. Com base no caso clínico apresentado e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. No manejo terapêutico desse paciente, a primiera medida a ser adotada é a\nrealização de tomografia computadorizada de urgência, para investigação imediata da lesão de 2\ncm no segmento anterior do lobo superior esquerdo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-214388","number":"214388","sourceNumber":"214388","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 83 anos de idade, tabagista (consumiu 1 maço/dia durante 50 anos), já\ndiagnosticado previamente com quadro de DPOC, chegou à emergência levado pela filha. Refere\nqueixa de tosse produtiva, com aumento da frequência de tosse e escarro, apresentando fadiga e\nsensação de mal-estar. A filha relata que o paciente já apresentou dois episódios semelhantes\ndurante o ano, sendo tratado com antibioticoterapia. Leva consigo uma espirometria recente, com\nVEF1 = 47% do previsto e VEF1/CVF < 70%. O paciente apresenta-se em regular estado geral,\ndispneico, sonolento e confuso, com presença de roncos e estertores difusos à ausculta pulmonar.\nObservam-se temperatura axilar (Tax) = 38,1 °C, FR = 32 irpm, Sat = 92% e PA = 110 mmHg x 65\nmmHg, FC = 110 bpm. No que se refere a esse caso clínico e com base nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Quanto à estratificação de gravidade do DPOC proposta\npelo guideline Global Initiative for Chronic Obstructive Lung Disease (GOLD), a espirometria do\npaciente o encaixa no estadiamento GOLD II.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-214402","number":"214402","sourceNumber":"214402","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 83 anos de idade, tabagista (consumiu 1 maço/dia durante 50 anos), já\ndiagnosticado previamente com quadro de DPOC, chegou à emergência levado pela filha. Refere\nqueixa de tosse produtiva, com aumento da frequência de tosse e escarro, apresentando fadiga e\nsensação de mal-estar. A filha relata que o paciente já apresentou dois episódios semelhantes\ndurante o ano, sendo tratado com antibioticoterapia. Leva consigo uma espirometria recente, com\nVEF1 = 47% do previsto e VEF1/CVF < 70%. O paciente apresenta-se em regular estado geral,\ndispneico, sonolento e confuso, com presença de roncos e estertores difusos à ausculta pulmonar.\nObservam-se temperatura axilar (Tax) = 38,1 °C, FR = 32 irpm, Sat = 92% e PA = 110 mmHg x 65\nmmHg, FC = 110 bpm. No que se refere a esse caso clínico e com base nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Caso o paciente apresente um escore mMRC de 1 e um\nescore CAT de 8, levando-se em consideração a classificação integrada proposta pelo GOLD, ele\npertenceria ao grupo C (alto risco de exacerbações e pouco sintomático).","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-214408","number":"214408","sourceNumber":"214408","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 83 anos de idade, tabagista (consumiu 1 maço/dia durante 50 anos), já\ndiagnosticado previamente com quadro de DPOC, chegou à emergência levado pela filha. Refere\nqueixa de tosse produtiva, com aumento da frequência de tosse e escarro, apresentando fadiga e\nsensação de mal-estar. A filha relata que o paciente já apresentou dois episódios semelhantes\ndurante o ano, sendo tratado com antibioticoterapia. Leva consigo uma espirometria recente, com\nVEF1 = 47% do previsto e VEF1/CVF < 70%. O paciente apresenta-se em regular estado geral,\ndispneico, sonolento e confuso, com presença de roncos e estertores difusos à ausculta pulmonar.\nObservam-se temperatura axilar (Tax) = 38,1 °C, FR = 32 irpm, Sat = 92% e PA = 110 mmHg x 65\nmmHg, FC = 110 bpm. No que se refere a esse caso clínico e com base nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Em relação a exacerbações de quadros de DPOC, os\nmicro-organismos mais comumente envolvidos nas infecções bacterianas são H. influenza, S.\npneumoniae e M. catarrhalis.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-214513","number":"214513","sourceNumber":"214513","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Determinado paciente de 8 anos de idade realiza tratamento de asma em unidade\nbásica de saúde desde os quatro anos. Tem histórico de crises de sibilância infrequentes.\n\nAtualmente está em uso de corticoide inalatório diário e salbutamol durante as crises. Apresenta\nsintomas noturnos uma vez por semana, sintomas\ndiurnos ausentes, com necessidade do uso de\nsalbutamol uma vez por semana, ausência de restrição às atividades normais e VEF1 na\nespirometria normal. Acerca desse caso clínico, julgue o item a seguir. Pode-se classificar a asma\ndesse paciente como \"parcialmente controlada\".","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-214358","number":"214358","sourceNumber":"214358","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Determinado paciente de 8 anos de idade realiza tratamento de asma em unidade\nbásica de saúde desde os quatro anos. Tem histórico de crises de sibilância infrequentes.\n\nAtualmente está em uso de corticoide inalatório diário e salbutamol durante as crises. Apresenta\nsintomas noturnos uma vez por semana, sintomas\ndiurnos ausentes, com necessidade do uso de\nsalbutamol uma vez por semana, ausência de restrição às atividades normais e VEF1 na\nespirometria normal. Acerca desse caso clínico, julgue o item a seguir. As infecções de vias aéreas\nsuperiores são causa frequente de exacerbação de asma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-214384","number":"214384","sourceNumber":"214384","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Determinado paciente de 8 anos de idade realiza tratamento de asma em unidade\nbásica de saúde desde os quatro anos. Tem histórico de crises de sibilância infrequentes.\n\nAtualmente está em uso de corticoide inalatório diário e salbutamol durante as crises. Apresenta\nsintomas noturnos uma vez por semana, sintomas\ndiurnos ausentes, com necessidade do uso de\nsalbutamol uma vez por semana, ausência de restrição às atividades normais e VEF1 na\nespirometria normal. Acerca desse caso clínico, julgue o item a seguir. A espirometria do referido\npaciente pode apresentar um distúrbio ventilatório obstrutivo com resposta ao broncodilatador.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-214389","number":"214389","sourceNumber":"214389","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Determinado paciente de 8 anos de idade realiza tratamento de asma em unidade\nbásica de saúde desde os quatro anos. Tem histórico de crises de sibilância infrequentes.\n\nAtualmente está em uso de corticoide inalatório diário e salbutamol durante as crises. Apresenta\nsintomas noturnos uma vez por semana, sintomas\ndiurnos ausentes, com necessidade do uso de\nsalbutamol uma vez por semana, ausência de restrição às atividades normais e VEF1 na\nespirometria normal. Acerca desse caso clínico, julgue o item a seguir. Uma das opções\nterapêuticas é a associação de antagonista do receptor dos leucotrienos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-196603","number":"196603","sourceNumber":"196603","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Suponha que o secretário de Saúde de uma metrópole brasileira com cerca de 5\nmilhões de habitantes precise gerenciar a\nalocação dos recursos da própria pasta entre as diversas\nnecessidades do sistema de saúde municipal, incluindo os serviços primário, secundário e terciário\nnas respectivas ações de prevenção, tratamento e reabilitação. Acerca de todo o planejamento que\nenvolve a função desse servidor público, julgue o item a seguir. Na definição das estratégias de\nrastreamento que serão utilizadas para determinada doença, o secretário certamente adotará\naquelas que apresentarem maior especificidade em detrimento da sensibilidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-196686","number":"196686","sourceNumber":"196686","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 62 anos de idade, branca, com histórico de hipertensão arterial\nsistêmica, diabetes mellitus, sedentarismo,\nobesidade e depressão, e que faz uso de metformina,\nglicazida, enalapril, hidroclorotiazida, sertralina e diazepam, vai a consulta de rotina. A respeito\ndesse caso clínico e com base nos conhecimentos de saúde do idoso, julgue o ítem a seguir. Com\nessa paciente, deve-se abordar a prevenção de quedas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-196697","number":"196697","sourceNumber":"196697","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 62 anos de idade, branca, com histórico de hipertensão arterial\nsistêmica, diabetes mellitus, sedentarismo,\nobesidade e depressão, e que faz uso de metformina,\nglicazida, enalapril, hidroclorotiazida, sertralina e diazepam, vai a consulta de rotina. A respeito\ndesse caso clínico e com base nos conhecimentos de saúde do idoso, julgue o ítem a seguir.\n\nIdosos apresentam maior risco de quedas quando são do sexo feminino e usam polifarmácia,\nrevelam histórico de quedas anteriores e idade\nacima de 80 anos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-196702","number":"196702","sourceNumber":"196702","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 62 anos de idade, branca, com histórico de hipertensão arterial\nsistêmica, diabetes mellitus, sedentarismo,\nobesidade e depressão, e que faz uso de metformina,\nglicazida, enalapril, hidroclorotiazida, sertralina e diazepam, vai a consulta de rotina. A respeito\ndesse caso clínico e com base nos conhecimentos de saúde do idoso, julgue o ítem a seguir. O\nrastreamento da neoplasia de cólon está indicado para essa paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-177598","number":"177598","sourceNumber":"177598","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"J.S.A., de 55 anos de idade, negra, viúva, com três filhos, hígida, com alimentação\nsaudável, assídua praticante de exercício\nfísico, vai à consulta para a realização de exames de\nrotina. Refere menopausa há 15 anos. Ao exame físico completo, não se encontra nenhuma\nalteração, exceto palidez de mucosas. Apresenta hemograma realizado em pronto atendimento por\nqueixas gripais, há 2 semanas, com anemia microcítica e índice de anisocitose aumentado. Com\nrelação à avaliação desse quadro, julgue o item a seguir. A paciente ainda deve ser incluída nos\nprogramas de rastreamento de neoplasia de colo do útero e de mama.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-177648","number":"177648","sourceNumber":"177648","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"No contexto da Atenção Primária à Saúde, eventualmente, encontram-se prontuários\nque relatam todo o curso de vida de certo\npaciente, desde o período gestacional até a idade adulta,\nincluindo-se o período reprodutivo. Suponha que o M.S.F., atualmente com 28 anos de idade, foi\nacompanhada, no posto de saúde, durante toda a sua vida, desde a própria gestação da qual foi\nfruto. Ao longo de sua vida, várias estratégias de prevenção e programas de rastreamento foram\nefetuados e, eventualmente, continuarão sendo utilizados ao longo de seu envelhecimento. A\npaciente é sexualmente ativa, solteira, negra, com dois filhos (2 e 4 anos de idade), secretária,\nnão\ntabagista, não etilista, fisicamente ativa, com IMC = 22,5 e PA = 125 mmHg x 70 mmHg na última\nconsulta. A respeito dessas estratégias e desses programas e considerando as recomendações\ndos cadernos de Atenção Básica do Ministério da Saúde, julgue o item a seguir. Os programas de\nrastreamento devem ser aplicados conforme as normas do Ministério da Saúde,\nindependentemente das expectativas e dos temores dos pacientes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-177654","number":"177654","sourceNumber":"177654","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"No contexto da Atenção Primária à Saúde, eventualmente, encontram-se prontuários\nque relatam todo o curso de vida de certo\npaciente, desde o período gestacional até a idade adulta,\nincluindo-se o período reprodutivo. Suponha que o M.S.F., atualmente com 28 anos de idade, foi\nacompanhada, no posto de saúde, durante toda a sua vida, desde a própria gestação da qual foi\nfruto. Ao longo de sua vida, várias estratégias de prevenção e programas de rastreamento foram\nefetuados e, eventualmente, continuarão sendo utilizados ao longo de seu envelhecimento. A\npaciente é sexualmente ativa, solteira, negra, com dois filhos (2 e 4 anos de idade), secretária,\nnão\ntabagista, não etilista, fisicamente ativa, com IMC = 22,5 e PA = 125 mmHg x 70 mmHg na última\nconsulta. A respeito dessas estratégias e desses programas e considerando as recomendações\ndos cadernos de Atenção Básica do Ministério da Saúde, julgue o item a seguir. Enquanto os testes\nde triagem utilizados nos programas de rastreamento apresentam alta especificidade, os testes de\nconfirmação diagnóstica apresentam alta sensibilidade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-177665","number":"177665","sourceNumber":"177665","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"No contexto da Atenção Primária à Saúde, eventualmente, encontram-se prontuários\nque relatam todo o curso de vida de certo\npaciente, desde o período gestacional até a idade adulta,\nincluindo-se o período reprodutivo. Suponha que o M.S.F., atualmente com 28 anos de idade, foi\nacompanhada, no posto de saúde, durante toda a sua vida, desde a própria gestação da qual foi\nfruto. Ao longo de sua vida, várias estratégias de prevenção e programas de rastreamento foram\nefetuados e, eventualmente, continuarão sendo utilizados ao longo de seu envelhecimento. A\npaciente é sexualmente ativa, solteira, negra, com dois filhos (2 e 4 anos de idade), secretária,\nnão\ntabagista, não etilista, fisicamente ativa, com IMC = 22,5 e PA = 125 mmHg x 70 mmHg na última\nconsulta. A respeito dessas estratégias e desses programas e considerando as recomendações\ndos cadernos de Atenção Básica do Ministério da Saúde, julgue o item a seguir. Os exames para\nHIV e sifílis devem ser realizados anualmente independentemente de autorização do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-177686","number":"177686","sourceNumber":"177686","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O escopo da abordagem comunitária do médico de família foge do completo isolamento\ndo consultório médico, envolvendo, também, ações\nde modificação do ambiente da comunidade,\nvisando à promoção da qualidade de vida e à prevenção de doenças da população. Considerando\nesse contexto, Rafael, residente do 2º ano de medicina de família e comunidade, procurou auxílio\nda prefeitura para implantar um programa de incentivo à atividade física, na área geográfica de sua\natuação, o qual incluía a revitalização da praça próxima ao posto, a implantação de academia ao ar\nlivre e a pista de caminhada. Três vezes por semana, Rafael investia a 1ª hora de sua manhã\norganizando um grupo de caminhada e orientando a população na prática de exercícios físicos.\n\nConsiderando a situação hipotética apresentada e os conhecimentos médicos correlatos, julgue o\nitem a seguir. É indispensável a realização de exame médico antes dos idosos iniciarem o\nprograma de caminhada, mesmo que em baixa intensidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-289428","number":"289428","sourceNumber":"289428","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 7 anos de idade foi encaminhada pelo clínico da rede básica para\nacompanhamento. Ela apresenta, desde os três anos de idade, episódios de sibilância associados\na tosse, dispneia aos esforços, prurido nasal, coriza e espirros frequentes. Já faz uso, há três\nmeses, de corticoide inalatório em dose baixa e beta-agonista de ação prolongada, além de\n\nbeta-agonista de curta duração nas exacerbações. No último mês, apresentou sintomas diurnos\napenas durante dois dias, nega cansaço nas\natividades físicas e a necessidade de medicações de\nresgate, e apresentou apenas um despertar noturno por tosse e sibilância. Revisando-se a técnica\nde uso das medicações inalatórias, observa-se que a mesma está correta, e que todas as medidas\nde higiene ambiental já foram tomadas. Considerando esse caso clínico, julgue o item a seguir. Se\nalterada a medicação, mesmo com melhora dos sintomas, deve-se manter a nova dose por pelo\nmenos mais três meses.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-289432","number":"289432","sourceNumber":"289432","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 7 anos de idade foi encaminhada pelo clínico da rede básica para\nacompanhamento. Ela apresenta, desde os três anos de idade, episódios de sibilância associados\na tosse, dispneia aos esforços, prurido nasal, coriza e espirros frequentes. Já faz uso, há três\nmeses, de corticoide inalatório em dose baixa e beta-agonista de ação prolongada, além de\n\nbeta-agonista de curta duração nas exacerbações. No último mês, apresentou sintomas diurnos\napenas durante dois dias, nega cansaço nas\natividades físicas e a necessidade de medicações de\nresgate, e apresentou apenas um despertar noturno por tosse e sibilância. Revisando-se a técnica\nde uso das medicações inalatórias, observa-se que a mesma está correta, e que todas as medidas\nde higiene ambiental já foram tomadas. Considerando esse caso clínico, julgue o item a seguir.\n\nPode-se prescrever o uso de corticoide inalatório em dose média/alta, associado a teofilinas de\nliberação lenta, e deve-se suspender o beta-agonista de ação prolongada, pois este não deve ser\nusado em pacientes menores de 10 anos de idade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-289435","number":"289435","sourceNumber":"289435","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 7 anos de idade foi encaminhada pelo clínico da rede básica para\nacompanhamento. Ela apresenta, desde os três anos de idade, episódios de sibilância associados\na tosse, dispneia aos esforços, prurido nasal, coriza e espirros frequentes. Já faz uso, há três\nmeses, de corticoide inalatório em dose baixa e beta-agonista de ação prolongada, além de\n\nbeta-agonista de curta duração nas exacerbações. No último mês, apresentou sintomas diurnos\napenas durante dois dias, nega cansaço nas\natividades físicas e a necessidade de medicações de\nresgate, e apresentou apenas um despertar noturno por tosse e sibilância. Revisando-se a técnica\nde uso das medicações inalatórias, observa-se que a mesma está correta, e que todas as medidas\nde higiene ambiental já foram tomadas. Considerando esse caso clínico, julgue o item a seguir.\n\nPode-se prescrever o uso de corticoide inalatório em dose média/alta, associado a antileucotrienos,\ne deve-se suspender o beta-agonista de ação\nprolongada, pois este não deve ser usado em\npacientes menores de 10 anos de idade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-152173","number":"152173","sourceNumber":"152173","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 80 anos de idade comparece à consulta e relata que, ao desembarcar de\num ônibus, perdeu-se e foi levada para casa\npor sua vizinha. Sua filha, na consulta, refere que, às\nvezes, a paciente esquece os fogões da casa ligados e ainda esquece compromissos marcados,\ncom mais facilidade. Durante a consulta, foi realizado o miniexame do estado mental, que foi\ncompatível com demência. A escala de depressão geriátrica não demonstrou depressão. Exames\nlaboratoriais foram normais, bem como uma tomografia de crânio adequada para a faixa etária.\n\nConsiderando esse caso clínico e os conhecimentos médicos a ele relacionados, julgue o item a\nseguir. Memantina, inibidor da dopamina, deve ser iniciado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-152165","number":"152165","sourceNumber":"152165","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 80 anos de idade comparece à consulta e relata que, ao desembarcar de\num ônibus, perdeu-se e foi levada para casa\npor sua vizinha. Sua filha, na consulta, refere que, às\nvezes, a paciente esquece os fogões da casa ligados e ainda esquece compromissos marcados,\ncom mais facilidade. Durante a consulta, foi realizado o miniexame do estado mental, que foi\ncompatível com demência. A escala da depressão geriátrica não demonstrou depressão. Exames\nlaboratoriais foram normais, bem como uma tomografia de crânio adequada para a faixa etária.\n\nConsiderando esse caso clínico e os conhecimentos médicos a ele relacionados, julgue o item a\nseguir. É contraindicado realizar diagnóstico de Alzheimer em pessoas acima de 90 anos de idade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-131817","number":"131817","sourceNumber":"131817","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Conforme a Sociedade Brasileira de Pneumologia e Tisiologia a respeito da asma,\nassinale a alternativa CORRETA:","options":{"A":"O diagnóstico de certeza é exclusivamente clínico, pois os sinais e sintomas da asma são\nespecíficos dessa condição.","B":"Os sintomas pioram no início da tarde e melhoram, sobretudo, à noite ou nas primeiras horas da\nmanhã.","C":"Exposições ocupacionais podem ter relação com a asma de início recente em adultos.","D":"Entre os achados no exame, a sibilância é o mais importante, pois está sempre presente nos\npacientes com asma.","E":"Uma espirometria normal exclui o diagnóstico de asma."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-108122","number":"108122","sourceNumber":"108122","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Com relação à Trombose Venosa Profunda (TVP), julgue os itens a seguir: A TVP pode\ndar origem a uma embolia pulmonar, sendo o\ncoágulo levado da perna acometida para o pulmão,\npassando pela veia femural profunda, veia cava inferior, veia porta, veia ázigos, veia cava\nsuperior,\nátrio direito, ventrículo direito e artéria pulmonar.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-108123","number":"108123","sourceNumber":"108123","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Com relação à Trombose Venosa Profunda (TVP), julgue os itens a seguir: A\nconsequência mais grave da TVP é a hemorragia\nvaricosa de membros inferiores, que pode levar\nao choque hipovolêmico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-108124","number":"108124","sourceNumber":"108124","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Com relação à Trombose Venosa Profunda (TVP), julgue o item a seguir: o\nespessamento e as alterações de coloração da\npele no membro acometido são eventos que podem\nocorrer nos casos de TVP com evolução crônica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-108198","number":"108198","sourceNumber":"108198","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de vinte anos de idade compareceu a uma unidade básica de saúde\ninformando apresentar, há três meses, tosse e\nchiados no peito, os quais vêm se agravando\nprogressivamente. Esse quadro tem se manifestado em associação com rinorreia e prurido nasal. O\nexame físico mostrou edema de cornetos nasais e sibilos expiratórios em ambas as regiões\ninfraescapulares. Com base nesse caso clínico, julgue o item a seguir. Para que se confirme o\ndiagnóstico desse paciente, deverá ser realizado o teste de espirometria.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-108222","number":"108222","sourceNumber":"108222","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de vinte anos de idade compareceu a uma unidade básica de saúde\ninformando apresentar, havia três meses, tosse e\nchiados no peito os quais vêm se agravando\nprogressivamente. Esse quadro tem se manifestado em associação com rinorreia e prurido nasal. O\nexame físico mostrou edema de cornetos nasais e sibilos expiratórios em ambas as regiões\ninfraescapulares. Com base nesse caso clínico, julgue o item a seguir. Sibilos expiratórios indicam\ngravidade do processo e demandam que o paciente seja encaminhado para serviço de\nemergência.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-108174","number":"108174","sourceNumber":"108174","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"No item abaixo é apresentado um caso clínico referente a doenças respiratórias na\ninfância, seguido de uma assertiva a ser\njulgada. Um escolar de nove anos de idade, com\ndificuldade para respirar, foi levado pela mãe a uma emergência pediátrica. A mãe informou que,\nhavia dois meses, esse quadro vinha se repetindo semanalmente, que os sintomas cediam\ntemporariamente com o uso de beta-2-adrenérgicos e que a atividade e o sono do paciente ficavam\nlimitados na vigência do quadro. O médico, após examiná-lo, admnistrou beta-2-adrenérigco por via\ninalatória e o encaminhou ao ambulatório para avaliação da função respiratória, que apresentou o\nseguinte resultado: volume expiratório forçado ao final do primeiro minuto (VEF1)\n\npré-broncodilatador = 85% do previsto com variação de VEF1 igual a 25%. Nesse caso, as\nDiretrizes Brasileiras para o Manejo da Asma\nrecomendam tratamento com beta-2-adrenérgico por\nvia inalatória para alívio dos sintomas e corticoide inalatório em baixa dosagem.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-79649","number":"79649","sourceNumber":"79649","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A Tomografia Computadorizada de Alta Resolução (TCAR) é uma ferramenta crítica\npara a avaliação das doenças pulmonares. Ao\nverificar o remodelamento do pulmão em favo de\nmel (faveolamento), reflete-se o estágio terminal de um número de doenças que causam destruição\ndo parênquima. Ao observar esse tipo de imagem, com faveolamento intenso, é possível sugerir\ndiagnóstico de: I. Pneumonia intersticial; II. Fibrose pulmonar idiopática; III. Sarcoidose; IV.\nTuberculose miliar. É CORRETO o que está contido em:","options":{"A":"I, II, III e IV.","B":"I, II e III, apenas.","C":"I e II, apenas.","D":"III e IV, apenas.","E":"IV, apenas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-79657","number":"79657","sourceNumber":"79657","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A Tomografia Computadorizada de Alta Resolução (TCAR) é uma ferramenta crítica\npara a avaliação das doenças pulmonares. Ao\nverificar o remodelamento do pulmão em favo de\nmel (faveolamento), reflete-se o estágio terminal de um número de doenças que causam destruição\ndo parênquima. Com base nos critérios de diagnóstico com TCAR e vendo imagens bem definidas\nde faveolamento, é possível sugerir Fibrose Pulmonar Idiopática, excluindo o seguinte critério\nepidemiológico:","options":{"A":"Idade < que 50 anos.","B":"Excesso de citocinas fibrogênicas.","C":"Resultado anormal em teste de função pulmonar.","D":"Doenças de colágeno vascular.","E":"Uso de drogas fibrogênicas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-88653","number":"88653","sourceNumber":"88653","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Acerca de doenças crônicas, julgue o item subsequente. A asma brônquica é uma\ndoença ainda sem cura.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-88659","number":"88659","sourceNumber":"88659","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Acerca de doenças crônicas, julgue o item subsequente. Os fumantes correm o risco\n200% maior de sofrer um acidente vascular cerebral que os não fumantes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-88706","number":"88706","sourceNumber":"88706","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Acerca de doenças crônicas, julgue o item subsequente. A espirometria, que mede as\ntaxas de ar inalado e expirado, constitui uma importante ferramenta de avaliação dos pacientes\nportadores de doenças pulmonares obstrutivas crônicas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-79642","number":"79642","sourceNumber":"79642","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Criança asmática, com episódios de dispneia, tosse e sibilância duas vezes por\nsemana, não sendo diários, com limitação\nfísica somente para grandes esforços. Algumas crises\nrequerendo curso de corticoide. Este quadro de asma pode ser classificado como","options":{"A":"aguda grave.","B":"intermitente.","C":"persistente leve.","D":"persistente moderada.","E":"persistente grave."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-82059","number":"82059","sourceNumber":"82059","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Com relação às doenças respiratórias e infecciosas, julgue o item a seguir. A doença\npulmonar obstrutiva crônica é uma enfermidade\nrespiratória passiva de prevenção e tratável, que se\ncaracteriza pela presença de obstrução crônica do fluxo aéreo brônquico, e que está associada a\numa resposta inflamatória anormal dos pulmões à inalação de partículas ou gases tóxicos, causada\nprimariamente pelo tabagismo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-88734","number":"88734","sourceNumber":"88734","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de oitenta e um anos de idade, portadora de câncer de cólon, relatou\nque, havia dois dias, tinha iniciado quadro\nde adinamia, anorexia, picos febris (> 38,5°C)\nacompanhados de tosse produtiva com escarro purulento e dispneia. No exame físico, a paciente\napresentou-se febril, acianótica, com frequência cardíaca de 112 bpm, frequência respiratória de 28\nrespirações por minuto, saturação de oxigênio em ar ambiente de 88% e pressão arterial de 106\nmmHg x 68 mmHg. A ausculta pulmonar revelou estertores crepitantes em terço inferior do pulmão\ndireito. O restante do exame físico não revelou alterações significativas. O exame de raios X do\ntórax mostrou consolidação no lobo inferior do parênquima pulmonar direito. Com base nesse caso\nclínico, julgue o item subsecutivo. O uso de heparina de baixo peso molecular durante a internação\nhospitalar é desnecessário.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-88736","number":"88736","sourceNumber":"88736","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de cinquenta e cinco anos de idade foi levado ao hospital devido à\ntentativa de suicídio por meio da inalação\nde monóxido de carbono. No exame físico, o paciente\napresentou-se comatoso, acianótico e hemodinamicamente normal. A gasometria demonstrou pH =\n7; pCO? = 31; pO? = 93; HCO? = 7; BE = -4,1 e saturação de oxigênio = 91%. Em relação a esse\ncaso clínico, julgue o item que se segue. Recomenda-se a adoção de intubação orotraqueal do\npaciente e de ventilação com oxigênio a 100%.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-82053","number":"82053","sourceNumber":"82053","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de trinta anos de idade procurou assistência médica, relatando que\napresentava, havia quatro meses, chiados\ndiurnos no peito, na frequência de três vezes por\nsemana, e despertar noturno, na frequência de uma vez por semana. O médico prescreveu o uso\nde beclometasona 250 mcg, diariamente, de 12/12h, bem como sabultamol 100 mcg para aliviar os\nsintomas. Na consulta de retorno, três meses após a primeira visita, a paciente relatou que o\ntratamento melhorara os sintomas noturnos, no entanto, não fizera efeito sobre os sintomas\ndiurnos. A paciente negou qualquer limitação de atividade física diária. Considerando o caso clínico\napresentado, julgue o item subsecutivo. Na consulta de retorno, constatou-se que houve controle\nparcial dos sintomas; logo, deve-se insistir no tratamento por mais seis meses.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-82055","number":"82055","sourceNumber":"82055","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de trinta anos de idade procurou assistência médica, relatando que\napresentava, havia quatro meses, chiados\ndiurnos no peito, na frequência de três vezes por\nsemana, e despertar noturno, na frequência de uma vez por semana. O médico prescreveu o uso\nde beclometasona 250 mcg, diariamente, de 12/12h, bem como sabultamol 100 mcg para aliviar os\nsintomas. Na consulta de retorno, três meses após a primeira visita, a paciente relatou que o\ntratamento melhorara os sintomas noturnos, no entanto, não fizera efeito sobre os sintomas\ndiurnos. A paciente negou qualquer limitação de atividade física diária. Considerando o caso clínico\napresentado, julgue o item subsecutivo. A doença apresentada pela paciente deve ser classificada\ncomo persistente leve.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-82057","number":"82057","sourceNumber":"82057","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de trinta anos de idade procurou assistência médica, relatando que\napresentava, havia quatro meses, chiados\ndiurnos no peito, na frequência de três vezes por\nsemana, e despertar noturno, na frequência de uma vez por semana. O médico prescreveu o uso\nde beclometasona 250 mcg, diariamente, de 12/12h, bem como sabultamol 100 mcg para aliviar os\nsintomas. Na consulta de retorno, três meses após a primeira visita, a paciente relatou que o\ntratamento melhorara os sintomas noturnos, no entanto, não fizera efeito sobre os sintomas\ndiurnos. A paciente negou qualquer limitação de atividade física diária. Considerando o caso clínico\napresentado, julgue o item subsecutivo. O tratamento prescrito à paciente em questão está de\nacordo com o preconizado pelas principais diretrizes sobre o assunto.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-88676","number":"88676","sourceNumber":"88676","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Com relação ao tromboembolismo venoso, à osteoporose e à infecção do trato urinário,\njulgue o item seguinte. A uretra curta, a\nfalta de ingestão de líquidos e as infecções vaginais são\nfatores predisponentes à infecção do trato urinário, cujo agente infeccioso mais comum é o E. coli.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-88686","number":"88686","sourceNumber":"88686","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Com relação ao tromboembolismo venoso, à osteoporose e à infecção do trato urinário,\njulgue o item seguinte. A tríade de\nVirchow, que indica o aumento do risco da trombose venosa\nprofunda, caracteriza-se pela presença de hipercoagulabilidade, fluxo sanguíneo anormal e dano\ndo endotélio vascular.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-88696","number":"88696","sourceNumber":"88696","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Com relação ao tromboembolismo venoso, à osteoporose e à infecção do trato urinário,\njulgue o item seguinte. O diagnóstico de\nosteoporose - cujo tratamento apropriado é feito com\nmedicamentos que estimulam a formação óssea, como os antracíclicos - é realizado por\ndensitometria óssea, com laudo de T score abaixo de 1,5.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-64700","number":"64700","sourceNumber":"64700","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em relação a pacientes com DPOC, assinale a alternativa que apresenta a alteração na\ngasometria que permite definir agudização da insuficiência respiratória.","options":{"A":"Acidose.","B":"Bicarbonato menor do que 34.","C":"PaCO2 superior a 50 mmHg.","D":"Alcalose.","E":"PaO2 menor do que 40 mmHg."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-45727","number":"45727","sourceNumber":"45727","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A pandemia de Influenza ocorrida em 2009 foi causada por um novo subtipo viral\nderivado de uma linhagem suína, o Influenza A\nH1N1. Uma das diferenças entre as infecções\ncausadas por esse novo agente e as causadas pelo vírus sazonal que circulava anteriormente é o\n(a):","options":{"A":"Transmissão respiratória e por contato.","B":"Maior risco de óbito em portadores de doença pulmonar prévia.","C":"Possibilidade de tratamento com antivirais.","D":"Alta incidência de formas graves em adultos jovens saudáveis.","E":"Predomínio de manifestações respiratórias."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-45746","number":"45746","sourceNumber":"45746","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma mãe leva seu filho de seis anos de idade ao pronto-socorro (PS) em virtude de\ntosse, cansaço e chiado no peito há três dias.\nInforma que é a quarta vez no mês que ele vai ao PS\npelo mesmo motivo, e que, na última vez, a criança precisou ficar em observação por 24 horas.\n\nNega febre ou sintomas gripais no momento. Informa que esses quadros pioram na época de frio.\nRelata que ele tosse muito quando brinca de corrida e que ele acorda pelo menos duas vezes por\nmês por causa da tosse e (ou) do cansaço. Na consulta, a criança apresenta-se reativa, consciente,\nhidratada, afebril, com boa perfusão periférica, FC: 130 bpm, FR: 32 irpm, SaO2: 92%, ausculta\npulmonar com sibilos expiratórios disseminados por todo tórax. Nesse caso, é correto o PS\nprescrever três nebulizações em uma hora com soro fisiológico (0,9%) mais:","options":{"A":"Adrenalina (1/1.000 ?uma ampola), na primeira nebulização, e fenoterol (cinco gotas) na\nsegunda e na terceira nebulizações.","B":"Fenoterol (cinco gotas) e uma dose de prednisolona oral.","C":"Fenoterol (cinco gotas) e uma dose de dexametasona oral.","D":"Adrenalina (1/1.000 ? uma ampola) na segunda e na terceira nebulizações.","E":"Adrenalina (1/1.000 ? uma ampola) e uma dose de dexametasona intramuscular."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-52627","number":"52627","sourceNumber":"52627","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de vinte anos de idade, com diagnóstico de asma brônquica, apresenta\nchiado no peito e tosse diária, de forma não\ncontínua, e falta ao trabalho algumas vezes devido aos\nsintomas. Tais sintomas surgem duas vezes por semana, geralmente ao subir escadas e à noite; e,\npara o alívio imediato, o paciente utiliza broncodilatador três vezes por semana ? uma vez por dia.\nCom frequência, ele necessita buscar o atendimento de emergência, onde, geralmente, recebe\nprescrição de corticoides sistêmicos. Considerando esse caso clínico julgue o item a seguir: Com\nreferência à atual classificação nacional e internacional, é correto classificar o referido paciente\ncomo portador de asma intermitente.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-32143","number":"32143","sourceNumber":"32143","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em pacientes portadores de DPOC, muitas terapias são direcionadas para o alívio dos\nsintomas e para a diminuição da frequência e da gravidade das exacerbações, sem, no entanto,\nalterar a progressão da doença. Assinale a alternativa que apresenta a intervenção que\ndemonstrou efeito positivo sobre a história natural da doença, reduzindo a taxa de declínio da\nfunção pulmonar.","options":{"A":"Antibioticoterapia adequada durante exacerbações.","B":"Agentes anticolinérgicos.","C":"Interrupção do tabagismo.","D":"Beta-agonistas.","E":"N-acetilcisteína."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-32154","number":"32154","sourceNumber":"32154","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Fábio, cinco anos de idade, foi levado ao pronto-socorro (PS) na madrugada de um dia\nmuito frio por apresentar chiado no peito, cansaço, tosse emetizante e falta de ar. A mãe relatou\nque ele tem tido quadros semelhantes até três vezes por mês, e que rotineiramente ele apresenta\ntosse matutina e cansaço durante as atividades como correr e jogar bola. Além disso, ao menos\numa vez por semana, ele acorda subitamente à noite com falta de ar. A respeito desse caso,\nassinale a alternativa correta tendo como base as VI Diretrizes Brasileiras para o manejo da Asma.","options":{"A":"A conduta inicial do PS será a administração de uma nebulização com soro fisiológico e três\ngotas de Fenoterol, sendo o paciente liberado para casa com prescrição de broncodilatador oral\n(Salbutamol de oito em oito horas).","B":"Após a estabilização do quadro, deve-se solicitar uma prova de função pulmonar (espirometria),\nque demonstrará um distúrbio ventilatório de tipo\nrestritivo, caracterizando a doença.","C":"Após a alta, o tratamento de manutenção ou profilaxia, será feito com corticoide inalatório\nassociado a broncodilatador de longa duração.","D":"A imunoterapia está indicada para todo paciente portador da doença descrita no caso.","E":"A doença descrita é mais frequente no sexo feminino, durante a infância, e no masculino, ao\nlongo da adolescência."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-352378","number":"352378","sourceNumber":"352378","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Segundo dados do DATASUS, em 2019 foram realizados mais de 5 milhões de\nprocedimentos cirúrgicos, com mortalidade\nperioperatória geral de 1,6%. Com o envelhecimento da\npopulação e o aumento da expectativa de vida, tais procedimentos são realizados em uma\npopulação com idade média mais avançada e prevalência de maior comorbidades. Nesse contexto,\navaliação clínica perioperatória ganha cada vez mais importância na tentativa de diminuir\ncomorbidades e a mortalidade perioperatórias. Tendo o texto apenas como caráter informativo e\nlevando em conta o tema que ele suscita e seus conhecimentos prévios, julgue o item a seguir.\n\nQuanto à avaliação geral do nível de atividade do paciente, é importante mencionar diversas\nferramentas de medição, como as Escalas de\nDuke, as Atividades Instrumentais de Vida Diária,\nbem como escalas específicas no contexto oncológico, a exemplo do Eastern Cooperative\nOncology Group e da Escala de Karnofsky. Além disso, para a classificação adequada destas\núltimas, é relevante considerar exames complementares, como hemograma, avaliação da função\nrenal, dos níveis de transaminases e do coagulograma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-352401","number":"352401","sourceNumber":"352401","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 68 anos de idade deu entrada com uma cefaleia de início súbito,\ndescrita como a pior que já experimentou,\nacompanhada de rebaixamento do nível de consciência.\nImediatamente, foi assegurada a via aérea e uma tomografia foi realizada, cuja imagem está\napresentada abaixo. A respeito do quadro clínico apresentado, da imagem acima e de seus temas\ncorrelatos, julgue o item a seguir. Trata-se de quadro clássico de hemorragia subaracnóidea (HSA)\ncom hemoventrínculo e classificação Fischer 5 e Hunt-Hess IV.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/352401.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-352400","number":"352400","sourceNumber":"352400","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 68 anos de idade deu entrada com uma cefaleia de início súbito,\ndescrita como a pior que já experimentou,\nacompanhada de rebaixamento do nível de consciência.\nImediatamente, foi assegurada a via aérea e uma tomografia foi realizada, cuja imagem está\napresentada abaixo. A respeito do quadro clínico apresentado, da imagem acima e de seus temas\ncorrelatos, julgue o item a seguir. A hemorragia vítrea pode ocorrer e é um indicativo de\nprognóstico\ndesfavorável. Portanto, é essencial realizar a fundoscopia em todos os pacientes diagnosticados\ncom HSA.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/352400.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-352399","number":"352399","sourceNumber":"352399","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 68 anos de idade deu entrada com uma cefaleia de início súbito,\ndescrita como a pior que já experimentou,\nacompanhada de rebaixamento do nível de consciência.\nImediatamente, foi assegurada a via aérea e uma tomografia foi realizada, cuja imagem está\napresentada abaixo. A respeito do quadro clínico apresentado, da imagem acima e de seus temas\ncorrelatos, julgue o item a seguir. Em pacientes em tratamento com anticoagulantes, é fundamental\nadministrar a reversão de forma ágil assim que disponível. O idarucizumabe é utilizado para\nreverter a ação da dabigatrana, enquanto o andexanet alfa é indicado para reverter a ação da\napixabana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/352399.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-352392","number":"352392","sourceNumber":"352392","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Considerando a imagem acima e os conceitos suscitados por ela, julgue o item a\nseguir. Trata-se de cortes de regiões analisadas\npelo Alberta Stroke Program Early CT Score que\navalia apenas acidentes vasculares encefálicos isquêmicos no território de artéria cerebral média e\nquanto maior a pontuação, maior a área de isquemia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-352391","number":"352391","sourceNumber":"352391","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Considerando a imagem acima e os conceitos suscitados por ela, julgue o item a\nseguir. No contexto da ressonância magnética,\nas sequências de difusão (DWI) positiva e a FLAIR\n(Fluid-Attenuated Inversion Recovery) negativa são altamente sensíveis. A presença dessas\ncaracterísticas é suficiente para concluir a avaliação do mismatch e prever que o déficit ocorreu há\nmenos de 4,5 horas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-343396","number":"343396","sourceNumber":"343396","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"As síndromes geriátricas compartilham diversas características, embora heterogêneas.\nElas são altamente prevalentes entre idosos,\nsobretudo idosos frágeis, têm impacto significativo na\nqualidade de vida, comprometem de forma substancial a funcionalidade dos indivíduos e costumam\nser multifatoriais, acometendo, no seu desenvolvimento, diversos órgãos e sistemas. Dentre as\nalternativas abaixo, a que só contém síndromes geriátricas é:","options":{"A":"Incapacidade cognitiva, depressão, movimentos involuntários.","B":"Incontinência urinária, instabilidade e quedas, iatrogenia.","C":"Imobilidade, mal de Parkinson, reumatismo.","D":"Osteoporose, perda de autonomia, deterioração cognitiva."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-343397","number":"343397","sourceNumber":"343397","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sobre os tipos de disbasia (alteração da marcha), é CORRETO afirmar:","options":{"A":"Marcha espástica: essa é a característica de intoxicação alcoólica ou por barbitúricos. O\npaciente embriagado titubeia, cambaleia, inclina-se\npara diante e para trás, parecendo, a cada\nmomento, que está prestes a perder o equilíbrio e cair. O controle sobre o tronco e as pernas fica\nmais comprometido.","B":"Marcha vestibular: quando o doente tem paralisia do movimento de flexão do pé ao tentar\ncaminhar, toca com a ponta do pé o solo e\ntropeça. Para evitar, levanta acentuadamente o membro\ninferior, lembrando o ?passo de ganso?.","C":"Marcha escavante: o paciente, para caminhar, acentua a lordose lombar e vai inclinando o\ntronco ora para direita, ora para esquerda,\nalternadamente, lembrando o andar de um pato.\nObservada nos pacientes com diminuição da força dos músculos pélvicos e da coxa, e também nas\nmulheres grávidas.","D":"Marcha Parkinsoniana: o doente anda como um bloco, enrijecido, sem o movimento automático\ndos braços. A cabeça permanece inclinada para\nfrente e os passos são curtos e rápidos, dando a\nimpressão de que o doente ?corre atrás do seu centro de gravidade? e que vai cair pra frente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-343401","number":"343401","sourceNumber":"343401","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"CMS, sexo feminino, 37 anos, dá entrada no pronto socorro relatando estar com ?a pior\ndor de cabeça da sua vida?. Refere início súbito, associada a náuseas e vômitos. Informou que\ncom frequência apresenta alterações visuais que duram em torno de 15 minutos, com sucessão de\ndores de cabeça do tipo pulsátil. No exame neurológico, encontrava- se sonolenta, sem sinais\nfocais, reflexos cutâneos plantares flexores e com rigidez de nuca (++/4+). O diagnóstico e o exame\ninicial mais indicados são:","options":{"A":"Hemorragia subaracnóidea por sangramento de aneurisma intracraniano; TC de crânio sem\ncontraste.","B":"Crise de migrânea com aura; angiorressonância do crânio.","C":"Crise de migrânea sem aura; punção lombar.","D":"Estado migranoso; angiografia com subtração digital."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-307098","number":"307098","sourceNumber":"307098","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma paciente de 72 anos de idade foi levada ao pronto-socorro, relatando que, no dia\nanterior, acordou com dificuldade para falar, movimentar o braço e a perna direitos e notou que a\nboca estava ?torta? ao exame. Ela estava consciente, com PA = 178 x 116 mmHg, FC = 84 bpm,\nFR = 16 irpm e SatO? = 98% em ar ambiente. A tomografia de crânio realizada após dois dias de\ninternação revela hipodensidade leucocortical de limites parcialmente definidos envolvendo\nterritório\nda artéria cerebral média esquerda. Tendo em vista esse caso clínico e os conhecimentos médicos\ncorrelatos, assinale a alternativa correta.","options":{"A":"A hipertensão não entra como fator de risco para os eventos isquêmicos cerebrais.","B":"O início de corticosteroides e uso profilático de drogas antiepilépticas são recomendados no\ntratamento desse paciente.","C":"Nesse caso, recomenda-se a administração de ácido acetilsalicitico, dose inicial de 325 mg nas\nprimeiras 24 horas a 48 horas.","D":"Nessa paciente, a fibrilação atrial não seria fator de risco pelo evento ter acometido o sistema\nnervoso central.","E":"A reabilitação precoce em nada contribui em pacientes estáveis clinicamente, sem apresentar\nimpacto no prognóstico depois do evento."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-263354","number":"263354","sourceNumber":"263354","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um homem com 55 anos de idade é encaminhado para esclarecimento diagnóstico de\ndéficit cognitivo associado a transtornos do movimento com suspeita de síndrome de Parkinson.\n\nNesse caso, qual é o achado semiológico que contribui para esse diagnóstico?","options":{"A":"Reflexos patelares exaltados associados à presença de clônus de rótula e de pés.","B":"Tremor em repouso, de baixa frequência e algo assimétrico (predominando na mão direita).","C":"Diminuição da sensibilidade vibratória e da propriocepção consciente nos membros inferiores.","D":"Presença de oftalmoplegia internuclear com alterações graves na mirada conjugada horizontal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-263361","number":"263361","sourceNumber":"263361","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um homem com 51 anos de idade, assintomático, comparece à consulta agendada na\nUnidade de Saúde da Família do seu bairro. Afirma ter procurado atendimento porque sua última\nconsulta médica foi há 7 anos e ficou apreensivo após seu vizinho comentar que havia descoberto\num câncer no intestino depois de realizar exames de rotina. Nega comorbidades, uso regular de\nmedicamentos, cirurgias prévias e história de câncer na família. Como o médico de família deve\nabordar essa situação?","options":{"A":"Solicitar o exame de sangue oculto nas fezes e orientar que ele é suficiente para o diagnóstico\nde câncer de cólon e reto.","B":"Orientar que os exames para detecção de câncer de cólon e reto devem ser realizados apenas\nem pacientes com sinais e sintomas.","C":"Solicitar o exame de sangue oculto nas fezes e orientar que, se positivo, o paciente poderá\nrealizar colonoscopia para avaliação.","D":"Orientar que o exame de colonoscopia para rastreamento do câncer de cólon e reto está\nindicado apenas para pessoas com história familiar da doença."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-263367","number":"263367","sourceNumber":"263367","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um homem com 62 anos de idade chega à sala de emergência de um hospital com\nquadro de instalação abrupta, há cerca de\n1 hora, de monoparesia superior direita associada à\nafasia não fluente. O paciente, que tem histórico de diabete melito tipo 2, vem usando metformina\n850 mg 2 vezes por dia, além de Ácido Acetilsalicílico (AAS), devido à ocorrência de fibrilação\natrial\nparoxística recorrente, tendo um ponto no escore CHA2DS2-VASc. Não há outras morbidades nem\nalergias. Na admissão hospitalar, o paciente mantém o déficit, que parece ter piorado um pouco\nnos últimos minutos. Está acordado, angustiado com a inegável afasia não fluente (Broca) e com\ndiminuição moderada da força no membro superior direito. Apresenta PA = 160 x 100 mmHg, FC =\n110 bpm, com ritmo cardíaco irregular e com anisocardiosfigmia. Neste momento, apresenta\nglicemia capilar = 300 mg/dl. O paciente é imediatamente encaminhado para a realização de uma\ntomografia computadorizada de crânio sem contraste, cuja imagem é apresentada na figura a\nseguir, tendo o laudo sido liberado cerca de 2 horas e 30 minutos após o início do quadro\nneurológico. Diante desse quadro, quais são o diagnóstico e a conduta médica adequados nesse\nmomento?","options":{"A":"Ataque isquêmico transitório; iniciar anticoagulação plena endovenosa em associação ao AAS.","B":"Acidente vascular encefálico isquêmico; proceder à trombólise imediata com rtPA.","C":"Acidente vascular encefálico isquêmico; contraindicar a terapia trombolítica.","D":"Ataque isquêmico transitório; associar clopidogrel ao AAS."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/263367.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-291498","number":"291498","sourceNumber":"291498","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente masculino, com 62 anos de idade, vem à consulta médica na atenção\nsecundária ambulatorial, encaminhado por tremor. O\npaciente conta que, há alguns meses, teve\ninício com tremor no braço direito e que, agora, parece ter progredido para ambos os braços e\nambas as pernas. O paciente diz que o tremor piora quando ele \"está nervoso\", mas que parece\nmelhorar quando faz alguma atividade, como cozinhar ou comer. Entretanto, o paciente conta que é\ndifícil, para ele, levantar-se da posição sentada e começar a andar. Também refere que perde o\nequilíbrio quando está caminhando e \"muda de rota\", e tem dificuldade para parar de caminhar,\nrelatando duas quedas no mês anterior à consulta. Com base no que foi apresentado, o diagnóstico\ndesse paciente é:","options":{"A":"Tremor essencial.","B":"Paralisia supranuclear progressiva.","C":"Doença de Huntington.","D":"Doença de Parkinson."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-263378","number":"263378","sourceNumber":"263378","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A equipe de Saúde da Família recebeu uma solicitação de visita domiciliar para um\npaciente com 74 anos de idade, que obteve\nalta hospitalar no dia anterior. A esposa e cuidadora do\npaciente mostrou a contrarreferência do hospital, informando que o paciente esteve internado por\ncâncer de próstata avançado com metástases ósseas e que recebeu alta com cuidados paliativos.\nAdemais, o paciente é hipertenso, diabético, acamado há 1 ano, em uso de sonda nasoenteral\ndevido a um acidente vascular encefálico e sem perspectiva de tratamento curativo. A esposa\nestava bastante angustiada e não entendia como o marido tinha recebido alta naquelas condições,\npois gemia e, à noite, gritava de dor, mesmo em uso de paracetamol e codeína (500 mg + 30 mg),\nque foram mantidos na alta hospitalar. Qual é a conduta médica correta para esse paciente?","options":{"A":"Iniciar morfina solução oral 10 mg/mL, 10 gotas, de 4 em 4 horas para controle de dor intensa\nem cuidados paliativos.","B":"Manter paracetamol, codeína e adicionar anti-inflamatório não esteroidal para otimizar\ntratamento da dor.","C":"Iniciar tramadol em solução oral 100 mg/mL, 20 gotas, de 12 em 12 horas, para controle de dor\nintensa.","D":"Encaminhar para reinternação hospitalar para controle da dor com morfina endovenosa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-273358","number":"273358","sourceNumber":"273358","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Ao considerar um teste de triagem potencial, quais pontos finais devem ser\nconsiderados para avaliar o ganho potencial de uma intervenção proposta?","options":{"A":"Impacto absoluto e relativo da triagem no desfecho da doença","B":"Aumento da expectativa média de vida de toda a população","C":"Número de indivíduos selecionados para alterar o resultado em um indivíduo","D":"Todas opções acima"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-291507","number":"291507","sourceNumber":"291507","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma mulher de 61 anos foi trazida ao pronto-socorro devido à disartria e hemiparesia\ndireita há 3 horas. Ela estava em uma\nreunião de trabalho quando, subitamente, iniciou com os\nsinais e sintomas. O serviço móvel de urgência foi acionado e, após a avaliação inicial, fez contato\ncom o pronto-socorro para receber a paciente. Não há relato de episódios prévios, infarto do\nmiocárdio, cirurgia ou hemorragia recentemente, apenas de hipertensão arterial há 10 anos, em uso\nde losartana 50mg, 2 vezes ao dia. O exame físico não apresenta maiores alterações, exceto por\nredução de força em membro superior e inferior direito. A paciente estava alerta, contudo, parecia\nter alguma dificuldade para compreensão dos comandos do médico urgencista. Sua pressão\narterial é de 120 x 80 mmHg, frequência cardíaca = 92 bpm, com 18 movimentos respiratórios por\nminuto. Se a tomografia computadorizada de crânio não mostrar sinais de sangramento, a conduta\na ser adotada imediatamente é","options":{"A":"encaminhamento para tratamento endovascular.","B":"admissão em unidade de terapia intensiva para estabilização.","C":"administração de Alteplase, via endovenosa.","D":"administração de ácido acetil salicílico e observação em unidade semi-intensiva."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-266499","number":"266499","sourceNumber":"266499","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Marta, de 69 anos de idade, acompanhava seu esposo em uma consulta médica de\nrotina. O casal aguardava o atendimento\nquando, de repente, Marta começou a passar mal. O\nesposo dela, então, pediu ajuda, aos gritos, afirmando \"Marta está tendo uma bilora, não fala nada\ncom nada!\" (sic). A médica Joana prontamente atendeu Marta e iniciou a avaliação dela. Na\navaliação clínica da paciente, constatou-se hemiparesia à esquerda, anisocoria, afasia, nível 14 na\nescala de Glasgow (AO4/RV 4/RM6), pressão arterial de 190 mmHg x 120 mmHg, frequência\ncardíaca de 52 bpm e glicemia capilar de 294 mg/dL. Considerando o caso clínico precedente,\njulgue o próximo item. Se não houver sinais de lesão em órgãos-alvo, o caso deve ser tratado como\nprovável pseudocrise hipertensiva, cabendo à médica Joana exercer demora permitida, administrar\nà paciente dois comprimidos de captopril 25 mg e um de diazepan 5 mg, por via oral, e questionar a\npaciente sobre o que a estaria afligindo no momento, buscando entendê-la como um todo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-274680","number":"274680","sourceNumber":"274680","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem, 52 anos, sem história clínica significativa de doença, não toma nenhuma\nmedicação regularmente. Seu pai morreu aos 74 anos\npor ataque cardíaco. Sua mãe tem 80 anos\ne é hipertensa. Dois irmãos mais jovens não têm nenhuma condição clínica crônica conhecida. Não\nfuma, não ingere álcool, não usa drogas e não faz exercícios. Ao exame, sua pressão arterial é de\n127/82 mmHg, pulso de 80 batimentos por minuto (bpm), frequência respiratória de 18 movimentos\nrespiratórios por minuto (mpm), altura de 1,70 me peso 86,25 kg. O exame físico cuidadoso não\nrevela nenhuma anormalidade. Considerando a saúde do paciente apresentado:","options":{"A":"A manutenção da saúde deve visar à prevenção de futuras doenças.","B":"Está dispensada a abordagem para imunizações, rastreamento de câncer e de doenças\ncomuns.","C":"Deve-se iniciar o rastreamento do câncer de colo somente a partir dos 60 anos.","D":"Como não há risco para doenças cardiovasculares, o rastreamento de cardiovasculopatias ou\nfatores de risco é dispensado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-274684","number":"274684","sourceNumber":"274684","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um dos conjuntos de doença com maior iniciativa para implantação de sistemas de\nrastreamentos são as neoplasias malignas. São situações onde os estudos reconhecem franca\nsuperioridade do rastreamento, EXCETO:","options":{"A":"Colorretal (pesquisa de sangue oculto nas fezes, retossigmoidoscopia e colonoscopia).","B":"Colo de útero (Papanicolau).","C":"Mama (mamografia).","D":"Autoexame: câncer de mama e de pele."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-230553","number":"230553","sourceNumber":"230553","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Na Artéria Carótida Interna (ACI) as ondas de velocidade de fluxo são normalmente de\nbaixa resistência. Assim podemos APENAS concordar que:","options":{"A":"Na Artéria Carótida Externa (ACE) o padrão da onda de velocidade é de baixa resistência,\nenquanto na Artéria Carótida Comum (ACC) é do tipo\nintermediário entre as carótidas interna e\nexterna.","B":"Na Artéria Carótida Externa (ACE) o padrão da onda de velocidade é de alta resistência,\nenquanto na Artéria Carótida Comum (ACC) é do\ntipo elevado entre as carótidas interna e externa.","C":"Na Artéria Carótida Externa (ACE) o padrão da onda de velocidade é sem resistência, enquanto\nna Artéria Carótida Comum (ACC) é do tipo\nintermediário entre as carótidas interna e externa.","D":"Na Artéria Carótida Externa (ACE) o padrão da onda de velocidade é de alta resistência,\nenquanto na Artéria Carótida Comum (ACC) é do\ntipo intermediário entre as carótidas interna e\nexterna."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-230584","number":"230584","sourceNumber":"230584","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sobre isquemia cerebral de origem extracraniana, marque a CORRETA:","options":{"A":"A arterite de Takayasu pode levar a isquemia cerebral extracraniana, sendo mais comum em\nhomens a partir da sexta década de vida.","B":"A displasia fibromuscular ocorre mais frequentemente em pacientes do sexo feminino.","C":"A aterosclerose não é causa comum de ataque isquêmico transitório e de acidente vascular\ncerebral.","D":"Na displasia fibromuscular a cirurgia de endarterectomia de carótidas é sempre o melhor\ntratamento."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-230591","number":"230591","sourceNumber":"230591","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A endarterectomia de carótida é uma cirurgia consagrada no tratamento da isquemia\ncerebral de origem extracraniana. Sobre suas complicações, é CORRETO afirmar:","options":{"A":"A microembolização cerebral pode levar a acidente vascular encefálico.","B":"A lesão intra-operatória do nervo vago causa alteração motora de metade da língua.","C":"A lesão do nervo hipoglosso pode levar a regurgitações alimentares, com broncoaspiração e\npneumonia de repetição.","D":"O ramo mandibular do nervo facial quando lesado leva a dificuldade em emitir notas de timbre\nagudo e resulta em fatigabilidade da voz."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-230623","number":"230623","sourceNumber":"230623","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A redução da polifarmácia podem diminuir o nível de fragilidade e os desfechos\nadversos e os riscos das intervenções. Podemos\napenas CONCORDAR que:","options":{"A":"A identificação da fragilidade não deve ser vista como uma razão para se negar ou suspender\ntratamentos, mas como um meio para se\nprogramarem intervenções individualizadas e centradas\nno paciente.","B":"A identificação da fragilidade deve ser vista como uma razão para se negar ou suspender\ntratamentos, mas como um meio para se programarem\nintervenções individualizadas e centradas\nno paciente.","C":"A identificação da fragilidade não deve ser vista como uma razão para se negar ou suspender\ntratamentos, nunca como um meio para se\nprogramarem intervenções individualizadas e centradas\nno paciente.","D":"A identificação da fragilidade não deve ser vista como uma razão para se negar ou suspender\ntratamentos, mas como um meio para se programarem intervenções gerais e não centradas no\npaciente."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-230624","number":"230624","sourceNumber":"230624","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Independentemente do instrumento para rastreio e identificação utilizado, a síndrome\nde fragilidade deve ser pesquisada em todos idosos\nacima de 70 anos de idade e naqueles com\nDCV, podemos assim CONCORDAR que:","options":{"A":"Assim mesmo que abaixo dessa faixa etária, medidas para a sua prevenção e tratamento não\ndevem ser operacionalizadas.","B":"Assim mesmo que abaixo dessa faixa etária, medidas para a sua prevenção e tratamento devem\nser operacionalizadas.","C":"Assim abaixo dessa faixa etária, medidas para a sua prevenção e tratamento não devem ser\noperacionalizadas.","D":"Assim mesmo que abaixo dessa faixa etária, medidas para a sua prevenção e tratamento nunca\ndevem ser operacionalizadas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-230629","number":"230629","sourceNumber":"230629","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A vulnerabilidade faz com que, diante de um insulto aparentemente pequeno como uma\ninfecção ou introdução de um novo medicamento, ou mesmo uma pequena cirurgia ocorra uma\nevidente e desproporcional mudança no estado de saúde do paciente, sendo CORRETO que:","options":{"A":"Essas mudanças podem ser exemplificadas como alterações de status de dependente para\nindependente, de capaz de se locomover para imobilidade, de equilíbrio e marcha estáveis para\nelevado risco de quedas, de lúcido para delirante.","B":"Essas mudanças podem ser exemplificadas como alterações de status de independente para\ndependente, de capaz de se locomover para imobilidade, de equilíbrio e marcha estáveis para\nelevado risco de quedas, sem evoluir para delirante.","C":"Essas mudanças podem ser exemplificadas como alterações de status de independente para\ndependente, de capaz de se locomover para imobilidade, de equilíbrio e marcha estáveis para\nelevado risco de quedas, de lúcido para delirante.","D":"Essas mudanças não podem ser exemplificadas como alterações de status de independente\npara dependente, de capaz de se locomover para\nimobilidade, de equilíbrio e marcha estáveis para\nelevado risco de quedas, de lúcido para delirante."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-227453","number":"227453","sourceNumber":"227453","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um homem de sessenta e um anos de idade, sem diagnósticos prévios nem queixas,\nprocurou atendimento em UBS, para iniciar acompanhamento. Considerando essa situação, e de\nacordo com o Caderno de Atenção Básica de Rastreamento, julgue o próximo item. O médico da\nfamília e comunidade, com o intuito de fazer o rastreamento adequado, deverá: verificar o uso de\nálcool e tabaco, aferir sua pressão arterial, calcular seu IMC e solicitar hemograma, lipidograma,\nglicemia de jejum e PSA.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-230637","number":"230637","sourceNumber":"230637","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A partir de estudo cardiovascular criou critérios diagnósticos conhecidos como o\n\n?Fenótipo da Fragilidade de Fried et al.?, ou ?Escala de Rastreio de Fragilidade do\nCardiovascular?. Podemos apenas CONCORDAR que:","options":{"A":"Estudo cardiovascular identificou as seguintes manifestações da síndrome: perda de peso\nintencional, fraqueza muscular, exaustão (fadiga), redução da velocidade da marcha e diminuição\ndo grau de atividade física.","B":"Estudo cardiovascular identificou as seguintes manifestações da síndrome: perda de peso não\nintencional, fraqueza muscular, exaustão (fadiga), redução da velocidade da marcha, mas não\ndiminuição do grau de atividade física.","C":"Estudo cardiovascular identificou as seguintes manifestações da síndrome: perda de peso não\nintencional, fraqueza muscular, exaustão (fadiga), redução da velocidade da marcha e diminuição\ndo grau de atividade física.","D":"Estudo cardiovascular identificou as seguintes manifestações da síndrome: perda de peso não\nintencional, mas sem fraqueza muscular, exaustão ou fadiga."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-212075","number":"212075","sourceNumber":"212075","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma senhora de 65 anos de idade relatou em consulta médica que apresentava leve\nlentidão havia oito meses e que sua letra cursiva manual tinha ficado menor. Nos últimos meses,\nela havia desenvolvido um tremor na mão esquerda durante repouso. Negou outras doenças,\nexceto uma constipação nos últimos seis meses. Seu exame físico mostrou frequência reduzida ao\npiscar, além de micrografia, associada à rigidez e à bradicinesia leve no lado esquerdo.\n\nConstatou-se tremor de repouso intermitente no membro superior esquerdo, quando ela estava\ncaminhando. O restante do exame clínico e a Ressonância Magnética (RM) cranioencefálica\nestavam normais. Foi confirmado o diagnóstico de doença de Parkinson. A respeito do caso clínico\napresentado, julgue o item a seguir. O tremor mencionado, no caso em tela, tem características\ntípicas, sendo uma delas a frequência de quatro a seis ciclos por segundo (Hertz - Hz),\nnormalmente com uma aparência de \"rolar pílulas\" ou \"contar dinheiro\" quando envolve a mão. Em\ngeral, esse tremor está presente quando o membro está em repouso completo e, frequentemente,\nsofre redução quando o membro se move e ocupa nova posição.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-206162","number":"206162","sourceNumber":"206162","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual das alterações cardiovasculares abaixo NÃO é considerada como decorrente do\navançar da idade em pacientes geriátricos?","options":{"A":"Redução do número de miócitos.","B":"Redução da dependência de pré-carga.","C":"Redução da responsividade ?-adrenérgica.","D":"Disfunção diastólica aumentada."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-183944","number":"183944","sourceNumber":"183944","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A respeito da doença de Parkinson, julgue o seguinte item. Na doença de Parkinson, o\ntremor manifesta-se como tremor de ação em movimentos erráticos, amplos e irregulares, na\nfrequência de dez a vinte ciclos por segundo, que ocorrem com a movimentação do membro e\ndesaparecem completamente no repouso.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-183950","number":"183950","sourceNumber":"183950","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A respeito da doença de Parkinson, julgue o seguinte item. A presença de anticorpos\nantirreceptores de acetilcolina no sangue representa importante marcador indicativo do diagnóstico\nde doença de Parkinson.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-183900","number":"183900","sourceNumber":"183900","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Acerca das causas, do tratamento e das consequências relacionadas às quedas de\nidosos, julgue o item a seguir. Situação Hipotética: Uma idosa de setenta e oito anos de idade\nprocurou assistência médica com relato de queda da própria altura associada à perda do equilíbrio\ndurante mudanças posturais. Assertiva: A principal hipótese diagnosticada a ser investigada nessa\npaciente é de distúrbios muscoloesqueléticos, que podem incluir fraqueza muscular e instabilidade\narticular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-177231","number":"177231","sourceNumber":"177231","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"As políticas públicas de rastreamento de doenças englobam várias populações de\nrisco, em diferentes faixas etárias.\nConsiderando as informações contidas no Caderno de Atenção\nBásica - Rastreamento, assinale a alternativa correta.","options":{"A":"A solicitação de hemograma completo em torno de 1 ano de vida é indicada para o rastreamento\nda anemia na população infantil.","B":"O rastreio do câncer de próstata com PSA sérico e toque retal está indicado universalmente na\npopulação masculina a partir dos 50 anos de idade.","C":"Em mulheres com sangramento pós-menopausa, o rastreamento da neoplasia de endométrio\npode ser realizado mediante biópsia\nendometrial por histeroscopia.","D":"A pesquisa de sangue oculto nas fezes pode ser utilizada como opção para rastreamento da\nneoplasia de cólon entre os 50 anos de idade e os 75 anos de idade.","E":"O programa de rastreamento da neoplasia de mama deve ser iniciado com a mamografia em\nmulheres a partir de 60 anos de idade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-183910","number":"183910","sourceNumber":"183910","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A cerca das causas, do tratamento e das consequências relacioandas às quedas de\nidosos, julgue o item a seguir. Escadas com\ndegraus de altura ou largura irregular, tapetes\npequenos ou capachos em superfícies lisas, móveis deslizantes, roupas excessivamente compridas\ne escadas com iluminação frontal são exemplos de riscos domésticos para quedas de idosos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-177239","number":"177239","sourceNumber":"177239","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem de 48 anos de idade, assintomático, sem queixas, sem comorbidades, sem uso\nde drogas lícitas ou ilícitas, comparece em\nconsulta de rotina solicitando \"exames para ver se está\ntudo bem\". O exame físico é normal. Considerando as recomendações do Ministério da Saúde,\nassinale a alternativa que indica um exame que deve ser solicitado para o referido caso.","options":{"A":"PSA.","B":"Colonoscopia.","C":"Colesterol total.","D":"TSH.","E":"Testosterona"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-177226","number":"177226","sourceNumber":"177226","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em relação à sarcopenia na população idosa, definida como a perda de massa e de\nfunção muscular, que ocorre ao longo dos anos, podendo ser intensificada pela presença de\ndoenças crônicas, assinale a alternativa correta:","options":{"A":"O diagnóstico de sarcopenia é realizado exclusivamente pela análise da massa muscular com\ndensitometria, bioimpedância ou análise de dobras cutâneas.","B":"O uso de ésteres de testosterona injetável é indicado para a recuperação de massa magra\nnesses pacientes.","C":"A insulinoterapia com insulinas de ação longa é uma das estratégias terapêuticas aprovadas\npara aumentar-se o anabolismo muscular desses\npacientes.","D":"Na população idosa em geral, o treinamento de potência é menos efetivo que o de força quando\nestudam-se desfechos de funcionalidade.","E":"A prática de exercício físico resisitido e o aumento da ingesta proteica resultaram em efeitos\npositivos em vários ensaios clínicos com idosos sarcopênicos."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-159614","number":"159614","sourceNumber":"159614","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente do sexo masculino, de oitenta e três anos de idade, portador de mal de\nAlzheimer e que, havia seis anos, sofrera\ninfarto agudo do miocárdio, o que motivou a colocação de\nstent em sua artéria coronária direita, apresentou quadro súbito de paralisia do dimidio esquerdo,\nbem como alteração da fala e do nível de consciência. Ao ter sido internado na UTI,\n\ndiagnosticou-se AVCI no paciente. Durante o período de internação na UTI, ele apresentou\ndificuldade de se alimentar por via oral,\ncom episódios de broncoaspiração associados, motivo por\nque foi necessário definir a SNE como via exclusiva de alimentação. Realizada avaliação da\ndeglutição mediante videodeglutograma, foi diagnosticada disfagia orofaríngea grave. Foi solicitada\nao paciente a realização de gastrostomia endoscópica. Nesse período, ele estava em uso de\nclopidogrel e AAS. A partir desse caso clínico, julgue o próximo item. Para a realização da\ngastrostomia endoscópica, o paciente deve suspender o uso das referidas medicações pelo menos\ncinco dias antes do procedimento e, durante o pré-operatório, deve substituí-las por heparina de\nbaixo peso molecular, suspendendo seu uso, entretanto, vinte e quatro horas antes do\nprocedimento cirúrgico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-159515","number":"159515","sourceNumber":"159515","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Julgue o item a seguir, acerca da doença de Parkinson. Além de apresentar efeitos\ncolaterais significativos, a Levodopa é o principal tratamento clínico dessa doença neurológica, já\nque, devido ao seu efeito neuroprotetor, modifica o curso progressivo da doença de Parkinson.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-159522","number":"159522","sourceNumber":"159522","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Julgue o item a seguir, acerca da doença de Parkinson. Os distúrbios do movimento\nobservados nos portadores dessa doença são\ninvoluntários, aleatórios, rápidos e migratórios e,\ncom frequência, passam subitamente de uma parte do corpo para outra, em sequência imprevisivel\ne sem propósito.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-168451","number":"168451","sourceNumber":"168451","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma mulher com 40 anos de idade é atendida em hospital, queixando-se de ter tido\ncefaleia súbita de forte intensidade, com náuseas e vômitos, seguida de perda de consciência. Ao\nexame, mostra-se consciente, orientada, sem deficit motor, com pupilas isocóricas e rigidez de\nnuca importante. Neste caso, o diagnóstico mais provável é:","options":{"A":"Enxaqueca complicada.","B":"Hemorragia subaracnoide.","C":"Hematoma intraparenquimatoso.","D":"Acidente vascular cerebral isquêmico."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-158024","number":"158024","sourceNumber":"158024","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O médico está avaliando Maria, uma senhora de 70 anos de idade, que apresentou\nAVC há cerca de quatro meses, com boa\nrecuperação do quadro de hemiparesia à direita que\nantes apresentava, mas que manteve algumas sequelas motoras. Maria voltou a conseguir tomar\nbanho, vestir-se, comer e ir ao banheiro sem necessitar de auxílio. Entretanto, o esposo dela,\nAntônio, teve de assumir as tarefas de preparar refeições, fazer compras e limpar a casa, pois\nMaria não mais conseguiu. Ela ainda toma decisões e \"manda na casa\", definindo que coisas serão\ncompradas e quais pratos serão feitos. No que se refere a esse caso hipotético, assinale a\nalternativa CORRETA.","options":{"A":"Maria é independente para as atividades básicas de vida diária, mas dependente para as\natividades instrumentais de vida diária. Não tem autonomia preservada.","B":"Maria é dependente para as atividades básicas de vida diária, mas independente para as\natividades instrumentais de vida diária. Não tem autonomia preservada.","C":"Maria é dependente para as atividades básicas de vida diária e para as atividades instrumentais\nde vida diária. Tem autonomia preservada.","D":"Maria é independente para as atividades básicas de vida diária, mas dependente para as\natividades instrumentais de vida diária. Tem autonomia preservada.","E":"Maria é independente para as atividades básicas de vida diária e para as atividades\ninstrumentais de vida diária. Tem autonomia preservada."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-168508","number":"168508","sourceNumber":"168508","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma mulher com 75 anos de idade, aposentada há 15 anos, reside em uma instituição\nde longa permanência de idosas conveniada à\nprefeitura local. Ela perdeu contato com sua família,\napresenta demência grave, síndrome da imobilidade e cognitiva, vive restrita ao leito e com\ndependência completa de outra pessoa para realização de todas as atividades da vida diária na\ninstituição. Tem histórico de três internações hospitalares prolongadas no último semestre devido a\npneumonia por aspiração e está em uso regular de haloperidol 2 mg/dia para controle de episódios\nde agitação psicomotora frequentes. A referida instituição localiza-se na área de abrangência de\numa Unidade Básica de Saúde, cujo médico de família é chamado para discutir a conduta com o\nnovo responsável pela instituição. Nessa situação, o médico de família deve","options":{"A":"construir novo plano de cuidado para os cuidadores, com ajuste medicamentoso.","B":"discutir e implementar cuidados paliativos junto aos cuidadores e responsáveis na instituição.","C":"construir genograma e ecomapa para estabelecer plano terapêutico orientado aos cuidadores da\npaciente na instituição.","D":"aplicar miniexame do estado mental para estabelecer o grau de comprometimento mental da\npaciente e as condutas adequadas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-159546","number":"159546","sourceNumber":"159546","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em um dia normal de trabalho, médicos de família e comunidade atendem a muitos\ncasos diferentes. Certa manhã, determinado\nmédico atendeu a quinze pacientes, entre os quais se\nencontravam os seguintes: (1) uma criança de cinco anos de idade com suspeita de abuso sexual,\ntrazida pela mãe; (2) um idoso de sessenta e seis anos de idade, tabagista, com diabetes melito\n(DM) e hipertensão arterial sistêmica (HAS); (3) uma mulher de vinte e três anos de idade,\nestudante universitária, que não tomava banho havia uma semana; (4) um bebê de uma semana de\nvida (5) e sua mãe, puérpera, para consulta normal; (6) um adolescente de dezessete anos de\nidade, com rolha de cera; (7) uma idosa de setenta e um anos de idade, com diabetes melito (DM)\ne obesa com úlcera no membro inferior esquerdo, (8) e sua filha, e cuidadora, de quarenta e nove\nanos de idade, que não dormia regularmente havia um mês. Considerando esses casos clínicos,\njulgue o item a seguir. De acordo com as orientações de rastreamento populacional de saúde\npública brasileira, a paciente 1 deve ser submetida, em outro momento, ao rastreamento de\nambliopia, estrabismo e acuidade visual.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-133950","number":"133950","sourceNumber":"133950","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Considere, hipoteticamente, que paciente masculino de 22 anos de idade,\n\nrecém-adepto de prática diária de atividade física aeróbica, comparece à consulta, queixando-se de\nepisódios frequentes de sensação de aperto no peito, tosse seca e dispneia. De acordo com as\nDiretrizes da Sociedade Brasileira de Asma e Tisiologia para o Manejo da Asma - 2012, o\ndiagnóstico espirométrico de asma em adultos pode ser estabelecido se for verificado:","options":{"A":"Relação VEF1 por CVF diminuída e prova broncodilatadora positiva.","B":"Relação CVF por VEF1 diminuída e prova broncodilatadora positiva.","C":"FEF 25%-75% inferior ao percentil 3 e prova broncodilatadora negativa.","D":"FEF 25%-75% inferior ao percentil 3 e prova broncodilatadora positiva.","E":"VEF1 diminuído com FEF 25%-75% normal e prova broncodilatadora negativa."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-129011","number":"129011","sourceNumber":"129011","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Com relação aos recursos terapêuticos para o tratamento de manutenção da asma,\nassinale a alternativa correta.","options":{"A":"A teofilina tem ação broncodilatadora prolongada, o que a torna útil para o tratamento de asma\nnoturna com administração uma vez ao dia.","B":"Em pacientes acima de quatro anos de idade, os beta-agonistas inalatórios de curta duração são\nutilizados em associação aos corticosteroides inalatórios quando estes forem insuficientes para\npromover o controle da asma.","C":"Os antileucotrienos inibem a ligação da IgE com o seu receptor e a broncoconstrição induzida\npor alérgeno, reduzindo a hiper-responsividade das\nvias aéreas.","D":"Os corticosteroides inalatórios são os principais medicamentos utilizados no tratamento,\nprofilático e anti-inflamatório, de manutenção,\ntanto em adultos como em crianças.","E":"O cromoglicato de sódio não é indicado em casos de asma persistente leve e de broncoespasmo\ninduzido por exercício."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-129004","number":"129004","sourceNumber":"129004","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A tríade clássica da fibrose cística ou mucoviscidose é:","options":{"A":"Doença pulmonar crônica, diarreia esteatorreica crônica e dificuldade de ganho ponderal e\nestatural.","B":"Doença pulmonar crônica, diarreia sanguinolenta crônica e anemia crônica.","C":"Doença pulmonar crônica, diarreia esteatorreica crônica e infecção urinária de repetição.","D":"Doença pulmonar recidivante, diarreia aquosa crônica e dificuldade de ganho ponderal e\nestatural.","E":"Doença pulmonar crônica e recidivante, diarreia esteatorreica aguda e dificuldade de ganho\nponderal e estatural."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-133994","number":"133994","sourceNumber":"133994","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A Fibrose Cística (FC) é uma doença genética, cuja prevalência na população chega a\n1/2.500 nascidos vivos na etnia branca. Nas últimas duas décadas, avanços no diagnóstico e na\nterapêutica dos pacientes com FC propiciaram aumento da sobrevida e da qualidade de vida.\n\nAcerca da fibrose cística, assinale a alternativa correta.","options":{"A":"A doença não pode ser considerada como diagnóstico diferencial das diarreias crônicas, já que\nnão cursa com manifestação gastrointestinal.","B":"O teste de suor possui elevada sensibilidade e especificidade para o diagnóstico, e é\nconsiderado positivo quando a concentração do cloreto no suor for maior que 45 mEq/L.","C":"É uma doença de herança autossômica recessiva, que leva a alteração de um canal condutor de\ncloreto de transmembrana presente em diversos epitélios do organismo que atinge, principalmente\nas glândulas exócrinas.","D":"O paciente portador de fibrose cística não pode fazer uso de qualquer tipo de vacina.","E":"Não existe diferença na expressão fenotípica da doença, sendo que os portadores sempre\napresentam a forma grave e completa da patologia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-111297","number":"111297","sourceNumber":"111297","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um individuo que apresenta bronquite crônica descompensada apresenta acidose:","options":{"A":"Metabólica com bicarbonato plasmático elevado e CO2 elevado.","B":"Respiratória com pH abaixo do normal, bicarbonato plasmático elevado e CO2 elevado.","C":"Respiratória com pH acima do normal, bicarbonato plasmático normal e CO2 elevado.","D":"Respiratória com pH abaixo do normal, bicarbonato plasmático normal e CO2 elevado.","E":"Respiratória com pH abaixo do normal, bicarbonato plasmático abaixo do normal e CO2 abaixo\ndo normal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-104785","number":"104785","sourceNumber":"104785","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A trombose venosa profunda é uma importante causa de morbidade e mortalidade em\npacientes hospitalizados, particularmente em pacientes no pós-operatório. Acerca dessa condição,\nassinale a alternativa correta.","options":{"A":"Estase venosa, lesão endotelial e hipercoagulabilidade estão presentes na maioria dos\npacientes cirúrgicos.","B":"A complicação mais letal dessa afecção é a necrose de membros inferiores.","C":"O local mais comum de início da trombose venosa é a região plantar de ambos os pés.","D":"Para evitar as complicações de liberação do trombo, os pacientes de risco devem evitar a\ndeambulação como medida profilática para a trombose.","E":"A dosagem de plaquetas no sangue periférico é o melhor marcador para o diagnóstico da\ntrombose venosa profunda."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-80691","number":"80691","sourceNumber":"80691","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Assinale a alternativa que apresenta um dos princípios no tratamento do paciente com\nasma:","options":{"A":"Afastar o indivíduo de suas atividades rotineiras até que atinja total controle sobre a doença.","B":"Conseguir que o indivíduo tenha noites de sono sem interrupção por sintomas da doença.","C":"Incentivar o uso de broncodilatadores inalatórios o máximo possível para se livrar de qualquer\nsintoma.","D":"Estimular que o indivíduo procure o serviço médico a qualquer hora, sem agendamento, por\nqualquer sintoma característico.","E":"Manter a função pulmonar, quando avaliada por indicadores próprios, em cerca de 60% do\nnormal."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-64431","number":"64431","sourceNumber":"64431","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Diante de um paciente com história de tosse e dispneia, são fatores que diminuem a\nprobabilidade de asma:","options":{"A":"Eosinofilia sem outra justificativa","B":"História familiar de atopia","C":"Antecedente de tabagismo importante (> 20 maços por ano)","D":"Sibilos, dispneia e tosse que pioram com exercício e resfriamento do ar inspirado","E":"Sibilos, dispneia e tosse após ingestão de salicilato ou betabloqueador"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-64435","number":"64435","sourceNumber":"64435","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O sinal eletrocardiográfico clássico de tromboembolismo pulmonar é:","options":{"A":"Bloqueio completo de condução pelo ramo esquerdo recente","B":"Fibrilação atrial aguda","C":"Taquicardia supraventricular com condução aberrante","D":"Inversão de onda T nas derivações precordiais","E":"Presença de S1, Q3, T3"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-137600","number":"137600","sourceNumber":"137600","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um homem de 65 anos de idade, com diabetes e hipertensão arterial não controladas,\né trazido à Emergência de um hospital\nterciário com hemiplegia direita e afasia iniciadas há 2\nhoras. Ao exame, encontra-se sonolento, acorda ao estímulo verbal, obedece aos comandos.\nApresenta afasia de expressão, pupilas isocóricas e fotorreagentes, hemiplegia do dimídio\ndireito. Pressão arterial = 190 x 120 mmHg, frequência cardíaca = 100 bpm, saturação de oxigênio\nde 96% em ar ambiente, auscultas cardíaca e pulmonar normais. A tomografia computadorizada\nde crânio sem contraste, realizada na Emergência, foi normal. Qual a melhor conduta a ser\nrealizada na sequência do atendimento?","options":{"A":"Indicação de trombólise intravenosa, por estar na janela terapêutica.","B":"Prescrição de ácido acetilssalicílico, por via oral, como\nantiagregante plaquetário.","C":"Prescrição de heparina de baixo peso molecular para\nanticoagulação.","D":"Prescrição de dexametasona para prevenir edema\ncerebral .","E":"Administração de nitroprussiato de sódio, por via\nendovenosa."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-31004","number":"31004","sourceNumber":"31004","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma gestante com 29 anos de idade, previamente hígida, com 12 semanas de\ngestação, procurou atendimento no\npronto-socorro com relato de tosse seca e dor torácica à direita\nhá um dia. Informou que, no dia da consulta, pela manhã, sentiu-se cansada durante o banho,\napresentando melhora após repouso. Relatou, ainda, que a temperatura corporal de 37,8°C\nnormalizou-se após o banho. Ao exame clínico apresentou: frequência cardíaca de 95 bpm,\nfrequência respiratória de 22 irpm, pressão arterial de 100 mmHg x 60 mmHg. A ausculta pulmonar\nevidenciou murmúrio vesicular discretamente reduzido em região infraescapular direita, com\ncrepitações teleinspiratórias no mesmo local. Não havia sinais de trombose venosa profunda em\nmembros inferiores. Considere esse caso clínico, julgue o item que se segue. O dímero-D deve ser\nsolicitado nesse caso, pois, caso seja normal, praticamente autoriza o médico a seguir a\ninvestigação de outras causas que justifiquem os sintomas.","options":{"A":"Certo.","B":"Errado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-22184","number":"22184","sourceNumber":"22184","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 75 anos de idade tabagista de 50 maços por ano informa apresentar\ntosse matinal desde os 50 anos de idade.\nPassados 10 anos, começou a sentir a associação de\ndispneia aos esforços moderados e gripes frequentes. Tais sintomas intensificaram-se em uma\nfrequência de pelos menos 4 meses ao longo do ano. Resolveu-se buscar assistência médica a\npartir do momento em que notou grande dificuldade para barbear-se e tomar banho sozinho. O\nexame físico revelou redução global do murmúrio vesicular. A radiografia de tórax mostrou\nretificação da cúpula diafragmática. Com a realização da espirometria, identificou-se capacidade\nvital forçada (CVF) a 60% do previsto, com VEFL a 30% do previsto e índice de Tiffenau com valor\nde 50% sem resposta ao uso do broncodilatador. Com referência ao quadro clínico acima, julgue o\nitem que se segue. Programa de reabilitação pulmonar deve ser incluído no plano terapêutico do\npaciente.","options":{"A":"certo","B":"errado"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-22185","number":"22185","sourceNumber":"22185","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 75 anos de idade tabagista de 50 maços por ano informa apresentar\ntosse matinal desde os 50 anos de idade.\nPassados 10 anos, começou a sentir a associação de\ndispneia aos esforços moderados e gripes frequentes. Tais sintomas intensificaram-se em uma\nfrequência de pelos menos 4 meses ao longo do ano. Resolveu-se buscar assistência médica a\npartir do momento em que notou grande dificuldade para barbear-se e tomar banho sozinho. O\nexame físico revelou redução global do murmúrio vesicular. A radiografia de tórax mostrou\nretificação da cúpula diafragmática. Com a realização da espirometria, identificou-se capacidade\nvital forçada (CVF) a 60% do previsto, com VEFL a 30% do previsto e índice de Tiffenau com valor\nde 50% sem resposta ao uso do broncodilatador. Com referência ao quadro clínico acima, julgue o\nitem que se segue. O grau de comprometimento da doença pode ser classificado como moderado,\npois ainda não há evidências de cor pulmonale nem a necessidade do uso do oxigênio\nsuplementar.","options":{"A":"certo","B":"errado"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-19216","number":"19216","sourceNumber":"19216","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Com relação à propedêutica funcional renal, julgue o item a seguir. No exame de urina\ntipo I (EAS), o registro ?sangue na urina? indica a presença de hematúria, não se excluindo a\npresença de mioglobina, pois a reação utilizada para essa detecção é de atividade peroxidásica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-19217","number":"19217","sourceNumber":"19217","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Com relação à propedêutica funcional renal, julgue o item a seguir. A presença de\nhemácias dismórficas, com acantócitos, no exame de urina tipo I, indica patologia vesical.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-19218","number":"19218","sourceNumber":"19218","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Com relação à propedêutica funcional renal, julgue o item a seguir. Leucocitúria\nsignificativa ao EAS é indicativo de infecção do\ntrato urinário, que pode ser cistite ou pielonefrite.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-354083","number":"354083","sourceNumber":"354083","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher de 93 anos de idade, doença de Alzheimer em fase grave (FAST 7b), em uso de\ndonepezila, memantina, sertralina e olanzapina. Além de valsartana, anlodipina, hidroclorotiazida\npara hipertensão; metformina e glibenclamida para diabetes; sinvastatina para dislipidemia;\nglicosamina com condroitina em pó para osteoartrite; alendronato, cálcio e vitamina D para\nosteoporose; e paracetamol para dor. Ela começou a apresentar dificuldades para aceitar os\nmedicamentos, ora recusando-os ora retendo-os na boca. Nesse caso, qual deve ser a conduta\nmais adequada?","options":{"A":"amassar e dissolver todos os medicamentos de uso habitual nos alimentos e líquidos.","B":"acrescentar um medicamento inibidor de bomba de prótons para proteção gástrica.","C":"otimizar a prescrição e avaliar a desprescrição dos medicamentos inapropriados.","D":"introduzir sonda nasoenteral para garantir o fornecimento de todos os medicamentos.","E":"solicitar internação hospitalar para administração parenteral de medicações equivalentes e\nsuplementação nutricional."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-354084","number":"354084","sourceNumber":"354084","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um médico é chamado para atender em domicílio um homem de 85 anos de idade.\nFamiliares relatam que o paciente era lúcido e plenamente funcional até há 15 dias, mas\napresentou mudança gradual no comportamento desde então: parou de dar atenção às netas, por\nvezes parece estar desorientado, repete as mesmas perguntas a seus filhos, tem dificuldade para\nvestir-se sozinho e aparenta certo desequilíbrio ao se levantar do sofá ? motivo pelo qual\nsolicitaram que a consulta ocorresse no domicílio. Há um dia, o paciente tem deixado cair objetos,\nquando os segura com a mão direita. O paciente não tem história de doença psiquiátrica prévia; é\ndiabético (usa metformina XR 850 mg por dia) e consome álcool esporadicamente, nos finais de\nsemana. As aferições das glicemias capilares ao longo do dia resultaram normais na última\nsemana. O filho relata que o paciente sofreu uma queda há um mês ? escorregou num\nestacionamento, sem maiores consequências. Na ocasião, foi submetido a uma sutura na região\nfrontal direita e a uma radiografia de crânio, que resultou normal. Qual o diagnóstico provável para\no caso e o exame complementar indicado para confirmá-lo, respectivamente?","options":{"A":"Encefalopatia de Wernicke-Korsakoff; dosagem de tiamina sérica.","B":"Doença de Alzheimer; avaliação neuropsicológica.","C":"Hidrocefalia de pressão normal; teste de Miller-Fisher.","D":"Delirium; eletroencefalograma.","E":"Hematoma subdural crônico; tomografia de crânio."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-354085","number":"354085","sourceNumber":"354085","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente masculino, 38 anos, casado, sem filhos, tabagista crônico, portador de\nadenocarcinoma de pulmão avançado com linfangite carcinomatosa e sem possibilidade de\ntratamento modificador de doença. Em progressão de doença e com dispneia refratária ao uso de\nopioides em altas doses e demais medidas farmacológicas e não farmacológicas. O mesmo\nencontra-se internado em enfermaria de cuidados paliativos e sendo acompanhado pela mãe e\nesposa. Qual afirmativa a seguir está correta quanto ao manejo de sedação paliativa? Parte\nsuperior do formulário","options":{"A":"Trata-se do uso de medicamentos que reduzem o nível de consciência para alívio de sintomas\nrefratários em paciente com doença avançada terminal.","B":"A sedação paliativa provoca o falecimento do paciente com doença avançada terminal, com o\nobjetivo de cessar o seu sofrimento.","C":"Na sedação paliativa utilizam-se medicações sedativas em doses elevadas, para o controle\nadequado do sintoma refratário.","D":"Os opioides são sempre utilizados na sedação paliativa por seu efeito sedativo e compõem a\nestratégia de sedação paliativa.","E":"Deve ser realizada sob monitorização sendo indicada a transferência do paciente da enfermaria\npara a unidade de terapia intensiva, caso seja\nindicada."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-351601","number":"351601","sourceNumber":"351601","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Para que um programa de rastreamento seja efetivo, deve-se garantir o rastreamento\nda maioria da população susceptível. São aspectos\nimportantes, que devem ser destacados, em\num programa de rastreamento, EXCETO:","options":{"A":"Sintomas","B":"Melhores evidências","C":"Acesso","D":"Agilidade"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-320445","number":"320445","sourceNumber":"320445","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O envelhecimento fisiológico compreende uma série de alterações nas funções\norgânicas devido exclusivamente aos efeitos da\nidade avançada sobre o organismo, fazendo com\nque o mesmo perca a capacidade de manter o equilíbrio homeostático e que todas as funções\nfisiológicas gradualmente comecem a declinar. Sobre o envelhecimento fisiológico do sistema\ncardiovascular, qual alternativa está correta?","options":{"A":"Mudanças morfológicas do coração são vistas em sua porção esquerda: menor hipertrofia e\nrigidez do ventrículo esquerdo e aumento do átrio esquerdo são observados.","B":"Devido à importante perda celular na topografia do nó sinusal e a infiltração gordurosa\nseparando este da musculatura subjacente, há uma\nmaior frequência de arritmias.","C":"As artérias, incluindo a aorta, apresentam menor formação de fibras de colágeno não\ndistensíveis, concomitante à menor desorganização das fibras elásticas.","D":"Ocorre aumento progressivo dos miócitos com diminuição do volume celular.","E":"As valvas cardíacas pouco se alteram com o processo do envelhecimento sendo pouco\nfrequentes a ausculta de sopros cardíacos em pacientes idosos."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-336307","number":"336307","sourceNumber":"336307","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher, 74 anos, 90 Kg, portadora de hipertensão arterial sistêmica, dislipidemia e\nfibrilação atrial em uso regular de\nLosartana, anlodipino, sinvastatina, carvedilol e varfarina relata\nquadro súbito de afasia e hemiparesia à esquerda há 3 horas. Ao exame: Tax: 36,5°C, ausculta\ncardíaca com ritmo cardíaco irregular e ausência de sopros, FC: 89 bpm, PA: 190/100 mmHg, TEC\n\n< 2 segundos. FR: 23 irpm, SpO2: 96% em ar ambiente. Exame neurológico: hipoestesia e força\ngrau 1 à esquerda em membros superiores e\ninferiores, desvio de rima labial para a direita. NIHSS:\n13 pontos. Tomografia de crânio obtido na emergência com hiperdensidade em trajeto de artéria\ncerebral média direita. Exames laboratoriais: Hb 14,0 g/dL| Htc 42% | 9.000 mm3 leucócitos |\nPlaquetas: 85.000 | TAP (INR): 4,7| Na: 137 mEq/L| K: 4,2 mEq/L. Eletrocardiograma: ritmo\ncardíaco irregular, ausência de onda P, sem sinais de isquemia aguda, FC: 86 bpm. O tratamento\nmais adequado indicado para essa paciente neste momento é:","options":{"A":"Trombectomia mecânica","B":"Heparina de baixo peso molecular","C":"Trombólise com Alteplase","D":"AAS + antagonista Vitamina K"},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-314034","number":"314034","sourceNumber":"314034","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A Doença de Alzheimer (DA) é uma doença neurodegenerativa crônica, com um início\ninsidioso e progressivo, mas um declínio lento. A DA é o tipo de demência mais comum. Em\nrelação a essa patologia, assinalar a alternativa CORRETA:","options":{"A":"Causas reversíveis de transtornos cognitivos devem ser excluídas com exames laboratoriais\niniciais e exames de imagem cerebral, como\ndeficiência de vitamina B12.","B":"RNM cerebrais normalmente revelam atrofia estrutural nos lobos frontais e/ou temporais,\ncaracterísticos da DA.","C":"A maioria dos casos de DA é decorrente de doença/alteração genética.","D":"Antagonistas do receptor NMDA, como a memantina, não parecem retardar a progressão do\ndeclínio funcional em pacientes com DA.","E":"Ausência de doenças cardiovasculares é necessário para o diagnóstico de DA."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-291640","number":"291640","sourceNumber":"291640","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente muito idoso, 88 anos, residente em Colatina/ES. Possui diagnóstico de\ndoença de Alzheimer provável em fase\navançada, FAST 7F, em seguimento regular no ambulatório\nde Geriatria. Faz uso Memantina 20mg/dia, Metoprolol 50mg/dia e Rosuvastatina 10mg/dia. Há\naproximadamente duas semanas, a filha, principal cuidadora, vem observando maior agitação do\npaciente, principalmente no período noturno. Sem consultar o médico assistente, resolveu\nadministrar Clonazepam 2mg (1 comprimido) pela noite para controle comportamental. Não houve\nresposta satisfatória. Decidiu então levá-lo ao médico de sua confiança, onde exame físico\ndetalhado evidenciou paciente com múltiplas contraturas em grandes articulações, gastrostomia em\nbom aspecto e presença de lesão sacral compatível com úlcera de pressão grau 2 e lesão\ntrocantérica esquerda compatível com úlcera de pressão grau 3. Ao observar a presença das\nlesões, a filha demonstra surpresa e chora bastante, afirmando que apenas havia observado\npequena vermelhidão local e que as feridas não estavam assim no dia anterior. Sempre foi muito\ncuidadosa com a pai e que tal situação muito a entristecia. Em relação ao caso apresentado, é\npossível afirmar:","options":{"A":"Um diagnóstico a ser levantado é a síndrome do imobilismo pela identificação de dois critérios\nmaiores: déficit cognitivo grave e úlceras\nde pressão e pelo menos dois critérios menores: múltiplas\ncontraturas e disfagia (representada pela gastrostomia).","B":"O uso de três medicações diferentes oferecidas a este paciente de forma regular com relação\ndireta a eventos adversos caracteriza a polifarmácia.","C":"Uso de colchões específicos, como o piramidal e o pneumático, normalmente não são indicados\npara idosos com demência avançada pois, pela\nrestrição que esses pacientes apresentam, não são\ncapazes de evitar ou diminuir a chance do surgimento de lesões cutâneas, como as úlceras de\npressão.","D":"O comportamento emocional da filha do paciente levanta a possibilidade do diagnóstico de\nsobrecarga do cuidador. Uma escala sugerida para esta avaliação é a escala de ZARIT.","E":"Em relação à demência apresentada, o uso isolado de Memantina como tratamento específico\n\npode ser impulsionado com associação de doses elevadas de anticolinesterásicos pois, de forma\nrobusta, traz resultados promissores a curto e médio prazo, sem definir maior chance de eventos\nadversos graves."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-291641","number":"291641","sourceNumber":"291641","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em Geriatria e Cuidados Paliativos, os fármacos devem ser administrados,\npreferencialmente, por via oral, tanto pela\nsimplicidade da oferta como por ser a via mais fisiológica\ne menos invasiva. Em algumas situações, entretanto, a via oral não está disponível. A via\nsubcutânea, neste contexto, oferece conveniência e segurança. Definida como hipodermóclise,\nsobre essa via é possível afirmar:","options":{"A":"Tem como desvantagem a limitação de volume e velocidade de infusão: Até 500mL/24h por sítio\nde punção.","B":"É via enteral mais acessível e confortável que a via endovenosa.","C":"Não há limite de medicamentos e eletrólitos a serem infundidos.","D":"Representam contra-indicações relativas para sua realização: Trombocitopenia grave, anasarca\ne ascite.","E":"Apresenta absorção variável (influenciada por perfusão e vascularização)."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-283883","number":"283883","sourceNumber":"283883","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Na avaliação de indivíduos geriátricos, é fundamental a avaliação e classificação de\nsuas atividades (básicas ou instrumentais)\ndiárias. Das atividades abaixo, é classificada como\natividade instrumental de vida diária a capacidade de:","options":{"A":"Se vestir.","B":"Tomar banho.","C":"Cozinhar.","D":"Realizar sua própria toalete.","E":"Deslocar-se da cama para a cadeira."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-260701","number":"260701","sourceNumber":"260701","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O Rastreio de doenças oncológicas em Geriatria deve acontecer para doenças que\npossam detectar lesões pré- malignas ou\nmalignas em estádio precoce. Para esta condição, quais\nsão as situações a serem observadas?","options":{"A":"O rastreio é tanto melhor quanto menor a incidência da doença","B":"O teste deve ter boa sensibilidade, baixo valor preditivo negativo e custo elevado","C":"A utilidade do rastreio acontece somente se o tratamento puder ser realizado de forma\nadequada e precoce","D":"O conhecimento da história natural da doença não é determinante na indicação do rastreio","E":"A avaliação funcional não representa condição relevante a ser considerada para a indicação ou\nnão do rastreio no paciente idoso"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-283934","number":"283934","sourceNumber":"283934","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem, 67 anos, procura atendimento após segundo episódio de perda de força em\nmembro superior e inferior direito com recuperação total. Nega alteração em expressão de face,\nfala e sensibilidade. No exame físico, apresenta-se hipertenso, sem detecção de hipotensão\npostural, ritmo cardíaco irregular, força preservada em membros superiores e inferiores. Qual\nhipótese diagnóstica mais provável a ser considerada nesse caso?","options":{"A":"Ataque isquêmico transitório.","B":"Acidente vascular isquêmico.","C":"Transtorno conversivo.","D":"Síndrome de Von Recklinghausen.","E":"Hipoglicemia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-227080","number":"227080","sourceNumber":"227080","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher de 76 anos é levada ao consultório por causa de dificuldade de marcha, com\npiora progressiva nos últimos 6 meses. É\nportadora de Diabetes Mellitus, gastroparesia diabética e\nlabirintopatia, e faz uso de metformina, glimepirida, domperidona e flunarizina regularmente há 1\nano. Ao exame físico, está alerta, orientada com as mucosas coradas, hidratadas e anictéricas. Há\nbradicinesia, tremor de repouso e cinético nas mãos e rigidez simétrica, nos membros superiores e\ninferiores. Sem outras anormalidades ao exame físico. Considerando o caso descrito, assinale a\nalternativa que apresenta a conduta imediata MAIS ADEQUADA a ser adotada para essa paciente:","options":{"A":"Prescrever a amantadina.","B":"Prescrever a levodopa/benserazida.","C":"\"Suspender a domperidona e prescrever a\nmetoclopramida.\"","D":"Suspender a flunarizina."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-227255","number":"227255","sourceNumber":"227255","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem de 72 anos, hipertenso, tabagista, apresentou quadro de mal súbito,\npermanecendo inconsciente por cerca de 10 minutos.\nFoi levado ao pronto-socorro onde, após 6\nhoras do início do quadro, permanece consciente, afásico, com desvio de comissura labial para\nesquerda e hemiparesia à direita, pressão arterial de 145/100 mmHg. O diagnóstico e tratamento\npara este paciente são, respectivamente:","options":{"A":"AVC isquêmico de artéria cerebral média direita, tratamento trombolítico.","B":"AVC isquêmico de artéria cerebral média direita, tratamento conservador.","C":"AVC isquêmico de artéria cerebral média esquerda, tratamento conservador.","D":"AVC hemorrágico subaracnoide direita, tratamento conservador."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-246732","number":"246732","sourceNumber":"246732","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O uso de vários medicamentos pode levar a quadro Parkinsonismo. NÃO causa(m) o\nParkinsonismo a(s) seguinte(s) droga(s):","options":{"A":"Neurolépticos atípicos;","B":"Ácido Valpróico;","C":"Fluoxetina;","D":"Primidona;","E":"Carbonato de Lítio."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-232135","number":"232135","sourceNumber":"232135","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Receber cuidados paliativos não significa que não haja mais nada a fazer por você ou\npela pessoa que você ama. Isso simplesmente indica que o diagnóstico é de uma doença crônica\ngrave, que ameaça a vida, e que uma equipe, juntamente com os profissionais especialistas na\nenfermidade, irá cuidar de quem está doente e daqueles que o cercam. Ou seja, há muito a fazer\npelo paciente. Acerca dos cuidados paliativos, são oferecidas as seguintes afirmações: I. Promover\no alívio da dor e outros sintomas desagradáveis. II. Afirmar a vida e considerar a morte como um\nprocesso normal da vida. III. Não acelerar nem adiar a morte. IV. Integrar os aspectos psicológicos\ne espirituais no cuidado ao paciente. V. Oferecer um sistema de suporte que possibilite ao paciente\nviver tão ativamente quanto possível, até o momento da sua morte. VI. Oferecer sistema de suporte\npara auxiliar os familiares durante a doença do paciente e a enfrentar o luto. São princípios\nfundamentais dos cuidados paliativos o que se afirma nos itens:","options":{"A":"I, II, III, IV, V e VI.","B":"I, II, III e VI.","C":"I, II, IV e V.","D":"III, IV, V e VI.","E":"I, III, IV e V."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-227120","number":"227120","sourceNumber":"227120","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O crescimento da população de idosos do Brasil tem sido sistemático e consistente. A\natenção ao idoso requer a avaliação de múltiplos domínios. O médico da equipe B realiza uma\nvisita domiciliar para uma avaliação multidimensional de um idoso de sua equipe. Analise os\naspectos importantes de serem abordados a seguir: I- Estado mental e avaliação do humor. II-\nRiscos de acidentes domiciliares e função dos membros inferiores. III- Atividades diárias IV-\nContinência urinária. V- Suporte social. Está(ão) CORRETO(S) o(s) aspecto(s) previsto(s) em:","options":{"A":"III apenas.","B":"I, II, III, IV e V.","C":"IV apenas.","D":"I, II e IV apenas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-212895","number":"212895","sourceNumber":"212895","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Para pacientes com doença de Alzheimer, em fase avançada, com disfagia grave em\nfunção da demência, a melhor opção para alimentar o paciente é:","options":{"A":"Manter dieta oral de conforto.","B":"Alimentação via sonda nasoentérica.","C":"Alimentação via sonda nasogástrica.","D":"Alimentação via gastrostomia (realizada por via endoscopia).","E":"Alimentação via gastrostomia (realizada cirurgicamente)."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-212912","number":"212912","sourceNumber":"212912","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A Síndrome da Fragilidade (SF) vem sendo amplamente estudada nas últimas décadas,\ne seus conceitos vêm sofrendo modificações.\nAssociada inicialmente com incapacidade funcional e\ncomorbidade, hoje se sabe que ela é uma entidade à parte, na qual nem todo indivíduo frágil é\nincapaz ou apresenta comorbidades e vice-versa. Sobre isso, assinale a alternativa CORRETA.","options":{"A":"Síndrome da Fragilidade como uma síndrome de declínio de energia que ocorre em espiral,\nembasado em um tripé de alterações relacionadas ao envelhecimento, composto, principalmente,\npor mialgias, desregulação neuroendócrina e disfunção imunológica.","B":"Fried e colaboradores propuseram um teste rápido para rastreamento de indivíduos frágeis. Eles\navaliaram cinco itens - força do braço, velocidade de marcha, perda de peso, exaustão física e\natividade física.","C":"Segundo o modelo proposto por Fried et col., os indivíduos são classificados como frágeis se\napresentarem alterações em dois ou mais itens, dentre os cinco propostos para rastreio da SF.","D":"Perda de peso não intencional (? 4,5 kg ou 5% do peso corporal no ano anterior); é um\nmarcador físico do Fenótipo de Fragilidade.","E":"Estudos identificaram que, enquanto a fraqueza muscular se manifesta no final e é reversível, a\nexaustão e a perda de peso são marcadores evidenciados no início do ciclo de fragilidade e\nindicam idosos com tendência a uma progressão rápida desse ciclo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-215150","number":"215150","sourceNumber":"215150","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Durante consulta clínica na Unidade Básica de Saúde, uma mulher com 86 anos de\nidade está sendo acompanhada por sua filha,\nque externa preocupação com o risco da ocorrência\nde acidentes domésticos que envolvam a sua genitora. A filha informa que sua mãe vem\napresentando declínio progressivo de várias de suas funções cognitivas, tendo recebido o\ndiagnóstico, há cerca de um ano, de doença de Alzheimer. Ultimamente, relata a filha, a mãe vem\nesquecendo o fogão aceso, deixando o gás do banheiro ligado e cometendo outros esquecimentos.\nMenciona ainda o problema de quedas frequentes, tendo sido a paciente classificada como ?idosa\nfrágil?, portadora de significativa sarcopenia. A filha acrescenta que a família está preocupada,\nbuscando auxílio no sentido de obter orientações quanto às medidas que devem ser tomadas para\na prevenção de acidentes domésticos e de proteção à paciente. Entre as intervenções voltadas ao\ncontrole de fatores extrínsecos relacionados à ocorrência de quedas dessa paciente idosa, a\nrecomendação mais efetiva é:","options":{"A":"Utilizar calçados abertos com solado de couro, pois diminuem o atrito ao caminhar e a chance de\ntropeços.","B":"Limitar práticas corporais e atividades físicas rotineiras, posto que a fadiga induzida\npredispõe ao\nrisco de quedas.","C":"Evitar luzes acesas durante a madrugada, o que torna o sono mais instável, facilitando o\ndespertar nesse período.","D":"Evitar a colocação de tapetes soltos, especialmente os de tecido, pois não permitem firmeza do\nidoso ao caminhar.","E":"Adquira sofás e cadeiras bem baixos, porque o grau de dificuldade exigido para se levantar é\nmenor, sendo que estes devem ser confortáveis e com braços."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-199626","number":"199626","sourceNumber":"199626","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"São fatores de risco não modificáveis para acidente vascular cerebral:","options":{"A":"Evento cerebrovascular prévio, diabetes, uso de contraceptivos orais.","B":"Estresse, raça negra, tabagismo.","C":"Sexo feminino, raça negra, hipercoagulabilidade.","D":"Sexo masculino, predisposição genética, raça negra."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-212915","number":"212915","sourceNumber":"212915","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A avaliação funcional é parte muito importante na anamnese de pacientes idosos.\nFazem parte do índice de Katz para Avaliação\ndas Atividades Básicas da Vida Diária perguntas\nsobre todos os itens abaixo, exceto:","options":{"A":"Capacidade de banhar-se.","B":"Capacidade de usar o sanitário.","C":"Capacidade de arrumar a casa.","D":"Capacidade de vestir-se.","E":"Capacidade de ter continência urinária e fecal."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-215160","number":"215160","sourceNumber":"215160","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma senhora de 85 anos de idade, tem visita domiciliar da Equipe de Saúde da Família\n(ESF) solicitada por sua cuidadora, pois há dois dias tem apresentado comportamento estranho.\n\nFala coisas desconexas, teve alucinação visual e comporta-se de forma agressiva algumas vezes.\nA paciente faz seguimento regular com a ESF há\n10 anos, atualmente com assistência domiciliar,\npois está restrita ao lar, após uma queda sofrida há quatro anos. A médica da equipe conhece a\npaciente e sabe que ela nunca teve problemas cardiovasculares, cognitivos ou de saúde mental, e\nque não faz uso de medicamentos contínuos. No exame físico, mostra-se desorientada em relação\nao tempo. A hipótese diagnóstica mais provável e a conduta adequada, são, respectivamente:","options":{"A":"Quadro depressivo; tratamento medicamentoso com tricíclico e avaliação por psicólogo.","B":"Quadro infeccioso agudo; solicitação de raio X, exame de urina e hemograma para melhor\navaliação.","C":"Demência de Alzheimer; encaminhamento para neurologista para realização de exames de\nimagem.","D":"Distúrbio de comportamento por transtorno psicótico; prescrição de antipsicótico e\nencaminhamento para psiquiatra.","E":"Quadro depressivo; encaminhamento para psicoterapia."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-220330","number":"220330","sourceNumber":"220330","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Para o diagnóstico precoce de uma doença altamente prevalente em uma população, o\nideal é dispor de exame laboratorial que apresente:","options":{"A":"Baixa especificidade.","B":"Valor preditivo negativo elevado.","C":"Valor preditivo positivo baixo.","D":"Alta sensibilidade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-188000","number":"188000","sourceNumber":"188000","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher, 65 anos, fumante e hipertensa. Apresentou episódio de síncope e foi levada ao\npronto socorro. Ao exame: PA: 90/50 mmhg, FC: 125 bpm, SpO2: 89%. Confirmado diagnóstico de\nembolia pulmonar maciça. Mediante quadro acima qual o tratamento correto deverá ser iniciado?","options":{"A":"Expansão volêmica e ácido acetilsalicílico.","B":"Heparina de baixo peso subcutânea e rivaroxabana oral.","C":"Heparina não fracionada endovenosa e warfarina oral.","D":"Trombolítico endovenoso e heparina não fracionada endovenosa.","E":"Filtro de veia cava inferior e trombectomia."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-172823","number":"172823","sourceNumber":"172823","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 65 anos relata tremor progressivo das mãos de início insidioso, há 3\nanos, que dificulta a escrita e o manuseio\nde objetos, particularmente de talheres. Ao exame\nneurológico, observou-se tremor postural nas mãos à extensão dos membros superiores, A marcha\nera atípica e o tono normal. Qual a melhor opção terapêutica para este paciente?","options":{"A":"Agonista dopaminérgico.","B":"Beta-bloqueador.","C":"Levodopa.","D":"Clonazepam."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-174353","number":"174353","sourceNumber":"174353","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A avaliação geriátrica ampla é instrumento fundamental na avaliação funcional do\npaciente idoso. Dentre as opções abaixo, assinale a que contém suas características:","options":{"A":"Não interfere na institucionalização ou na tomada de decisões terapêuticas.","B":"Sua aplicação na sala de emergência não é capaz de aumentar o número de diagnósticos,\nestando por este motivo contra-indicada","C":"Realizada por equipe multidisciplinar, quando possível, e utiliza diversas escalas de avaliação.","D":"É utilizada para avaliação global do idoso, especialmente o não-frágil.","E":"Estudos recentes demonstram não haver evidências de redução na mortalidade quando aplicada\naos pacientes muito idosos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-188031","number":"188031","sourceNumber":"188031","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual das situações abaixo é considerada das mais sugestivas de asma para criança\nmenor de 5 anos segundo as Diretrizes da Sociedade Brasileira de Pneumologia e Tisiologia?","options":{"A":"Ter pelo menos um episódio de sibilância nos primeiros anos.","B":"Episódios repetidos de pneumonia nos primeiros anos.","C":"Presença de tosse e sibilos associados a viroses respiratórias.","D":"Pouca resposta ao beta2 agonista inalatório.","E":"Presença de dermatite atópica e rinite alérgica."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-174365","number":"174365","sourceNumber":"174365","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O melhor escore para avaliar a gravidade clínica de um paciente com AVE isquêmico, e\nque deve ser utilizado antes da trombólise\nquímica, está relacionado com o seguinte termo/sigla:","options":{"A":"TIMI.","B":"NIH.","C":"ASPECTS.","D":"CHA2DS2VASC.","E":"MELD."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-172747","number":"172747","sourceNumber":"172747","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Médico de família realiza visita domiciliar a paciente que vem sendo acompanhado com\nmais proximidade devido diagnóstico de neoplasia de pulmão metastático e problemas no\nenfrentamento da doença, com grande repercussão na dinâmica familiar. Os familiares presentes\nno domicílio relatam que o paciente está mais calmo em relação a períodos anteriores, as vezes até\num pouco \"aéreo\". A filha está preocupada com o fato do paciente estar \"dormindo demais\" em sua\nopinião. Nos últimos dias, segundo os relatos, o paciente tem procurado algumas pessoas com\nquem não tinha mais relações próximas, incluindo um filho, para \"pedir perdão pelas coisas que\nfez\". Considerando os trabalhos de Elizabeth Kübler-Ross sobre o processo de luto e\nenfrentamento da morte e do morrer, pode-se dizer que este paciente encontra-se no estágio de:","options":{"A":"Aceitação.","B":"Negociação.","C":"Depressão.","D":"Isolamento."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-148567","number":"148567","sourceNumber":"148567","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"São características da dêmencia de Alzheimer:","options":{"A":"Convulsões e distúrbio de marcha precoces.","B":"Sintomas psiquiátricos e vegetativos.","C":"Atividades de vida diária preservadas.","D":"Alteração neurológica focal.","E":"História familiar ausente."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-148614","number":"148614","sourceNumber":"148614","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"De acordo com o conceito de \"cuidados paliativos\" definido pela Organização Mundial\nde Saúde, as seguintes doenças encaixam-se\nneste perfil, exceto:","options":{"A":"Insuficiência cardíaca em paciente aguardando transplante de coração.","B":"DPOC grave dependente de oxigênio.","C":"Câncer em estadiamento avançado.","D":"Demência em estágio avançado.","E":"Esclerose lateral amiotrófica."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-148532","number":"148532","sourceNumber":"148532","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"São condições para uso de ativador do plasminogênio tecidual humano recombinate\n(rtPA) em casos de acidente vascular encefálico\nagudo, exceto:","options":{"A":"Não administrar heparina ou antiagregante plaquetário nas primeiras 24 horas do uso de rtPA.","B":"Iniciar o rtPA em até 4,5 horas da admissão na sala de emergência.","C":"Exame de imagem (tomografia computadorizada ou ressonância nuclear magnética) sem\nevidência de hemorragia.","D":"Manter o paciente em jejum por 24 horas.","E":"Manter níveis pressóricos controlados."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-162599","number":"162599","sourceNumber":"162599","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente masculino de 53 anos consulta um mês após alta hospitalar por acidente\nvascular cerebral isquêmico. Assinale a\nalternativa que NÃO apresenta indicação adequada para o\ncaso acima.","options":{"A":"Uso de estatina.","B":"Uso de AAS.","C":"Endarterectomia de carótida na presença de estenose de 50%.","D":"Controle da hipertensão arterial sistêmica com diurético ou IECA.","E":"Uso de Varfarina na presença de fibrilação atrial."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-155463","number":"155463","sourceNumber":"155463","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A apneia do sono é uma doença que frequentemente faz parte de síndromes clínicas\nincluindo várias doenças. A associação com obesidade e obstrução de vias aéreas pode causas\nhipoventilação alveolar, que compreende as seguintes alterações:","options":{"A":"PaCO2 > 45 mmHg e PaO2 < 70mmHg.","B":"Valor de VEF1 < 60% e pico de fluxo < 30%.","C":"SatO2 < 90% e PH< 7,30.","D":"PH > 7,30 e PaO2 < 50 mmHg.","E":"SatO2 < 90% e VEF1 < 60%."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-126900","number":"126900","sourceNumber":"126900","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em relação ao tratamento da Doença Pulmonar Obstrutiva Crônica (DPOC), assinale a\nalternativa CORRETA.","options":{"A":"Apesar de ser recomendada, a cessação do tabagismo não diminui a progressão da doença.","B":"A vacinação anti-influenza não reduz o risco de exacerbações graves.","C":"Os broncodilatadores são as principais drogas no tratamento da DPOC.","D":"Os mucolíticos e os antitussígenos são medicamentos que devem ser usados rotineiramente nos\npacientes com DPOC, devido à baixa incidência de efeitos colaterais."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-131627","number":"131627","sourceNumber":"131627","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em pacientes com doença pulmonar obstrutiva crônica, padrão enfisematoso, ocorre,\ncaracteristicamente, aumento:","options":{"A":"Da capacidade pulmonar total.","B":"Da razão de volume expiratório forçado no primeiro segundo/capacidade vital forçada.","C":"Da capacidade vital forçada.","D":"Da retenção do CO2.","E":"Do fluxo expiratório máximo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-126917","number":"126917","sourceNumber":"126917","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em relação à Doença Tromboembólica (DTV), é INCORRETO afirmar que:","options":{"A":"O risco de DTV na gravidez é 14 vezes maior.","B":"O risco de DTV é maior no 3° trimestre e nas primeiras 6 semanas do pós-parto.","C":"O fator mais importante de DTV na gravidez são as posições viciosas e flexão contínua e\nduradoura do membro inferior.","D":"O segundo fator de risco mais importante é a trombofilia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-126879","number":"126879","sourceNumber":"126879","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A classificação da gravidade da asma aguda precisa ser realizada no início do\ntratamento. Quanto à classificação da gravidade da asma aguda, assinale a alternativa\nINCORRETA.","options":{"A":"A classificação deve ser feita através da anamnese, saturação de oxigênio e uma medida\nobjetiva da função pulmonar.","B":"A asma leve apresenta dispneia ao andar e ao falar frases longas.","C":"A asma moderada apresenta dispneia ao falar mesmo em frases curtas.","D":"A frequência respiratória está sempre muito aumentada na asma grave."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-137854","number":"137854","sourceNumber":"137854","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A trombose venosa profunda e sua principal complicação a embolia pulmonar são\nsituações de ocorrência não rara, no pós-operatório de grandes cirurgias, apresentando potencial\nde mortalidade significante. É correto afirmar que:","options":{"A":"O exame do D-dímero pode estar falseado positivamente devido a uma série de situações\nclínicas, inclusive pós-operatório, mas com um\nresultado negativo a chance de embolia é muito\nbaixa.","B":"A mutação de Leiden do fator V não interfere com o desenvolvimento da trombose venosa\nprofunda.","C":"A disfunção cardíaca direita é encontrada numa pequena porcentagem dos pacientes com\nembolia pulmonar maciça.","D":"Os sinais radiológicos de Palla e Westermark representam a diminuição de aporte sanguíneo no\npulmão com embolia.","E":"A ultrassonografia das veias das pernas negativas para trombose venosa descarta embolia."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-127244","number":"127244","sourceNumber":"127244","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sobre a fibrose cística, assinale a afirmativa INCORRETA.","options":{"A":"Íleo meconial, prolapso retal, pancreatite e retardo no crescimento estão entre as manifestações\nclínicas da doença.","B":"Há comprometimento do transporte de água, determinando a produção de secreções\nespessadas, que ocasionam as alterações clínicas\nnos diversos órgãos envolvidos.","C":"Ocorre de forma grave e homogênea em praticamente todos os pacientes.","D":"Acomete principalmente os pulmões, vias aéreas superiores, pâncreas, glândulas sudoríparas,\ntrato biliar, intestinos e aparelho reprodutor.","E":"A infecção crônica por Pseudomonas aeruginosa, especialmente por cepas mucoides, está\nassociada a um pior prognóstico."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-127180","number":"127180","sourceNumber":"127180","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Para o uso seguro de anticoagulantes, em um paciente com trombose venosa profunda\naguda, é absolutamente necessário saber,\nexceto:","options":{"A":"Existência de pontos de sangramentos reais ou potenciais.","B":"D-dímero.","C":"Tempo e atividade de protrombina.","D":"Tempo de tromboplastina parcial ativada.","E":"Histórico de plaquetopenia induzida por heparinas."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-106390","number":"106390","sourceNumber":"106390","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em paciente com embolia pulmonar, os êmbolos provêm, na maioria dos casos, de:","options":{"A":"veias pélvicas.","B":"veias superficiais das coxas.","C":"veias poplíteas.","D":"veias dos membros superiores.","E":"veias varicosas das panturrilhas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-106375","number":"106375","sourceNumber":"106375","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Todos os fatores abaixo estão relacionados a um maior risco de complicações\npulmonares no pós-operatório, exceto:","options":{"A":"idade acima dos 60 anos.","B":"asma com fluxo expiratório máximo de 220 L/min.","C":"doença pulmonar obstrutiva crônica.","D":"insuficiência cardíaca congestiva.","E":"volume expiratório forçado em 1 segundo de 1,5 L."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-102772","number":"102772","sourceNumber":"102772","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 55 anos, hipertenso, diabético e obeso, dá entrada no Pronto Atendimento\ncom queixa de dor torácica\nventilatório-dependente com irradiação para dorso, de início súbito e\nassociado à dispneia intensa e à hemoptise. Está no 4º dia de pós-operatório de artroplastia de\njoelho, permanecendo em repouso desde a cirurgia. O ECG mostra taquicardia sinusal. Sobre esse\ncaso, é CORRETO afirmar que:","options":{"A":"O dímero D deve ser solicitado e, caso negativo, excluir com segurança o diagnóstico de\nembolia pulmonar.","B":"Uma troponina positiva fecha o diagnóstico de síndrome coronariana aguda.","C":"Deve ser solicitada uma angiotomografia de tórax ou cintilografia de ventilação-perfusão,\ndependendo da disponibilidade no serviço\nmédico.","D":"Caso se confirme embolia pulmonar, o tratamento com varfarina só deve ser iniciado após 3 a 5\ndias de anticoagulação com heparina não fracionada ou de baixo peso molecular."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-106391","number":"106391","sourceNumber":"106391","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Pacientes com distúrbios de hipoventilação crônica frequentemente se queixam de\ncefaleia ao despertar. Qual é a causa desse sintoma?","options":{"A":"Despertar do sono.","B":"Vasodilatação cerebral.","C":"Vasoconstricção cerebral.","D":"Policitemia.","E":"Microaspiração e tosse noturnas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-102768","number":"102768","sourceNumber":"102768","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Levando-se em consideração a classificação em grupos da Doença Pulmonar\nObstrutiva Crônica - DPOC-, de acordo com a\nintensidade dos sintomas e risco de exacerbações,\nassinale a alternativa que é compatível com um paciente portador de DPOC estratificado no \"grupo\nC\".","options":{"A":"VEF1 maior que 50%; duas ou mais exacerbações no último ano, dispneia aos esforços maiores\nque os habituais.","B":"50% < VEF1 < 80%; uma ou menos exacerbações no último ano e dispneia aos esforços\nmaiores que os habituais.","C":"30% < VEF1 < 50%; duas ou mais exacerbações no último ano e dispneia de repouso.","D":"VEF > 50%; uma ou menos exacerbações ao ano e dispneia aos mínimos esforços."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-100965","number":"100965","sourceNumber":"100965","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher, 23 anos, asmática em uso de budesonida 200 mcg 12/12h, vem à consulta de\nrotina referindo sintomas asmáticos diurnos cinco vezes por semana, com uso de broncodilatador\nde alívio em todas elas. Nega despertares noturnos relacionados à asma, idas ao pronto\natendimento ou limitação das atividades habituais. Espirometria evidencia distúrbio ventilatório\nleve\ncom VEF1 70% do predito. Ao exame físico a ausculta pulmonar e frequência respiratória estão\nnormais e saturação de oxigênio é de 98%. Neste caso, identifique qual o nível de controle da asma\ne a melhor abordagem a seguir.","options":{"A":"Asma controlada; manter medicação.","B":"Asma parcialmente controlada; aumentar dose de budesonida para 400 mcg de 12/12 h e\nassociar montelucaste.","C":"Asma parcialmente controlada; aumentar dose de budesonida para 400 mcg de 12/12 h e\nassociar formoterol 12 mcg de 12/12 h.","D":"Asma não controlada; aumentar dose de budesonida para 400 mcg de 12/12 h.","E":"Asma não controlada, manter a dose de budesonida e associar omalizumabe."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-100996","number":"100996","sourceNumber":"100996","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher, 63 anos, tabagista 35 anos/maço, submetida à cirurgia ginecológica há 15 dias,\nevoluiu com quadro súbito de dispneia, dor torácica tipo pleurítica, tosse e palpitações. Ao exame\nfísico apresentava frequência respiratória de 28 irpm, frequência cardíaca de 112 bpm, turgência\njugular, empastamento e dor em panturrilha direita. Ausculta cardíaca e respiratória sem alterações.\nA saturação periférica de O2 era de 93%. Assinale a alternativa INCORRETA:","options":{"A":"Dosagem plasmática positivas de d-dímero confirma o diagnóstico.","B":"Cintilografia de ventilação/perfusão positiva e/ou angiotomografia positiva confirmam o\ndiagnóstico.","C":"Após o tratamento inicial o paciente deve receber heparina não fracionada ou heparina de baixo\npeso molecular.","D":"Heparinização plena deve ser instituída imediatamente para a paciente.","E":"Pacientes com instabilidade hemodinâmica devem receber trombolíticos o mais precocemente\npossível, usualmente nas primeiras 48 horas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-106458","number":"106458","sourceNumber":"106458","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"L.M.R., 32 anos, masculino, IMC: 37,4, artropatia de coluna lombar, risco cirúrgico\napresentando história de rinite alérgica e\nespirometria com padrão restritivo leve. Submetido à\ncirurgia bariátrica tipo gastroplastia à Fobi-Capella, por vídeo. No 2º dia pós-operatório, ao\nlevantar\npara ir ao banheiro, apresentou quadro de dispneia intensa e súbita. Ao exame com esforço\ninspiratório e expiratório, FR: 26 irpm, sem ruidos adventícios, som claro pulmonar e FTV normal.\nQual a principal hipótese diagnóstica, a melhor propedêutica para confirmação diagnóstica e\ntratamento?","options":{"A":"Crise de asma - teste terapêutico - nebulização com ipatróprio e fenoterol","B":"Tromboembolismo pulmonar - gasometria arterial - heparinização plena","C":"Atelectasia - Radiografia de tórax AP e perfil - Fisioterapia respiratória e Ventilação Não\nInvasiva (VNI)","D":"Crise de asma - espirometria - adrenalina","E":"Tromboembolismo pulmonar - angiotomografia de tórax - heparinização plena"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-100956","number":"100956","sourceNumber":"100956","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Na asma é CORRETO afirmar que:","options":{"A":"Aproximadamente 50% das crianças apresentam pelo menos um episódio de sibilância nos\nprimeiros anos de vida, sendo que a maioria delas não desenvolverá asma.","B":"A prevalência de refluxo gastroesofágico em asmáticos é menos comum que na população em\ngeral.","C":"A água destilada pode servir como veículo nas nebulizações das exacerbações da asma.","D":"A aminofilina está indicada como um dos tratamentos iniciais da asma na infância.","E":"Na maioria das vezes, as exacerbações da asma, qualquer que seja sua gravidade, ocorrem de\nforma rápida, com deterioração clínica em um período de 24h e as causas mais comuns são as\ninfecções bacterianas."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-106430","number":"106430","sourceNumber":"106430","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Igor, 5 anos, tem história de sibilância, dispneia e tosse em episódios semanais, às\nvezes tem suas atividades limitadas quando\nfaz grandes esforços, e acorda na madrugada com\ntosse e sibilância pelo menos uma vez por semana. Necessita usar broncodilatadores de alívio\ncerca de 2 vezes por semana, e tem Pico de Fluxo Expiratório \"maior ou igual a\" 80% do previsto.\nDe acordo com o último Consenso Brasileiro para o Manejo de Asma, classifique a asma de Igor.","options":{"A":"Asma intermitente.","B":"Asma persistente leve.","C":"Asma persistente moderada.","D":"Asma persistente grave.","E":"Não pode ser caracterizado como asma nessa faixa etária."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-87472","number":"87472","sourceNumber":"87472","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Todas as alternativas a seguir apresentam efeitos colaterais do ?-2-agonista, EXCETO:","options":{"A":"hipocalemia.","B":"hipercalemia","C":"taquicardia.","D":"tremores.","E":"ansiedade."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-77371","number":"77371","sourceNumber":"77371","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente do sexo masculino, 44 anos, 70 kg, sem doenças prévias e totalmente\nassintomático, retorna a Cachoeiro após viagem\nnoturna de ônibus proveniente da cidade de São\nPaulo. Na manhã do mesmo dia, apresenta dispneia intensa, sendo levado ao hospital onde dá\nentrada em insuficiência respiratória e choque circulatório, sendo intubado imediatamente. Logo\napós, apresenta parada cardiorrespiratória em atividade elétrica sem pulso. É reanimado\nprontamente, com retorno em taquicardia sinusal (FC 130 bpm), PA 70 x 40 mmHg sendo iniciada\ninfusão de noradrenalina com melhora para 110 x 80 mmHg. ECG mostrando taquicardia sinusal,\nonda S em D1, onda Q em D3 com onda T invertida, além de inversão de onda T de V1 a V6. Ao\nlongo do manejo terapêutico e diagnóstico deste caso, qual das medidas abaixo é considerada\ninapropriada e totalmente inaceitável:","options":{"A":"Encaminhamento à hemodinâmica para cateterismo cardíaco e cineangiocoronografia.","B":"Dosagem de troponina.","C":"Realização de ecocardiograma na sala de emergência.","D":"Heparinização.","E":"Administração de 40 mg de tenecteplase."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-88884","number":"88884","sourceNumber":"88884","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 40 anos, sem antecedentes de broncoespasmo, apresenta quadro súbito\nde dispneia, cianose ++/+4 e sibilos pulmonares\ndifusos. Estava na enfermaria em tratamento de\npneumonia com antibiótico parenteral, sem qualquer sintomatologia até há cerca de 30 minutos.\nQual a hipótese mais provável?","options":{"A":"Embolia pulmonar.","B":"Pneumotórax espontâneo.","C":"Reação de anafilaxia.","D":"Broncoaspiração.","E":"Broncoespasmo severo."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-88872","number":"88872","sourceNumber":"88872","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem de 29 anos, vítima de acidente automobilístico sofreu fratura fechada de diáfise\nde fêmur direito. Internado com tração\nesquelética há 2 dias, começou a apresentar desconforto\nrespiratório, confusão mental, taquicardia, petéquias e febre. Gasometria revela PO2 de 55 mmHg,\n\nP.A . 110 x 70 mmHg. A hipótese diagnóstica provável é:","options":{"A":"Septicemia.","B":"Pneumonia aspirativa.","C":"Síndrome compartimental.","D":"Embolia gordurosa.","E":"TVP evoluindo com embolia pulmonar."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-88870","number":"88870","sourceNumber":"88870","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher asmática de 34 anos chega à sala de emergência em broncoespasmo. A\nacompanhante relata que a crise iniciou-se há 24 horas com piora progressiva, apesar do uso\ndoméstico de agonista B2 inalatório. Ao exame físico apresenta-se sonolenta, cianótica, afebril,\ncom sudorese profusa, pulso de 120 bpm, frequência respiratória de 32/min, e pressão arterial =\n120/90 mmHg. A ausculta pulmonar mostra murmúrio vesicular diminuído bilateralmente com\npoucos sibilos difusos e expiração prolongada. A conduta imediata mais adequada para este caso\né:","options":{"A":"Decidir a terapia baseando-se na gasometria arterial.","B":"Intubação traqueal e ventilação mecânica.","C":"Administrar B2 agonista e corticosteroide, ambos por via intravenosa.","D":"Administrar B2 agonista inalatório, aminofilina , corticosteroide intravenosos e\nantibioticoterapia\nparenteral.","E":"Ventilação não invasiva."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-59011","number":"59011","sourceNumber":"59011","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente multípara, 68 anos de idade, é internada na enfermaria cirúrgica para ser\nsubmetida à colecistectomia. Na madrugada\nda data do procedimento cirúrgico apresentou dispneia\nde estabelecimento súbito, cianose de extremidades e dor torácica retroesternal. Ao exame físico:\nconsciente, orientada no tempo e espaço, frequência respiratória de 32 ipm, frequência cardíaca de\n130 bpm, murmúrio vesicular normoaudível bilateralmente, ausência de ruídos adventícios. A\nhipótese diagnóstica mais provável é:","options":{"A":"Tromboembolismo pulmonar.","B":"Infarto agudo do miocárdio.","C":"Pneumonia bacteriana.","D":"Broncoespasmo.","E":"Endocardite bacteriana."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-59038","number":"59038","sourceNumber":"59038","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A.J.M., feminina, 62 anos, ex-tabagista de 100 anos-maço, parou há 10 anos,\napresenta quadro de dispneia aos esforços e\ntosse seca diária com predomínio matinal iniciados há\n5 anos. Atualmente refere ter que parar para descansar por diversas vezes quando anda 50 metros\nno plano, toma banho sozinha e consegue realizar atividades domésticas. Refere quadros\nfrequentes de piora da dispneia com tosse produtiva com secreção amarelada com necessidade de\nuso de antibióticos - três episódios no último ano. Espirometria evidencia distúrbio ventilatório\nobstrutivo grave sem resposta ao broncodilatador. Qual seria a melhor opção de tratamento para\nesta paciente?","options":{"A":"Vacinação para influenza, reabilitação pulmonar, fenoterol, tiotrópio, budesonida e aminofilina.","B":"Reabilitação pulmonar, salmeterol, tiotrópio e fluticasona.","C":"Vacinação para influenza, reabilitação pulmonar, formoterol, budesonida e tiotrópio.","D":"Vacinação para influenza, fenoterol, budesonida e teofilina.","E":"Reabilitação pulmonar, tiotrópio e budesonida."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-59357","number":"59357","sourceNumber":"59357","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Os novos critérios diagnósticos para Síndrome do Desconforto Respiratório Agudo -\nSDRA - (Critérios de Berlim), publicados em 2012, estabeleceram:","options":{"A":"Que a presença de relação PaO2/FiO2 < 300, a presença de infiltrados nos quatro quadrantes\npulmonares na radiografia de tórax, com pressão capilar < 18, em paciente com dificuldade\nrespiratória de início recente caracteriza a Lesão Pulmonar Aguda.","B":"Que a presença de relação PaO2/FiO2 < 100, a presença de infiltrados nos quatro quadrantes\npulmonares na radiografia de tórax, com pressão capilar < 18, em paciente com dificuldade\nrespiratória de início recente caracteriza a SDRA.","C":"Que a SDRA será caracterizada em leve, moderada ou grave, de acordo com a relação\nPaO2/FiO2 (além dos outros critérios\ndiagnósticos necessários), acabando com o conceito anterior\nde Lesão Pulmonar Aguda.","D":"Que não é necessário que o paciente esteja recebendo nenhum nível de PEEP, pondo fim a\ndiscussão quanto à sua necessidade para caracterização diagnóstica da SDRA.","E":"Que desconforto respiratório agudo será caracterizado apenas em pacientes com início de\nsintomas ou fatores predisponentes há menos\nde 48h do diagnóstico, finalmente definindo o tempo\nnecessário para a definição do conceito de agudo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-59390","number":"59390","sourceNumber":"59390","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente 35 anos, submetida há cerca de 10 dias à cirurgia plástica (abdominoplastia +\nlipoescultura), dá entrada no pronto-socorro com quadro de dispneia iniciada há cerca de 48 horas\ne agravada nas últimas horas, tendo apresentado ainda tosse com 01 episódio de hemoptise de\npequeno volume, motivo este que a levou a procurar o pronto-socorro urgentemente. Na admissão\nencontrava-se acordada, lúcida, acianótica, anictérica. Taquipneia com FR de 30 rpm e ausculta\npulmonar normal. RCR 2t com FC 140 bpm e PA 110 X 70. Abdome sem alterações além de\nesperadas de PO. Membros inferiores normais sem empastamento de panturrilhas. Você\nimediatamente suspeita da possibilidade de Tromboembolismo Pulmonar (TEP) e calcula o escore\nde probabilidade de Wells, obtendo o seguinte resultado e sua interpretação:","options":{"A":"50 = Altíssima probabilidade de TEP.","B":"7 = Alta probabilidade de TEP.","C":"30 = Probabilidade intermediária de TEP.","D":"30 = Alta probabilidade de TEP.","E":"5 = Probabilidade intermediária de TEP."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-59401","number":"59401","sourceNumber":"59401","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente 35 anos, submetida há cerca de 10 dias à cirurgia plástica (abdominoplastia +\nlipoescultura), dá entrada no pronto-socorro com quadro de dispneia iniciada há cerca de 48 horas\ne agravada nas últimas horas, tendo apresentado ainda tosse com 01 episódio de hemoptise de\npequeno volume, motivo este que a levou a procurar o pronto-socorro urgentemente. Na admissão\nencontrava-se acordada, lúcida, acianótica, anictérica. Taquipneia com FR de 30 rpm e ausculta\npulmonar normal. RCR 2t com FC 140 bpm e PA 110 X 70. Abdome sem alterações além de\nesperadas de PO. Membros inferiores normais sem empastamento de panturrilhas. Uma vez\ncalculado o escore de probabilidade de Wells no caso anterior, qual dos abaixo é o próximo passo\na ser adotado?","options":{"A":"Solicitar ecocardiograma.","B":"Solicitar cintilografia pulmonar.","C":"Solicitar Dímero D, se negativo excluir diagnóstico de TEP.","D":"Solicitar Angiotomografia de tórax.","E":"Solicitar Dímero D e se positivo solicitar Angiotomografia de tórax."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-59412","number":"59412","sourceNumber":"59412","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente 35 anos, submetida há cerca de 10 dias à cirurgia plástica (abdominoplastia +\nlipoescultura), dá entrada no pronto-socorro com quadro de dispneia iniciada há cerca de 48 horas\ne agravada nas últimas horas, tendo apresentado ainda tosse com 01 episódio de hemoptise de\npequeno volume, motivo este que a levou a procurar o pronto-socorro urgentemente. Na admissão\nencontrava-se acordada, lúcida, acianótica, anictérica. Taquipneia com FR de 30 rpm e ausculta\npulmonar normal. RCR 2t com FC 140 bpm e PA 110 X 70. Abdome sem alterações além de\nesperadas de PO. Membros inferiores normais sem empastamento de panturrilhas. Na\npossibilidade de seu diagnóstico de Tromboembolismo Pulmonar (TEP) estar correto e for\nconfirmado, qual das condutas abaixo é a mais adequada?","options":{"A":"Heparinização plena e trombólise com alteplase.","B":"Trombólise com estreptoquinase e heparinização apenas ao término da sua infusão.","C":"Heparinização plena, solicitar ecocardiograma e, caso haja disfunção ventricular direita, indicar\ntrombólise com alteplase.","D":"Heparinização plena com enoxaparina e iniciar warfarina no mesmo dia.","E":"Heparinização plena, monitorização em CTI por pelo menos 48 horas, indicando trombólise com\nalteplase somente se evoluir com instabilidade hemodinâmica."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-59376","number":"59376","sourceNumber":"59376","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente é admitido no Pronto-Socorro do Hospital Evangélico em insuficiência\nrespiratória e realiza a radiografia de tórax\nabaixo (VER IMAGEM). Baseado neste caso responda:\nQual o diagnóstico?","options":{"A":"Pneumonia à esquerda.","B":"Derrame pleural volumoso à esquerda.","C":"Hérnia diafragmática à esquerda.","D":"Atelectasia do pulmão esquerdo.","E":"Atelectasia do pulmão direito."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/59376.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-59381","number":"59381","sourceNumber":"59381","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente é admitido no Pronto-Socorro do Hospital Evangélico em insuficiência\nrespiratória e realiza a radiografia de tórax\nabaixo (VER IMAGEM). Baseado neste caso responda:\nApós as medidas iniciais de suporte clínico para tratamento da insuficiência respiratória, qual das\nmedidas listadas abaixo é a mais importante?","options":{"A":"Iniciar levofloxacina.","B":"Drenagem torácica.","C":"Toracocentese diagnóstica.","D":"Tomografia de tórax.","E":"Broncoscopia."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/59381.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-59093","number":"59093","sourceNumber":"59093","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"São afirmações verdadeiras relacionadas à asma, exceto:","options":{"A":"Sintomas duas vezes por semana ou menos, sem despertares noturnos e sem limitação das\natividades pode ser considerado um quadro de asma controlada.","B":"Espaçadores reduzem a biodisponibilidade sistêmica e efeitos adversos dos corticoides\ninalatórios.","C":"O uso de corticoide oral ou intravenoso tem efeito clínico equivalente na crise de asma.","D":"A nebulização pode ser feita com soro fisiológico ou água destilada.","E":"O tratamento da rinite melhora os sintomas da asma."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-59097","number":"59097","sourceNumber":"59097","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Pré-escolar, masculino, quatro anos, veio para consulta de rotina e a mãe queixa-se de\nrespiração rápida e que seus lábios ficam \"azulados\" quando corre ou está em jogos de\ncompetição. Esse quadro desaparece quando cessam as atividades físicas. Apresenta ao exame\nsopro sistólico ++/6 que irradia para o dorso. A intolerância ao exercício provavelmente é devido\na:","options":{"A":"Asma.","B":"Atresia tricúspide.","C":"Estenose pulmonar.","D":"Comunicação interatrial.","E":"Comunicação interventricular."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-44006","number":"44006","sourceNumber":"44006","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem, 75 anos, encontra-se no dia 06 de pós-operatório de drenagem de hematoma\nsubdural. Ele evoluiu com insuficiência respiratória aguda, acompanhada por hemoptise, sendo\nconfirmado diagnóstico de embolismo pulmonar agudo, através da angiotomografia de tórax.\n\nAssinale abaixo a assertiva INCORRETA em relação ao embolismo pulmonar agudo:","options":{"A":"Trauma, cirurgia e imobilização prolongada são importantes fatores de risco.","B":"Existe indicação para a utilização de filtro em veia cava.","C":"A presença de tomografia helicoidal normal não descarta tromboembolismo pulmonar em\npacientes com alta probabilidade clínica.","D":"A trombólise está contraindicada.","E":"Hipoxemia ocorre raramente (05 a 15%) nos pacientes com embolismo pulmonar agudo,\nsecundária ao desequilíbrio da relação ventilação/perfusão."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-43316","number":"43316","sourceNumber":"43316","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual dos achados abaixo NÃO é típico da sarcoidose?","options":{"A":"Linfonodomegalias hilares.","B":"Predomínio nos lobos inferiores.","C":"Padrão perilinfático.","D":"Predomínio nos lobos superiores."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-43957","number":"43957","sourceNumber":"43957","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente feminina, 35 anos, passado de asma brônquica. Foi admitida na emergência\ncom dispneia e sibilos difusos. Ao exame\nfísico: frequência respiratória = 40 rpm, frequência\ncardíaca = 120 bpm, lúcida e orientada, mas com dificuldade de falar. SpO2 = 90% sob uso de\nmáscara com oxigênio 10 L/min. As seguintes opções terapêuticas são apropriadas para essa\npaciente, exceto:","options":{"A":"Os beta-adrenérgicos de curta duração são os medicamentos de escolha para o tratamento das\nexacerbações, sendo a via inalatória a primeira opção.","B":"Corticosteroide deverá ser utilizado na crise aguda, por ser efetivo em reduzir a inflamação das\nvias aéreas.","C":"Deve-se evitar a associação de anticolinérgico (brometo de ipratrópio) ao beta-adrenérgico\nnessa paciente, pela possibilidade de piora na função\npulmonar.","D":"A aminofilina não deve ser utilizada rotineiramente, por ter efeito broncodilatador menos intenso\nem relação ao beta-adrenérgico e aumentar o\nrisco de efeitos adversos, como tremores, náuseas e\ntaquiarritmia.","E":"O sulfato de magnésio pode ser utilizado nos pacientes asmáticos graves, na dose de 2 g em\ninfusão lenta (10 a 15 minutos)."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-43324","number":"43324","sourceNumber":"43324","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 18 anos, sexo masculino, longilíneo, foi admitido no pronto-socorro\nrelatando que após crise de tosse intensa\niniciou com quadro de dor torácica súbita, de forte\nintensidade, à esquerda, com irradiação para o abdome, associada à dispneia inicialmente leve,\nporém com piora rapidamente progressiva, tornando-se intensa na admissão no pronto-socorro. Ao\nexame físico encontra-se taquicárdico 150 bpm, hipotenso PA 80 x 40 mmHg, intensamente\ndispneico, grande esforço respiratório, sons pulmonares abolidos em hemitórax esquerdo. Qual a\nprincipal suspeita diagnóstica?","options":{"A":"Embolia pulmonar maciça.","B":"Pneumonia por estafilicocos.","C":"Derrame pleural volumoso.","D":"Pneumotórax hipertensivo.","E":"Taquicardia supraventricular com repercussão hemodinâmica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-43326","number":"43326","sourceNumber":"43326","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 18 anos, sexo masculino, longilíneo, foi admitido no pronto-socorro\nrelatando que após crise de tosse intensa\niniciou com quadro de dor torácica súbita, de forte\nintensidade, à esquerda, com irradiação para o abdome, associada à dispneia inicialmente leve,\nporém com piora rapidamente progressiva, tornando-se intensa na admissão no pronto-socorro. Ao\nexame físico encontra-se taquicárdico 150 bpm, hipotenso PA 80 x 40 mmHg, intensamente\ndispneico, grande esforço respiratório, sons pulmonares abolidos em hemitórax esquerdo. Qual a\nmedida inicial e mais importante a ser tomada?","options":{"A":"Angiotomografia de tórax seguida de trombólise.","B":"Internação em CTI e inicio de antibiótico apropriado na primeira hora.","C":"Drenagem torácica em selo d'agua.","D":"Punção do hemitórax esquerdo com jelco 14 no segundo espaço intercostal/linha hemiclavicular.","E":"Cardioversão elétrica sincronizada sob sedação."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-43325","number":"43325","sourceNumber":"43325","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Grávida de 32 semanas, inicia em 01/08/2009 com febre elevada e tosse seca. Realiza\nradiografia de tórax e é medicada com amoxicilina. Persiste com febre, evolui com dispneia. É\nnovamente atendida em 08/08/2009, sendo realizado raio X de tórax que mostra áreas de\nhipotransparência em ambos pulmões, com predomínio nos terços inferiores. Desta vez é\ninternada em sua cidade local e seu antibiótico é trocado para ceftriaxone. Não apresenta melhora\nnos 02 dias seguintes, sendo transferida para o HECI para avaliação com pneumologista. É\nadmitida em 11/08/2009, às 16h, com cianose de extremidades, corada, hidratada. Presença de\ncreptações finas difusas, com acentuada diminuição dos sons pulmonares em bases. SaO2 de 68%\nem ar ambiente. FR 35 rpm. Sem esforço respiratório significativo. É levada ao CTI onde\ninicialmente recebe suporte ventilatório não invasivo e após, com uso de O2 suplementar,\napresentou melhora clínica com aumento da SaO2 96%. Na manhã de 12/08, apresenta\nsignificativa piora clínica, com FR 45 rpm, SaO2 de 84% mesmo com altas frações de O2, e grande\nesforço respiratório. Exames revelando: Hb 10, leuc 12.000 (NB0; NS 80; E 5; M5; L 10), PCR 20,\nDHL 2200 RX tórax: infiltrado pulmonar difuso nos quatro quadrantes. Acerca do caso em questão,\nmarque a alternativa CORRETA:","options":{"A":"Trata-se de provável infecção pelo vírus H1N1, sendo indicado isolamento respiratório imediato.","B":"A presença de insuficiência respiratória com elevação de DHL acima de 1500 caracteriza o\ndiagnóstico de pneumocistose, sendo indicado o uso de Bactrin.","C":"Independente da etiologia, trata-se de Síndrome do Desconforto Respiratório Agudo grave.\n\nDeve-se proceder a imediata cesariana e logo após realizar a intubação orotraqueal para controle\nda hipoxemia.","D":"Independente da etiologia, trata-se de Síndrome do Desconforto Respiratório Agudo grave.\n\nDeve-se proceder imediata intubação orotraqueal para controle da hipoxemia e realizar a cesariana\nimediata devido aos elevados riscos para o feto.","E":"Independente da etiologia, trata-se de Síndrome do Desconforto Respiratório Agudo grave.\n\nDeve-se proceder a imediata intubação orotraqueal para controle da hipoxemia e a realização de\n\ncesariana não deverá ser imediata, porém, após administração de corticoide para maturação\npulmonar do feto."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-32422","number":"32422","sourceNumber":"32422","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A doença tromboembólica mantém-se como causa importante de morbidade e\nmortalidade no pós-operatório de\nintervenções operatórias de grande porte. Assinale a alternativa\nincorreta na prevenção, diagnóstico e tratamento do binômio trombose venosa\n\nprofunda-tromboembolismo pulmonar:","options":{"A":"O encorajamento à deambulação precoce e a movimentação ativa e passiva dos membros\ninferiores para reduzir a estase venosa e\nfortalecer o retorno venoso constituem método barato e\nmuito eficaz para profilaxia da doença tromboembólica no pós-operatório.","B":"A obesidade é um fator de risco para a trombose venosa profunda.","C":"Na suspeita clínica de tromboembolismo pulmonar, o teste do D-dímero pode ser utilizado.\n\nApresenta alta sensibilidade e baixa especificidade. É de grande valia para a exclusão do\ndiagnóstico de tromboembolismo pulmonar.","D":"A profilaxia medicamentosa com baixas doses de heparina pode ser mantida inclusive em casos\nde hemorragia ativa, plaquetopenia e\nneurocirurgia.","E":"O filtro de veia cava pode ser utilizado em casos de trombos em território ilíaco-femoral."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-23129","number":"23129","sourceNumber":"23129","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Responda às próximas duas perguntas baseados neste caso clínico e de acordo com\nas IV Diretrizes Brasileiras para Manejo da\nAsma. A mãe de uma menina de dois anos de idade\nrelata na consulta pediátrica de rotina que sua filha ?vive gripada?. Refere que a criança apresenta\nquadros repetidos de coriza, obstrução nasal e espirros. Praticamente toda semana precisa utilizar\nnebulização com beta 2 agonista para alívio de tosse e ?cansaço?. Estes quadros ocorrem há\ncerca de um ano e melhora rápido quando nebuliza. No momento a criança está bem, sem queixas\ne no exame físico o pediatra observa lesões compatíveis com dermatite atópica. A mãe é asmática,\nmas não faz uso de medicação profilática: o pai fuma em casa. O diagnóstico do pediatra foi asma.\nQuais critérios (maiores e menores) deste caso que justifiquem este diagnóstico, considerando a\nidade da criança?","options":{"A":"Resposta a broncordilatador, fumante no domicílio, sintomas de rinite alérgica.","B":"História familiar de asma, sintomas de rinite alérgica, dermatite atópica.","C":"Fumante no domicílio, sintomas de rinite alérgica, sibilância na ausência de quadro gripal.","D":"Fumante no domicílio, dormatite atópica, sibilância na ausência de quadro gripal.","E":"Resposta a broncordilatador, história familiar de asma, sintomas de rinite alérgica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-23133","number":"23133","sourceNumber":"23133","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Responda às próximas duas perguntas baseados neste caso clínico e de acordo com\nas IV Diretrizes Brasileiras para Manejo\nda Asma. A mãe de uma menina de dois anos de idade\nrelata na consulta pediátrica de rotina que sua filha ?vive gripada?. Refere que a criança apresenta\nquadros repetidos de coriza, obstrução nasal e espirros. Praticamente toda semana precisa utilizar\nnebulização com beta 2 agonista para alívio de tosse e ?cansaço?. Estes quadros ocorrem há\ncerca de um ano e melhora rápido quando nebuliza. No momento a criança está bem, sem queixas\ne no exame físico o pediatra observa lesões compatíveis com dermatite atópica. A mãe é asmática,\nmas não faz uso de medicação profilática: o pai fuma em casa. Qual a classificação proposta para o\nquadro de asma desta criança e qual conduta?","options":{"A":"Asma intermitente/somente medicação para alívio das crises.","B":"Asma intermitente/medicação para alívio das crises, corticoide inalatório de manutenção.","C":"Asma persistente leve/ medicação para alívio das crises/ corticoide inalatório de manutenção.","D":"Asma persistente leve/ medicação para alívio das crises/ corticoide inalatório associado a beta 2\nagonista de longa duração na manutenção.","E":"Asma persistente leve/ somente medicação para alívio das crises."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-9403","number":"9403","sourceNumber":"9403","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Ao examinar um paciente com quadro de DPOC, você detecta o bordo inferior do\nfígado a 4 cm do RCD, consistência normal,\nsem nódulos, indolor. É correto afirmar apenas com\neste dado que:","options":{"A":"O paciente tem hepatomegalia.","B":"O paciente tem o fígado rebaixado devido à hiperinsuflação pulmonar.","C":"Você deve continuar seu exame e definir o limite do bordo superior para então avaliar se há ou\nnão hepatomegalia.","D":"Você necessita de uma ultrassonografia para determinar o tamanho do fígado, pois não há como\ndefinir pelo exame físico.","E":"A palpação do fígado abaixo do rebordo costal sempre define a presença de hepatomegalia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-9430","number":"9430","sourceNumber":"9430","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"São complicações associadas ao uso de oxigênio, EXCETO:","options":{"A":"Displasia broncopulmonar.","B":"Traqueobronquite.","C":"Aumento do apetite.","D":"Em altas concentrações pode levar à atelectasia.","E":"Cefaleia."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-9444","number":"9444","sourceNumber":"9444","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Assinale a INCORRETA sobre o diagnóstico diferencial de asma:","options":{"A":"Fibrose cística.","B":"Síndrome de Löeffler.","C":"Aspiração de corpo estranho.","D":"Fístulas traqueoesofágicas.","E":"Somente uma das acima não faz parte do diagnóstico diferencial de asma."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-8154","number":"8154","sourceNumber":"8154","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sobre asma, segundo a IV Diretrizes Brasileiras para o Manejo da Asma, é correto\nafirmar, exceto:","options":{"A":"O tratamento da asma leva em conta o grau de gravidade da doença.","B":"Doses adequadas e repetidas de Beta 2 agonista de curta duração por via inalatória, a cada10 a\n30 minutos na primeira hora, constitui a\nmedida inicial de tratamento de uma crise de asma na\ncriança.","C":"Os critérios maiores que sugerem o diagnóstico de asma no lactente são: um dos pais com\nhistória de asma e diagnóstico de dermatite atópica no paciente.","D":"O uso de corticoide oral está indicado no tratamento da crise de asma.","E":"Na criança com asma classificada como intermitente, a medicação de escolha para o tratamento\nde manutenção é um corticoide inalatório."},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-363959","number":"363959","sourceNumber":"363959","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher de 68 anos, hipertensa, diabética e dislipidêmica, apresentou quadro de perda\nda consciência e hemiplegia à direita. Foi\nencaminhada ao pronto-socorro onde foi levantada a\nhipótese de doença carotídea aterosclerótica. Qual dos seguintes exames deverá ser solicitado\npara iniciar o rastreamento da doença em questão?","options":{"A":"Angiografia das carótidas.","B":"Ecodoppler de carótidas.","C":"Angiorressonância de carótidas.","D":"Angiotomografia das carótidas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-366970","number":"366970","sourceNumber":"366970","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual dos seguintes é um exemplo de distúrbio hipocinético?","options":{"A":"Burnout.","B":"Tremor essencial.","C":"Distrofia miotônica.","D":"Parkinsonismo."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-353817","number":"353817","sourceNumber":"353817","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O Outubro Rosa é um movimento global que ocorre anualmente com o objetivo de\nsensibilizar a população sobre a importância da prevenção e do diagnóstico precoce do câncer de\nmama. Com relação às recomendações para mulheres com maior risco de desenvolver esta\ndoença, é CORRETO afirmar:","options":{"A":"As mulheres com maior risco de ter o câncer de mama devem tomar cuidados especiais,\nfazendo, a partir dos 35 anos de idade, o\nexame clínico das mamas e a mamografia, uma vez por\nano.","B":"As mulheres com maior risco de ter o câncer de mama devem tomar cuidados especiais,\nfazendo, somente a partir dos 50 anos de idade,\no exame clínico das mamas e a mamografia, uma\nvez por ano.","C":"As mulheres com maior risco de ter o câncer de mama devem tomar cuidados especiais,\nfazendo, a partir dos 50 anos de idade, o\nexame clínico das mamas e a mamografia, duas vezes\npor ano.","D":"As mulheres com maior risco de ter o câncer de mama devem tomar cuidados especiais,\nfazendo, a partir dos 35 anos de idade, o exame\nclínico das mamas e a mamografia, de 5 em 5\nanos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-353816","number":"353816","sourceNumber":"353816","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O câncer de próstata é o mais frequente entre os homens, depois do câncer de pele.\nCom relação ao diagnóstico e características deste câncer, é CORRETO afirmar:","options":{"A":"A doença é confirmada após alteração no exame de sangue (PSA).","B":"A doença é confirmada após alteração no exame de toque retal.","C":"O câncer de próstata, na maioria dos casos, cresce rapidamente, se espalha para outros órgãos\ne causa morte.","D":"Não é recomendado que se realize o rastreamento do câncer de próstata em homens sem sinais\nou sintomas."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-353810","number":"353810","sourceNumber":"353810","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A avaliação clínica periódica tem como objetivo o diagnóstico precoce ou o controle de\nfatores de risco de doenças potencialmente tratáveis em pacientes assintomáticos. Porém, vale\nressaltar que os exames devem ser solicitados com cautela, pois interferem na vida de pacientes\nassintomáticos. Dito isso, a alternativa que apresenta critérios necessários para a aceitação de um\nexame como forma de rastreamento é:","options":{"A":"A doença deve representar um problema de saúde pública que seja relevante; a doença deve ter\nhistória natural bem conhecida; deve existir estágio pré-clínico bem definido; o benefício da\ndetecção e do tratamento deve ser superior aos riscos.","B":"Os exames devem ser aceitáveis e confiáveis; a doença deve ser um problema de saúde de\ndifícil detecção; a fase assintomática pode não permitir detecção.","C":"O benefício do tratamento precoce supera os riscos da doença; a história natural da doença não\ninterfere no diagnóstico; os exames podem ser de difícil acesso.","D":"A sobrevida com tratamento deve ser superior ao curso natural da doença; a magnitude da\ndoença não tem grande relevância para a\nsaúde pública; os exames devem ser acessíveis e estar\ndisponíveis."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-342597","number":"342597","sourceNumber":"342597","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"São nervos colinérgicos, exceto:","options":{"A":"os nervos motores que inervam o músculo esquelético","B":"os neurônios pré-ganglionares parassimpáticos e simpáticos","C":"os neurônios colinérgicos centrais","D":"os neurônios das fibras da dor dos tipos A delta e C"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-331963","number":"331963","sourceNumber":"331963","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem, 65 anos, hipertenso controlado, sem outras doenças, comparece consulta de\nrotina. O acompanhante refere alteração de comportamento há cerca de cinco anos, com\nagravamento há dois meses, quando ficou mais confuso. Refere que o paciente urina no meio da\nsala, tira a roupa na rua e estoca comida no guardaroupa. Às vezes come doces compulsivamente.\nExame neurológico: sem déficits focais. A hipótese diagnóstica é:","options":{"A":"Doença de Alzheimer.","B":"Demência por Corpúsculos de Lewy.","C":"Demência fronto-temporal.","D":"Demência vascular."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-339760","number":"339760","sourceNumber":"339760","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Observando a imagem a seguir, responda a provável alteração:","options":{"A":"Tumor de provável etiologia primária cerebral.","B":"Insulto isquêmico crônico em território da circulação posterior.","C":"Hemorragia intraparenquimatosa cerebral.","D":"Insulto isquêmico recente no território da artéria cerebral média esquerda.","E":"Vasculite."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/339760.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-330066","number":"330066","sourceNumber":"330066","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Considerando a comunicação realizada com pacientes portadores de doenças\noncológicas com caráter progressivo fora de\npossibilidade de cura, entre os temas a serem tratados\ncom o paciente, é INCORRETO afirmar:","options":{"A":"Diagnósticos e prognóstico.","B":"Planejamento para o futuro.","C":"Transição de tratamento curativo para cuidado paliativo.","D":"Questão de início de vida."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-330078","number":"330078","sourceNumber":"330078","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sobre as síndromes geriátricas, é INCORRETO afirmar:","options":{"A":"As incontinências urinárias podem ser divididas em: incontinência de esforço, de urgência, mista,\npor hipotonia do detrusor e paradoxal.","B":"A proliferação de drogas, procedimentos terapêuticos e diagnósticos na medicina atual\naumentam a incidência de iatrogenia, sobretudo na população idosa.","C":"O delirium é um quadro confusional agudo, com comprometimento flutuante da atenção e da\nfunção cognitiva.","D":"Os principais fatores de risco para a síndrome da instabilidade e quedas na população idosa\nfrágil são os extrínsecos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-342628","number":"342628","sourceNumber":"342628","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 65 anos relata tremor progressivo das mãos, de início insidioso, há 3\nanos, que dificulta a escrita e o manuseio de objetos, particularmente de talheres. Ao exame\nneurológico, observou-se tremor postural nas mãos à extensão dos membros superiores. A marcha\nera atípica, e o tônus, normal. Qual é a melhor opção terapêutica para esse paciente?","options":{"A":"agonista dopaminérgico","B":"betabloqueador","C":"levodopa","D":"clonazepam"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-334802","number":"334802","sourceNumber":"334802","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A localização mais comum dos aneurismas intracranianos das circulações anterior e\nposterior é, respectivamente,","options":{"A":"comunicante anterior e topo da basilar.","B":"comunicante posterior e cerebelar posteroinferior.","C":"cerebral média e comunicante posterior.","D":"comunicante anterior e comunicante posterior."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-334850","number":"334850","sourceNumber":"334850","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual rastreamento atende aos princípios de prevenção quaternária e às orientações do\nMinistério da Saúde?","options":{"A":"J., 20 anos de idade, sexo masculino, rastreamento de hipertensão arterial.","B":"C., 42 anos de idade, sexo masculino, rastreamento de câncer de cólon e reto.","C":"L., 34 anos de idade, sexo feminino, rastreamento de dislipidemia.","D":"J., 32 anos de idade, sexo masculino, rastreamento de câncer de tireoide."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-334852","number":"334852","sourceNumber":"334852","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente sexo masculino, 83 anos de idade, admitido no pronto socorro portador de\ndoença pulmonar obstrutiva crônica e em uso de\noxigenioterapia domiciliar há 12 meses. Apresenta\nperda de 10 kg nos últimos 10 meses e várias internações nos últimos 2 anos devido a\nexarcebações. Há 4 semanas não consegue levantar da cama, devido a fadiga intensa. Mantém\ndesconforto respiratório a despeito do tratamento otimizado da doença de base. Uso de antibióticos\ne adequada titulação de morfina em infusão contínua. De acordo com o caso relatado, qual é o\nmanejo para este paciente, elegível para cuidados paliativos?","options":{"A":"Intubação orotraqueal devido a refratariedade da dispneia.","B":"Sedação paliativa deverá ser discutida com a família e com a equipe uma vez que neste cenário\no paciente não tem autonomia.","C":"Sedação paliativa está contraindicada uma vez que acelera o processo de morte.","D":"Sedação paliativa está indicada se o sintoma for intolerável para o paciente."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-300810","number":"300810","sourceNumber":"300810","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente, sexo feminino, 50 anos, queixando-se de cefaleia forte, de aparecimento\nabrupto com duração de 10 horas. Relata que a\ndor é difusa, latejante e piorou quando saiu ao ar\nlivre e se expôs à luz solar. Após análise detalhada dos sintomas, a conclusão é para diagnóstico\nde hemorragia subaracnoidea. A alternativa que apresenta CORRETAMENTE achados clássicos\nde exame para o diagnóstico de hemorragia subaracnoidea é:","options":{"A":"Hemorragia de retina ou sub-hialoide, meningismo, paralisia do terceiro ou sexto nervo.","B":"Febre, meningismo, estado mental alterado, Sinais de Kernig e Brudzinski.","C":"Papiledema, dificuldades cognitivas, déficits neurológicos focais.","D":"Sensibilidade ou enduração na artéria temporal, pulsação diminuída ou ausente na artéria\ntemporal, edema de nervo óptico."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-313204","number":"313204","sourceNumber":"313204","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Homem de 64 anos apresenta quadro de tremor de mãos bilateral, associado à\nlentificação de movimentos (principalmente do\nbalanço dos braços ao deambular), além de\ndificuldade para sustentar movimentos repetitivos e instabilidade de marcha. Esta em uso de\nenalapril, metformina, flunarizina e metoclopramida,. Considerando as informações dadas, assinale\na alternativa que apresenta o diagnóstico e a conduta adequada para o caso:","options":{"A":"parkinsonismo secundário; suspender medicações com efeitos colaterais","B":"parkinsonismo secundário; associar agonista dopaminérgico com inibidor da COMT","C":"doença de Parkinson suspender medicações","D":"doença de Parkinson iniciar inibidor da COMT"},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-317169","number":"317169","sourceNumber":"317169","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sra. ABC, mulher, 62 anos, vem à consulta médica em UBS com sensação de cansaço,\nfraqueza e mal estar. Refere dispneia aos\npequenos esforços, cansando para atividades de vida\ndiário (tomar banho e vestir a roupa). É tabagista de cigarro branco desde os 12 anos, em média 20\ncigarros ao dia. Na infância já trabalhou na lavoura, e tinha fogão e lenha em casa. Desconhece\ncomorbidades, mas diz que raramente vai ao médico. Não lembra quando foi a última vacina que\ntomou, pois os locais de vacinação são sempre longe de casa e a paciente não tem quem a leve\npara a vacinação. Baixa aceitação alimentar, comendo mais sopas e alimentos batidos, alega que\ncomidas secas e em pedaços maiores tem dificuldade para deglutição. Tem perda ponderal de 7kg\nnos últimos 2 meses. Nunca fez cirurgias, desconhece doenças de infância. É etilista ativa, em\nmédia 7 latinhas de cerveja ao dia. Nega queixas alérgicas, nega vômitos, nega diarreia. Refere\nque a urina está mais escura e em menor volume nos últimos meses. Ao exame físico: Peso 42 kg.\nA 1,65; SpO2 90%, FR 18irpm; FC 103bpm; PA 170x120mmHg; Tax: 37,2ºC; Descorada +/4,\ndesidratada 2+/4, eupneica em arambiente, lúcida e orientada no tempo e espaço, contactuante\ncom o examinador. Ausculta respiratória: murmúrio vesicular redizido difusamente, sem estertores\ncrepitantes. Expansibilidade pulmonar preservada. Ausculta cardíaca: ritmo regular, em 2 tempo,\nbulhas normofonéticas, sem sopros. Abdome escavado, doloroso a palpação profunda em eigastro,\ndescombressão brusca negativa. Extremidades sem edema de membros inferiores, pulso\nperiféricos palpáveis e simétricos, tempo de enchimento capilar normal. Neurológico: sem sinais\nfocais, verbaliza sem dificuldade, movimenta os quatro membros, sem paresias ou paralisias. A\ninvestigação de fraqueza, mal estar e cansaço nessa paciente deve conter:","options":{"A":"Realização de eletrocardiograma para avaliação de função cardíaca.","B":"Realização de exames de sangue com avaliação de função da tireoide, diabetes, dislipidemia,\nperfil ósseo, vitamina D e vitamina B12, função\nrenal e função hepática.","C":"Prova de função pulmonar, sem uso de broncodilatador.","D":"Solicitação de exame de PET-SCAN, pela possibilidade de Câncer, dessa forma é possível\nrastrear eventos neoplásicos."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-294276","number":"294276","sourceNumber":"294276","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um homem de 52 anos apresentou-se ao neurologista queixando-se de um tremor. Sua\nesposa havia notado que o sintoma teve\ninício há um ano, principalmente quando estava em\nrepouso. Ele também reclamou de andar mais devagar, e sua esposa relatou que sua voz estava\nmais suave. Relatou que sua caligrafia havia ficado menor e que era saudável e não tinha queixas\nde problemas cognitivos. No exame físico, ele tinha um tremor de repouso com frequência\nmoderada na mão direita, com leve roda dentada no braço direito. Ao exame da marcha, ele tinha\numa postura ligeiramente flexionada e balançou o braço direito menos do que o esquerdo. Qual é o\ndiagnóstico mais provável para esse paciente?","options":{"A":"Doença de Parkinson idiopática.","B":"Demência com Doença do Corpo de Lewy (DCL).","C":"Parkinsonismo vascular.","D":"Parkinsonismo induzido por drogas."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-313210","number":"313210","sourceNumber":"313210","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Uma mulher de 65 anos apresenta história de acidente vascular cerebral no lobo frontal\nesquerdo. Qual dos seguintes sintomas psiquiátricos está mais frequentemente associado a um\nacidente vascular cerebral nessa área do cérebro?","options":{"A":"pânico","B":"mania","C":"depressão","D":"obsessões"},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-316326","number":"316326","sourceNumber":"316326","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 68 anos, diabético, hipertenso sem controle adequado, apresentou quadro\nsúbito de hemiparesia completa\ndesproporcionada à esquerda. Foi encaminhado ao PS de AVC\nurgente, chegando lá com 02 horas de ictus. Ao exame: PA 160 x 110mmHg / FC: 88bpm / RCR 2T\nBNF / Glicemia: 110mg/dl / Hemograma sem alterações / TAP e TTPA = normais NIHSS = 14 /\nASPECTS = 10 / TC de crânio = normal / AngioTC de crânio = oclusão no segmento M1 da artéria\ncerebral média direita. Diante do quadro neurológico em questão, e imaginando um cenário ideal e\notimizado, qual a melhor alternativa terapêutica para esse paciente?","options":{"A":"Trombectomia mecânica direta, pois NIHSS muito elevado aumenta a chance de sangramento\npós-trombólise.","B":"Ressonância de crânio para avaliar Mismatch e trombólise endovenosa.","C":"Trombólise endovenosa, angioTC de controle, trombectomia mecânica caso oclusão permaneça.","D":"Ressonância de crânio para avaliar Mismatch, trombólise endovenosa seguida de trombectomia\nmecânica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-316327","number":"316327","sourceNumber":"316327","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O acrônimo CADASIL (Cerebral Autosomal Dominant Arteriopathy with Subcortical\nInfarcts and Leukoencephalopathy) constitui\ndoença genética causada por mutações. É a causa\ngenética mais freqüente de infartos cerebrais e constitui modelo importante de estudo de\ndemências. Os sintomas dessa doença geralmente iniciam na 3ª ou 4ª décadas de vida, afetando\nindivíduos de ambos os sexos. Tem como principais manifestações enxaqueca, depressão, crises\nepiléticas, ataques isquêmicos transitórios (AITs), paralisia pseudobulbar e demência progressiva.\nQual gene mutante está envolvido na CADASIL?","options":{"A":"P53","B":"NOTCH3","C":"P21","D":"NGHK1"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-308265","number":"308265","sourceNumber":"308265","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Cuidados Paliativos é uma especialidade nova e foi recentemente reconhecida pelo\nMinistério da Saúde como área de atuação médica. Considerando os princípios determinados pela\nOMS, é correto afirmar que:","options":{"A":"A família/cuidador não são considerados importantes no processo de atendimento.","B":"Esses cuidados devem melhorar a qualidade de vida podendo influenciar de maneira positiva o\ncurso da doença.","C":"Esses cuidados não podem ser realizados por profissionais de maneira individual.","D":"Esses cuidados devem prover apenas alivio da dor e devem ser iniciados apenas após ser\ndeterminado término do tratamento oncológico com intenção curativa."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-311954","number":"311954","sourceNumber":"311954","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em relação aos programas de rastreamento existentes é correto afirmar:","options":{"A":"é indicado rastreamento de câncer de próstata para todos os homens após os 50 anos com PSA\nem suas frações livre e total, anualmente.","B":"é indicado rastreamento de dislipidemias de homens com alto risco cardiovascular a partir dos\n25 anos, anualmente.","C":"não é indicado rastreamento de hipertensão arterial sistêmica para menores de 18 anos.","D":"é indicado rastreamento de câncer de mama para mulheres entre 45 e 74 anos, bianualmente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-300980","number":"300980","sourceNumber":"300980","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A endarterectomia de carótida é uma cirurgia consagrada no tratamento da isquemia\ncerebral de origem extracraniana. Sobre suas complicações, é CORRETO afirmar:","options":{"A":"A microembolização cerebral pode levar a acidente vascular encefálico.","B":"A lesão intra-operatória do nervo vago causa alteração motora de metade da língua.","C":"A lesão do nervo hipoglosso pode levar a regurgitações alimentares, com broncoaspiração e\npneumonia de repetição.","D":"O ramo mandibular do nervo facial quando lesado leva a dificuldade em emitir notas de timbre\nagudo e resulta em fatigabilidade da voz."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-273132","number":"273132","sourceNumber":"273132","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Os cuidados paliativos buscam oferecer assistência com o objetivo de melhorar a\nqualidade de vida de um indivíduo doente, aliviando o sofrimento diante de uma doença incurável\nque possa pôr fim à sua vida. Para que isso não seja confundido com a inércia do profissional de\nsaúde em não fazer mais nada pelo paciente e dele ter pena, a Organização Mundial da Saúde\n(OMS) aponta alguns princípios fundamentais concernentes ao cuidado paliativo, dentre os quais\nse EXCLUI:","options":{"A":"Apressar uma morte.","B":"Melhorar a qualidade de vida do paciente.","C":"Integrar os aspectos psicológicos e espirituais de cuidados do paciente.","D":"Promover o alívio da dor."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-281815","number":"281815","sourceNumber":"281815","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente do sexo feminino, de 45 anos, dá entrada no pronto-socorro da Santa Casa\ncom hemiparesia direita e afasia, NIHSS 16, PA\n130x90 mmHg, FC = 70 bpm. Acompanhante nega\ncomorbidades prévias e refere que a mesma teve infecção por Covid-19 há cerca de um mês.\n\nTambém refere que os sintomas iniciaram-se há cerca de uma hora. Foi então realizado uma\ntomografia de crânio sem sinais de isquemia e/ou sangramento, exames laboratoriais e glicemia\nsem alterações. Diante do caso apresentado, qual deve ser a conduta?","options":{"A":"Internação aos cuidados da neurologia para prosseguir investigação com ressonância magnética\nde crânio.","B":"Administrar ataque de ácido acetilsalicílico na dose de 300 mg e internar a paciente em leito de\nterapia intensiva para prosseguir investigação etiológica.","C":"Realizar punção liquórica para descartar processo infeccioso meníngeo.","D":"Iniciar Alteplase na dose de 0,9 mg/kg e monitorizar a PA, nível de consciência e déficit\nneurológico com a escala de NIHSS."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-277417","number":"277417","sourceNumber":"277417","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A lesão isolada do III par craniano leva a sinais clínicos como:","options":{"A":"desvio contralateral da língua","B":"disfonia por paralisia de corda vocal ipsilateral","C":"miose e estrabismo convergente ipsilateral","D":"midríase e ptose palpebral ipsilateral"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-281984","number":"281984","sourceNumber":"281984","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Aposentado de 72 anos, hipertensão arterial mal controlada, apresentou quadro súbito\nde hemiparesia desproporcionada em dimidio\nesquerdo. Ao ser avaliado pelo neurologista no\npronto-socorro, notou-se que o paciente não percebeu uma leve percussão no lado esquerdo do\nseu corpo, estimulo este simultâneo e na mesma localização do lado direito. Quando foi requisitado\na ele que desenhasse uma casa e uma árvore, o paciente desenhou apenas os lados direitos\ndesses objetos. Diante de tais alterações, qual lobo cerebral foi afetado?","options":{"A":"Lobo parietal direito.","B":"Lobo temporal direito.","C":"Lobo occipital.","D":"Lobo frontal inferior direito."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-273148","number":"273148","sourceNumber":"273148","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Quanto à hidrocefalia, é INCORRETO afirmar:","options":{"A":"Na hidrocefalia, ocorre o aumento anormal do fluido cefalorraquidiano dentro da cavidade\ncraniana, acompanhado de expansão dos ventrículos\ncerebrais, alargamento ósseo, sobretudo da\ntesta, e atrofia encefálica, de que resultam deficiência mental e convulsões.","B":"Na hidrocefalia, o fluido extra exerce pressão sobre o cérebro e pode causar danos cerebrais. É\nmais comum em crianças e idosos.","C":"O tratamento da hidrocefalia costuma ser realizado com a inserção cirúrgica de um tubo (shunt)\nem um ventrículo, para drenar o excesso de\nlíquido.","D":"O fluido extra exerce pressão sobre o cérebro e pode causar danos cerebrais. Ocorre apenas\nem crianças."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-257730","number":"257730","sourceNumber":"257730","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Leia o caso clínico a seguir. Uma mulher de 42 anos apresenta quadro súbito de\ncefaleia intensa e desesperadora, náuseas, vômitos e perda transitória da consciência durante a\nrelação sexual. No momento do atendimento, apresenta-se confusa, com rigidez de nuca e sem\ndéficits motores. Qual é a causa mais provável do quadro clínico desta paciente?","options":{"A":"Hemorragia subaracnoideia.","B":"Meningite viral.","C":"Hemorragia intracerebral.","D":"Hematoma extradural."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-257731","number":"257731","sourceNumber":"257731","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Para um paciente de 35 anos de idade com acidente vascular cerebral do tipo\nisquêmico, qual é o padrão-ouro para avaliar presença de forame oval patente?","options":{"A":"Doppler transcraniano com teste de microbolhas.","B":"Ecocardiograma transesofágico com teste de microbolhas.","C":"Ecocardiograma transtorácico com teste de microbolhas.","D":"Angiorressonância magnética de vasos cervicais."},"answer":"","answerPending":true,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-257937","number":"257937","sourceNumber":"257937","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente do sexo feminino, 40 anos, tem diagnóstico de asma desde a infância. Alega\nque há cerca de dois meses vem apresentando\nsintomas quase diários de tosse seca e chiado no\npeito que aliviam com uso de salbutamol. Alega acordar à noite com dispneia e chiado no peito pelo\nmenos uma vez por semana. Faz uso de formoterol/budesonida 12/400 mcg três vezes ao dia,\nbrometo tiotrópio (dois jatos cedo), montelucaste 10 mg à noite. Refere que não esquece as\nmedicações. Faz uso adequado e técnica correta. Alega que tem um cachorro e um gato que ficam\ndentro do seu quarto. Queixa de epigastralgia e pirose frequentes, espirros e pruridos nasal várias\nvezes ao dia, desencadeados por contato com poeira, mofo e fumaça. Alega roncos durante a\nnoite, com episódios de apneia visto por marido, sonolência diurna excessiva. Tem HAS, faz uso de\nenalapril. Nega tabagismo. Ao exame: IMC 30 kg/m², spO? 98%. Em bom estado geral, eupneica,\nvigil. Ausculta pulmonar: sem outras alterações. Exames complementares: IGE 550, hemograma\neosinófilos 6% (690), raio X tórax sem alterações. Espirometria: pré broncodilatador: CVF 4,30\n(82%), VEF1 2,97 (70%), VEF1/ CVF 0,68; pós broncodilatador: CVF 4,95 (95%), VEF1 3,39 (85%),\n\nVEF1/CVF 0,80. De acordo com o fenótipo, como pode ser melhor classificada essa paciente?","options":{"A":"Asma alérgica.","B":"Asma paucicelular.","C":"Asma neutrofílica.","D":"Asma alérgica eosinofílica."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-265891","number":"265891","sourceNumber":"265891","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O envelhecimento é fator risco para a maioria das Doenças Cardiovasculares, assim\ncomo de inúmeras comorbidades, tornando os idosos o grupo etário de maior heterogeneidade e\ncomplexidade. Podemos assim CONCORDAR que:","options":{"A":"De forma geral, o sistema de saúde é mal preparado para assistir pacientes portadores de\nmultimorbidades, visto que necessitam de uma individualização menor e assistência por equipe\nmultiprofissional trabalhando de forma integrada.","B":"De forma geral, o sistema de saúde é mal preparado para assistir pacientes portadores de\nmultimorbidades, visto que necessitam de uma individualização ainda maior e assistência por\nequipe multiprofissional trabalhando de forma integrada.","C":"De forma geral, o sistema de saúde é mal preparado para assistir pacientes portadores de\nmultimorbidades, visto que não necessitam de uma individualização ainda maior e assistência por\nequipe multiprofissional trabalhando de forma integrada.","D":"De forma geral, o sistema de saúde é mal preparado para assistir pacientes portadores de\nmultimorbidades, visto que necessitam de uma individualização ainda maior e assistência por\nequipe multiprofissional trabalhando de forma segmentada."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-265892","number":"265892","sourceNumber":"265892","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Podemos considerar que existe uma superposição, mas não uma concordância na\nocorrência de fragilidade, incapacidade e multimorbidade (coexistência de duas ou mais doenças\ncrônicas). Assim podemos indicar como CORRETO que:","options":{"A":"Embora seja mais frequente, existem indivíduos frágeis sem incapacidade e sem a presença de\nmultimorbidade.","B":"Inexistem indivíduos frágeis sem incapacidade e sem a presença de multimorbidade.","C":"Embora seja menos frequente, existem indivíduos frágeis sem incapacidade e sem a presença\nde multimorbidade.","D":"Embora seja menos frequente, existem indivíduos frágeis com incapacidade e nunca sem a\npresença de multimorbidade."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-281316","number":"281316","sourceNumber":"281316","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Os indivíduos idosos com diabetes têm risco aumentado para desenvolvimento das\nsíndromes geriátricas, sendo correto o item:","options":{"A":"Tais como polifarmácia, déficit cognitivo, incontinência urinária, quedas e dor crônica; os\nindivíduos com estas síndromes que desenvolvem diabetes têm seu quadro agravado.","B":"Tais como polifarmácia, déficit cognitivo, incontinência urinária, quedas e dor crônica; os\nindivíduos com estas síndromes que desenvolvem diabetes têm seu quadro melhorado.","C":"Tais como polifarmácia, déficit cognitivo, incontinência urinária, quedas e dor crônica; os\nindivíduos com estas síndromes que não desenvolvem diabetes têm seu quadro agravado.","D":"Tais como polifarmácia, déficit cognitivo, incontinência urinária, quedas e não a dor crônica; os\nindivíduos com estas síndromes que desenvolvem diabetes têm seu quadro agravado."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-265900","number":"265900","sourceNumber":"265900","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A Avaliação Geriátrica Ampla (AGA) prioriza o estado funcional e a qualidade de vida,\nutilizando instrumentos de avaliação, facilitando a comunicação entre os membros da equipe\ninterdisciplinar. Somente NÃO podemos concordar que:","options":{"A":"Deve ser aplicada aos idosos frágeis e portadores de multimorbidades.","B":"A AGA é também é um importante preditor de desfechos desfavoráveis, ou seja, não tem valor\nprognóstico, para pacientes cirúrgicos, oncológicos e ortopédicos.","C":"A AGA é fundamental no contexto da avaliação do idoso.","D":"Apresenta quatro principais dimensões, que são a capacidade funcional, as condições médicas,\no funcionamento social e a saúde mental."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-274812","number":"274812","sourceNumber":"274812","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Dona Maria Inês, 92 anos, está acamada, totalmente dependente para atividades\ndiárias, confusa, com quadro avançado de\nAlzheimer. É obesa, hipertensa (em uso de Anlodipina,\nPropranolol e Losartana), diabética (em uso de Metformina e Glicazida), além de tomar medicações\npara dislipidemia (Sinvastatina), hipotiroidismo (Puran T4), insuficiência venosa (Diosmina -\nHesperidina) e labirintite (Betaistina). Faz uso, ainda, de medicações para o Alzheimer (Memantina\ne Galantamina) e de um remédio para dormir (Bromazepam). A família da paciente solicitou uma\nvisita domiciliar de rotina, e a principal queixa foi a alimentação inadequada de dona Maria Inês,\nque não está aceitando nada além de pizza e empadas. Você, como médico da Atenção Primária\nque acompanha esta paciente, deve ter como principal foco de atenção durante a consulta da\npaciente, e como conduta mais adequada, respectivamente:","options":{"A":"a questão nutricional, pois a alimentação inadequada pode resultar em descontrole dos quadros\njá apresentados, deve ser encaminhada ao\nNutricionista.","B":"a polifarmácia, pois a interação medicamentosa pode levar a outras comorbidades; devem ser\nmantidos apenas os medicamentos para Hipertensão Arterial e diabetes mellitus, com suspensão\nde todos os outros.","C":"a qualidade de vida da paciente, pois pela idade e quadro clínico ela se encaixa em perfil para\ncuidados paliativos; deve ser incentivada a oferta de alimentos que ela goste, como pizza e\nempadas.","D":"o uso do Bromazepam, pois piora o risco de quedas e pode estar contribuindo para a confusão\nmental da paciente; deve ser suspensa a medicação imediatamente."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-282032","number":"282032","sourceNumber":"282032","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O MINIMENTAL (Miniexame do Estado Mental) é utilizado comumente na consulta\nmédica em Atenção Primária à Saúde, e tem por excelência, EXCETO:","options":{"A":"Instrumento de rastreio.","B":"Pode ser usado isoladamente para diagnóstico das síndromes demenciais.","C":"Permite quantificação do declínio cognitivo e sugere quais funções cognitivas estão\ncomprometidas.","D":"Avalia todas as funções cognitivas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-281325","number":"281325","sourceNumber":"281325","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"No idoso, a indicação de tratamentos exige mais cautela, as metas terapêuticas são\nmenos precisas, porém sonegá-las apenas devido\nà idade implica omissão. Sendo correto o item:","options":{"A":"As decisões não devem ser compartilhadas e é necessário considerar a relação risco/benefício e\na expectativa de vida.","B":"As decisões devem ser compartilhadas e é desnecessário considerar a relação risco/benefício e\na expectativa de vida.","C":"As decisões devem ser compartilhadas e é necessário considerar a relação risco/benefício e a\nexpectativa de vida.","D":"As decisões devem ser compartilhadas e é necessário considerar a relação risco/benefício e não\na expectativa de vida."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-282037","number":"282037","sourceNumber":"282037","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A manutenção da função é uma meta fundamental dos cuidados geriátricos e um\nelemento importante do envelhecimento\nbem-sucedido. Assim como outras síndromes geriátricas, o\ndeclínio funcional é multifatorial; fatores médicos, psicológicos, sociais e ambientais podem\ncontribuir para o comprometimento do estado funcional. As informações sobre o estado funcional\nsão importantes para o planejamento e monitorização das respostas à terapia e para determinação\ndo prognóstico. A funcionalidade global é o ponto de partida de qualquer avaliação e deve ser\nabrangente, contemplando a coleta de informações sobre Atividades de Vida Diária: Básicas,\nInstrumentais e Avançadas. Sobre funcionalidade: I. A primeira a ser perdida é a atividade de Vida\nDiária BÁSICA. II. Banho, vestir-se, higiene pessoal, transferência, continência, alimentação fazem\nparte de atividades BÁSICAS de Vida Diária. III. Fazer compras no mercado, faxinar a casa,\npreparar a comida, organizar as finanças no lar e saber os horários das medicações fazem parte de\natividades INSTRUMENTAIS da vida diária. IV. Atividades ocupacionais, atividades sociais,\nparticipação na comunidade, atividades recreativas, direção veicular, desempenho de papéis na\nfamília como, por exemplo, cuidador fazem parte das atividades AVANÇADAS da vida diária.","options":{"A":"Todas estão corretas.","B":"I e II estão corretas.","C":"II, III e IV estão corretas.","D":"Todas estão erradas."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-281327","number":"281327","sourceNumber":"281327","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Nos idosos os tratamentos farmacológicos devem priorizar condições e restringir o\nnúmero de medicamentos, sendo adequado o item:","options":{"A":"Não simplificar a posologia, avaliar e estimular a adesão insatisfatória até na prevenção\nsecundária após IAM e orientar sobre os problemas da automedicação.","B":"Simplificar a posologia, avaliar e estimular a adesão insatisfatória até na prevenção secundária\napós IAM e não orientar sobre os problemas\nda automedicação.","C":"Simplificar a posologia, avaliar e estimular a adesão insatisfatória até na prevenção secundária\napós IAM e orientar sobre os problemas de\nnão realizar a automedicação.","D":"Simplificar a posologia, avaliar e estimular a adesão insatisfatória até na prevenção secundária\napós IAM e orientar sobre os problemas da\nautomedicação."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-274538","number":"274538","sourceNumber":"274538","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A presença do idoso na atenção primária está cada vez mais prevalente, como reflexo\ndo aumento da expectativa de vida de toda\npopulação brasileira. o médico de mfc, por isso,\nnecessita cada vez mais de conhecimentos sobre essa faixa etária. O diagnóstico provável de\ndoença de alzheimer inclui, EXCETO:","options":{"A":"Início insidioso.","B":"Piora cognitiva.","C":"Apresentação simultânea de alucinações visuais, parkinsonismo e flutuações cognitivas.","D":"Piora da linguagem."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-229493","number":"229493","sourceNumber":"229493","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A Espessura Médio-Intimal (EMI) da Ultrassonografia Vascular é caracterizada, ao\nmodo bidimensional, por uma dupla linha com definição\ndas interfaces lúmen-íntima e\n\nmédia-adventícia. Indique o item ERRADO:","options":{"A":"A Placa Carotídea (PC) ateromatosa pode ser definida como uma estrutura focal estendendo-se\nno mínimo 0,5 mm para o lúmen do vaso.","B":"A Placa Carotídea (PC) ateromatosa pode ser definida como medindo mais do que 50% do valor\nda medida da EMI adjacente.","C":"A distância entre as duas interfaces acústicas não é considerada a medida da EMI.","D":"A Placa Carotídea (PC) ateromatosa pode ser definida pela medida de EMI > 1,5 mm."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-246527","number":"246527","sourceNumber":"246527","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente feminino, 57 anos, obesa, com peso de 120 kg, diabética em tratamento\nirregular com metformina 850 mg/dia. Durante\nrefeição matinal, perdeu de forma súbita força em\ndimidio esquerdo. Recebida no serviço de urgência com PA = 215x145, FC = 110 bpm, hemiplegia\nà esquerda, paralisia facial esquerda. Após avaliação inicial, a TC de crânio foi normal. I. Deve\nser\nindicada a trombólise o mais precoce possível, quando o tempo do ictus for inferior a 4,5 horas,\nexcluindo as contraindicações absolutas. II. Nos acidentes vasculares encefálicos a pressão arterial\nsistólica acima de 185 e diastólica acima de 110 contraindicam trombólise, quando refratária. III. A\ndose do rtPA é de 0,9 mg/kg, não exercendo 90 mg, devendo ser infundido 10% em bolus em 1\nminuto e o restante em 30 minutos. Pode-se afirmar que apenas:","options":{"A":"o item I está certo.","B":"o item II está certo.","C":"o item III está certo.","D":"os itens I e II estão certos.","E":"os itens II e III estão certos."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-232216","number":"232216","sourceNumber":"232216","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O grau do comprometimento neurológico e a extensão do sangramento subaracnóideo\nno momento da admissão são os preditores mais\nimportantes das complicações neurológicas e do\ndesfecho clínico. Portanto, é imperativo graduar a severidade da hemorragia subaracnóidea tão\nlogo seja possível, após a estabilização dos pacientes com esse quadro. Um paciente que se\nencontra sonolento ou confuso com déficit neurológico focal leve apresenta um escore na escala de\nHunt e Hess de:","options":{"A":"1.","B":"2.","C":"3.","D":"4."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-241700","number":"241700","sourceNumber":"241700","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Mulher de 38 anos atendida no pronto-atendimento com cefaleia occipital súbita e\nprimeiro episódio de convulsão. História prévia\nde obesidade, em uso de anticoncepcional oral.\nExame neurológico: pressão arterial 130x100mmHg; escala de coma de Glasgow 14; desorientada;\nrigidez nucal ++/++++; força muscular normal. Solicitada tomografia computadorizada do crânio\ncom injeção de contraste. O diagnóstico mais provável é:","options":{"A":"hemorragia subaracnoidea espontânea.","B":"trombose venosa cerebral.","C":"hipertensão intracraniana idiopática.","D":"acidente vascular cerebral isquêmico.","E":"hemorragia intraparenquimatosa cerebral."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-12/241700.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-254224","number":"254224","sourceNumber":"254224","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O diagnóstico de demência de Alzheimer pode não ser absolutamente fácil. É sempre\nnecessário descartar a possibilidade de pseudodemência e demências secundárias. Para esses\ndiagnósticos diferenciais, é necessário descartar, EXCETO:","options":{"A":"Depressão.","B":"Hipotireoidismo.","C":"Deficiência de vitamina D.","D":"Uso de fármacos anticolinérgicos."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-249854","number":"249854","sourceNumber":"249854","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente do sexo masculino, de 66 anos, comparece ao pronto atendimento com\nqueixa de paresia em andar inferior da face esquerda e também de membro superior esquerdo.\nQual é a melhor conduta inicial para o caso?","options":{"A":"Administrar dose de ataque de ácido acetilsalicílico.","B":"Realizar tomografia computadorizada de crânio, sem contraste.","C":"Administrar trombolítico endovenoso.","D":"Realizar trombectomia mecânica."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-229511","number":"229511","sourceNumber":"229511","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O critério anatômico em especial das estenose baseia-se na avaliação da redução\nluminal e deve ser usado para caracterizar\nImagem Cardiovascular de Ultrassonografia Vascular.\nPodemos APENAS aceitar o item:","options":{"A":"A avaliação anatômica não pode ser prejudicada em circunstâncias como calcificação arterial\ncom sombra acústica.","B":"A avaliação anatômica pode ser prejudicada em circunstâncias como calcificação arterial com\nsombra acústica, ajustes inadequados do equipamento, entre outros.","C":"A avaliação anatômica pode ser prejudicada em circunstâncias como calcificação arterial sem a\nsombra acústica, somente por ajustes inadequados do equipamento, entre outros.","D":"A avaliação anatômica pode ser prejudicada em circunstâncias como descalcificação arterial\nsem a sombra acústica, por ajustes inadequados do equipamento, entre outros."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-234325","number":"234325","sourceNumber":"234325","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual é a melhor maneira de prevenir AVC isquêmico em um homem de 60 anos, obeso,\nsedentário, sem outras comorbidades e com fibrilação atrial paroxística?","options":{"A":"Aspirina.","B":"Warfarin.","C":"Rivaroxabana.","D":"Mudanças do estilo de vida."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-247409","number":"247409","sourceNumber":"247409","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 74 anos, sexo masculino, vai até o ambulatório geral referindo tremor em\nrepouso que alivia com o movimento, instabilidade postural, bradicinesia e rigidez. O filho que o\nacompanha, relata prejuízo de memória, comprometimento da atenção e função executiva. Sobre o\ntratamento desta condição:","options":{"A":"a L-dopa é a mais potente medicação antiparkinsoniana, com bom perfil de segurança e deve\nser iniciada em todos os pacientes assim que o\ndiagnóstico é feito.","B":"pacientes com doença moderadamente avançada e idade acima de 70 anos respondem bem\naos anticolinérgicos muscarínicos, como o\nbiperideno.","C":"inibidores da monoaminoxidase B (iMAO-B), como a selegilina, apresentam efeito sintomático\ndiscreto e são eficazes como monoterapia na\nfase inicial da doença.","D":"sintomas demenciais associados respondem bem a doses baixas de antagonistas atípicos da\ndopamina, como olanzapina ou quetiapina."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-248925","number":"248925","sourceNumber":"248925","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Um paciente de 68 anos, hipertenso de longa data, tabagista por 50 anos e com\ndiabetes mellitus diagnosticado há 20 anos,\nchega ao serviço de pronto atendimento com relato de\nque, ao ter iniciado atividade física com membro superior esquerdo, apresentou tonteira seguida\npor síncope e que não se recorda bem do que aconteceu. Os acompanhantes informaram que ele\napresentou fala arrastada e desvio da comissura labial. Porém, após 6 horas de observação no\nserviço de pronto atendimento, todas as alterações já haviam se normalizado. Foram solicitados, à\nadmissão, glicemia capilar, que revelou 86mg/dL; tomografia computadorizada do encéfalo, que se\nmostrou normal; duplex scan de carótidas e vertebrais, que revelou ateromatose carotídea bilateral\ncom placas ulceradas, com inversão de fluxo sisto/diastólico, contínuo, em artéria vertebral\nesquerda. A artéria vertebral direita apresentava-se com fluxo ascendente, com velocidade normal.\nO diagnóstico mais provável para a situação clínica aguda apresentada pelo paciente é:","options":{"A":"ataque cerebral hipoglicêmico","B":"acidente vascular encefálico hemorrágico","C":"acidente vascular encefálico trombótico","D":"ataque isquêmico cerebral transitório"},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-232235","number":"232235","sourceNumber":"232235","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Qual dos fatores a seguir melhor prediz prognóstico para pacientes com hemorragia\nsubaracnóidea aguda?","options":{"A":"Localização do aneurisma roto.","B":"Nível de consciência do paciente à admissão hospitalar.","C":"Idade do paciente.","D":"Presença de outras comorbidades clínicas."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-232236","number":"232236","sourceNumber":"232236","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Paciente de 64 anos, do sexo feminino, com funcionalidade neurológica preservada até\nentão, que estava em Barra do Garças-MT, apresentou quadro súbito de hemiplegia esquerda,\nheminegligência, desvio tônico do olhar, sem perda de consciência. Antecedente de hipertensão\narterial sistêmica, bem controlada, e tabagismo. Chega ao pronto atendimento em Goiânia-GO com\nnove horas de início dos sintomas. Ao exame físico: NIHSS 16 e estabilidade hemodinâmica (PA\n145 x 92 mmHg); hemoglicoteste 110 mg/dl. Tomografia computadorizada de crânio sem contraste\nnão evidencia lesões agudas. Há disponibilidade de neuroimagem multimodal. Diante do caso, a\nconduta de urgência mais associada à reversão de sintomas e melhora de prognóstico em 90 dias\né:","options":{"A":"Neuroimagem multimodal e, se presença de oclusão de grandes vasos, trombectomia mecânica.","B":"Cuidados de UTI e craniectomia descompressiva em até 24 horas de início de sintomas.","C":"Neuroimagem multimodal e, se presença de oclusão de grandes vasos, trombólise endovenosa.","D":"Observação em sala de urgência e manejo pressórico e glicêmico rigorosos."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-252758","number":"252758","sourceNumber":"252758","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em relação à doença de Parkinson, marque a alternativa INCORRETA:","options":{"A":"Caracteriza-se por tremor de repouso, rigidez, bradicinesia e comprometimento da marcha.","B":"Do ponto de vista patológico, caracteriza-se por degeneração dos neurônios dopaminérgicos da\nsubstância negra.","C":"Para a confirmação do diagnóstico, a tomografia por emissão de pósitrons deve ser realizada.","D":"A levodopa é a medicação de escolha para o tratamento."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-231972","number":"231972","sourceNumber":"231972","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"O rastreamento de câncer é uma importante ação de prevenção. Entretanto, os\nbenefícios da implantação do programa de\nrastreamento populacional devem ser cuidadosamente\navaliados. São critérios para a implantação de um programa de rastreamento populacional de\ncâncer, exceto:","options":{"A":"transcendência, magnitude e vulnerabilidade da doença","B":"custo-efetividade favorável","C":"estagio pré-clínico bem definido da doença","D":"exames de rastreamento disponíveis, aceitáveis e confiáveis","E":"realização de triagem por meio de mutirões"},"answer":"E","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-231973","number":"231973","sourceNumber":"231973","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Os rastreamentos (screenings) são utilizados em Saúde Pública para o diagnóstico\nprecoce de doenças e, consequentemente, o\ntratamento oportuno de doenças. Em relação a esses\nprocedimentos e suas aplicações em Saúde Pública, assinale a alternativa incorreta:","options":{"A":"o rastreamento deve ser de baixo custo e com o menor risco possível à população rastreada,\npois podem ser prejudiciais no âmbito\npopulacional ao levar a investigações invasivas nem sempre\ninócuas","B":"o rastreamento, mais conhecido como checkup, visa ao diagnóstico precoce de doenças e deve\nincluir as doenças para as quais se dispõe de métodos diagnósticos","C":"o valor preditivo positivo baixo e a baixa frequência das doenças dificultam rastreamentos para\nmuitas doenças","D":"o tratamento precoce da doença rastreada deve ser capaz de reduzir seus desfechos\ndesfavoráveis","E":"o rastreamento deve contemplar doenças de alta prevalência e elevadas morbidade e\nmortalidade"},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-249501","number":"249501","sourceNumber":"249501","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Sobre isquemia cerebral de origem extracraniana, marque a correta:","options":{"A":"A arterite de Takayasu pode levar a isquemia cerebral extracraniana, sendo mais comum em\nhomens a partir da sexta década de vida.","B":"A aterosclerose não é causa comum de ataque isquêmico transitório e de acidente vascular\ncerebral.","C":"Na displasia fibromuscular a cirurgia de endarterectomia de carótidas é sempre o melhor\ntratamento.","D":"A displasia fibromuscular ocorre mais frequentemente em pacientes do sexo feminino."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-249502","number":"249502","sourceNumber":"249502","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"A endarterectomia de carótida é uma cirurgia consagrada no tratamento da isquemia\ncerebral de origem extracraniana. Sobre suas complicações, é correto afirmar:","options":{"A":"A microembolização cerebral pode levar a acidente vascular encefálico isquêmico.","B":"A lesão intra-operatória do nervo vago causa alteração motora de metade da língua.","C":"A lesão do nervo hipoglosso pode levar a regurgitações alimentares, com broncoaspiração e\npneumonia de repetição.","D":"O ramo mandibular do nervo facial quando lesado leva a dificuldade em emitir notas de timbre\nagudo e resulta em fatigabilidade da voz."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-229857","number":"229857","sourceNumber":"229857","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Os cuidados paliativos, segundo a Organização Mundial de Saúde (2002), \"consistem\nna assistência promovida por uma equipe\nmultidisciplinar, que objetiva a melhoria da qualidade de\nvida do paciente e seus familiares, diante de uma doença que ameace a vida, por meio da\nprevenção e alívio do sofrimento, da identificação precoce, avaliação impecável e tratamento de dor\ne demais sintomas físicos, sociais, psicológicos espirituais\". Mesmo com esta definição abordada\ninternacionalmente, ainda é comum ver profissionais que interpretam os cuidados paliativos como\n\"não ter nada para fazer\", o que é incorreto, visto que o foco é melhorar as condições de vida de\nqualquer um que esteja sob estes cuidados. Ademais, alguns autores e sistemas de saúde\ninterpretam que a maior parte dos pacientes em paliativismo deverão ter seus cuidados divididos\nem diferentes níveis de atenção, sendo a Atenção Primária à Saúde responsável por grande parte\ndos mesmos. Agora, imagine que você é médica(o) do senhor Alberto, de 74 anos, com câncer de\npróstata com metástases para pulmões e fígado. Durante uma visita domiciliar, realizada devido à\ncaquexia, ascite e uso contínuo de oxigenioterapia domiciliar, você percebe que Alberto está muito\nincomodado com a dispneia, que diz persistir a despeito do uso do O2. Dentre das opções abaixo,\na melhor opção de tratamento para o sintoma referido pelo paciente é","options":{"A":"a morfina.","B":"o haloperidol.","C":"a amitriptilina.","D":"a fluoxetina."},"answer":"A","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-229858","number":"229858","sourceNumber":"229858","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Os cuidados paliativos, segundo a Organização Mundial de Saúde (2002), \"consistem\nna assistência promovida por uma equipe\nmultidisciplinar, que objetiva a melhoria da qualidade de\nvida do paciente e seus familiares, diante de uma doença que ameace a vida, por meio da\nprevenção e alívio do sofrimento, da identificação precoce, avaliação impecável e tratamento de dor\ne demais sintomas físicos, sociais, psicológicos espirituais\". Mesmo com esta definição abordada\ninternacionalmente, ainda é comum ver profissionais que interpretam os cuidados paliativos como\n\"não ter nada para fazer\", o que é incorreto, visto que o foco é melhorar as condições de vida de\nqualquer um que esteja sob estes cuidados. Ademais, alguns autores e sistemas de saúde\ninterpretam que a maior parte dos pacientes em paliativismo deverão ter seus cuidados divididos\nem diferentes níveis de atenção, sendo a Atenção Primária à Saúde responsável por grande parte\ndos mesmos. O Sistema Único de Saúde, criado pela lei nº 8.080/90, foi tema da revista científica\nThe Lancet por meio do artigo \"Brazil's unified health system: the first 30 years and prospects for\nthe future\". Neste texto, os autores concluem que: \"A expansão do SUS permitiu ao Brasil atender\nrapidamente às mudanças nas necessidades de saúde da população, com um aumento dramático\nda cobertura dos serviços de saúde em apenas três décadas. No entanto, apesar de seus\nsucessos, a análise de cenários futuros sugere a necessidade urgente de enfrentar desigualdades\ngeográficas persistentes, financiamento insuficiente e colaboração abaixo do ideal entre os setores\npúblico e privado.\" (CASTRO et al., 2019). Um dos instrumentos existentes para se lidar com as\niniquidades geográficas apontadas pelo texto é a limitação de quantidade de pessoas por equipe da\nEstratégia de Saúde da Família, por meio de área delimitada e de responsabilidade sanitária. A\nesta área geográfica se dá o nome de","options":{"A":"área de influência.","B":"área de abrangência.","C":"território.","D":"microárea."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-246574","number":"246574","sourceNumber":"246574","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Em crianças, diferentemente dos adultos, os derrames são produzidos por uma gama\nde distúrbios. Sobre os acidentes vasculares\ncerebrais (AVC) em pediatria, julgue os seguintes\nitens. I. Nos AVC's isquêmicos de origem arterial, as arteriopatias são a principal causa, presentes\nem mais da metade dos pacientes. II. Os derrames perinatais são mais comuns que aqueles\nocorridos em fases tardias da infância; entretanto, suas manifestações podem ser precoces, 24 a\n48 horas após o nascimento, ou tardias, ao fim do primeiro ano de vida. III. Um dos tratamentos\npreconizados consiste em anticoagulação, independentemente de a causa ser arterial ou venosa.\nEssa terapêutica mostrou benefícios nos derrames ocorridos em todas as faixas etárias pediátricas.\nAssinale a alternativa correta.","options":{"A":"Todos os itens estão certos.","B":"Nenhum item está certo.","C":"Apenas os itens I e II estão certos.","D":"Apenas os itens I e III estão certos.","E":"Apenas o item I está certo."},"answer":"C","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-247453","number":"247453","sourceNumber":"247453","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"João de 45 anos compareceu à consulta com a Médica de Família e Comunidade Dra.\nMaria. Ao revisar o prontuário, não há relato de doenças crônicas diagnosticadas, cirurgias prévias\nou alergia a medicamentos. Dra. Maria descobre que João é casado com Josefa, não é tabagista\nou etilista, trabalha como motorista de ônibus e não tem um horário definido para as refeições,\ndevido às escalas variáveis. João quer \"fazer exames\", pois está preocupado que nos últimos\nmeses \"faz muito xixi, bebe muita água e come mais ainda\". Maria pergunta como isso atrapalha\nsua vida e o que João acredita está causando esses sintomas. João refere incômodo por ter que\nparar o ônibus várias vezes para ir ao banheiro e por acordar muitas vezes à noite. Acredita que\nisso seja \"câncer na próstata\" e quer fazer \"exame do toque\". No final da consulta, Maria explica\nque existe uma grande possibilidade de João ter diabetes mellitus e orienta que não existe\nindicação para realizar \"exame de próstata\". Considerando o caso acima, marque a afirmação\ncorreta:","options":{"A":"no trecho em negrito (\"\"Dra. Maria descobre...\"\") Dra. Maria está aplicando o seguinte\ncomponente do método clínico centrado na\npessoa: Explorando a doença e a experiência da\npessoa com a doença.","B":"ao orientar que não existe indicação para realizar \"\"exame de próstata\"\", Dra. Maria está\npraticando prevenção secundária.","C":"Maria não deveria ter perguntado o que João acredita está causando seus sintomas, já que isso\nnão tem implicação para o tratamento e não faz parte do Método Clínico Centrado na Pessoa.","D":"no trecho \"\"Dra. Maria pergunta como isso atrapalha sua vida e o que João acredita está\ncausando esses sintomas\"\" está abordando duas\ndimensões da experiência da pessoa com a\ndoença: funcionalidade e ideias. A abordagem dessas dimensões faz parte do componente\n\"\"Explorando a doença e a experiência da pessoa com a doença\"\" do Método Clínico Centrado na\nPessoa."},"answer":"D","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-12-247458","number":"247458","sourceNumber":"247458","collectionBlock":"med:med-clinica-medica-med-clm-12","collectionLabel":"MED · MED CLM 12","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 12","subtopic":"","stem":"Dona Filomena de 81 anos, recebeu alta hospitalar há 3 dias, com orientação para\nCuidados Paliativos em casa. Esteve internada\npor 3 meses para tratamento de um Câncer de\nCólon de Útero com metástases em pulmão. Hoje recebe a visita da nutricionista, a pedido da\nfamília, devido à recusa absoluta em se alimentar. A profissional, após anamnese e exame físico\ncompleto, faz uma dieta detalhada e balanceada para a paciente, considerando a necessidade\ncalórica e as restrições alimentares devido à diabetes mellitus que a paciente apresenta, e orienta\na\nfamília quanto à possibilidade de dieta via sonda caso persista a recusa em se alimentar. Orienta\nainda sobre a importância de uma hidratação adequada. Dona Filomena está lúcida, desorientada\n(1+/4), levemente desidratada. Nega dor e refere apenas vontade de comer \"pudim\". Considerando\nos princípios dos Cuidados Paliativos é correto afirmar que a nutricionista:","options":{"A":"tem uma conduta adequada, pois é importante considerar as restrições alimentares relacionadas\ncom as doenças de base e o aporte calórico\ndeve ser adequado em síndromes consumptivas.","B":"não está correta, pois pode haver vantagens em diminuir o aporte nutricional e de hidratação, e\num certo grau de desidratação está, inclusive, associado a um melhor controle da dor, devido à\nliberação de opiides endógenos.","C":"está se baseando nos Cuidados Centrados no Paciente, ao fazer uma dieta personalizada de\nacordo as necessidades da paciente no momento atual da doença.","D":"não está correta em orientar a possibilidade de sorida, já que a via preferencial para o suporte\nnutricional em uma paciente lúcida e não receptiva à dieta é a parenteral."},"answer":"B","answerPending":false,"source":"Clinica médica/MED CLM 12/MED CLM 12.txt","sourceLabel":"MED · MED CLM 12","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 12","MED"],"answerSource":"explicit","commentDeferred":true}]};
